// 马原题目深度解析，由 scripts/bank/merge_annotations.py 生成。
module.exports = {"20001":{"solution":"题干追问的是马克思主义的阶级属性。它公开申明为无产阶级解放服务，把科学性与阶级性统一于一身，因此只能落在“无产阶级思想的科学体系”上，其余三项都错在把主体范围放宽或换了对象。","optionAnalysis":{"A":"马克思主义公开申明为无产阶级服务，是无产阶级争取自身解放的思想体系，主体与题干要求的阶级属性完全吻合。","B":"“人民大众”外延包含多个阶级，掩盖了马克思主义鲜明的阶级属性，教材定义的落脚点是无产阶级而非一般民众。","C":"革命阶级范围过宽，资产阶级在反封建时期也曾是革命阶级，用它界定会抹掉马克思主义的阶级属性。","D":"政党是政治组织而非思想体系，马克思主义是党的指导思想，但不能反过来把它定义为“革命政党思想的体系”。"},"memoryTip":"记“无产阶级＋科学”两个词：阶级属性只认无产阶级，不可扩大成人民大众。"},"20002":{"solution":"题目问“广义”，关键在范围大小。广义马克思主义不限于马克思恩格斯的原创理论，还包括后来继承者的丰富和发展；狭义才只算创始人那一部分，抓住是否包含继承者即可判定。","optionAnalysis":{"A":"明确把创始人的基本理论、基本观点和学说同继承者的发展一并纳入，外延最宽，正合“广义”的要求。","B":"讲的是无产阶级争取解放的使命，属于理论内容的表述，没有回答范围宽窄这一设问。","C":"这是对无产阶级斗争性质、目的和解放条件的说明，仍属理论内容，未界定广义的外延。","D":"只限于马克思和恩格斯创立的理论观点和方法，恰恰是狭义马克思主义的界定。"},"memoryTip":"广义看“继承者发展”，狭义只算马恩原创，判题先看有没有“后来发展”。"},"20003":{"solution":"与上题相对，狭义要同时卡死“创始人”和“阶级属性”两个条件。马克思和恩格斯共同创立，服务于无产阶级解放，少一人或丢掉阶级属性都不完整，只有该项二者兼备。","optionAnalysis":{"A":"只提马克思一人，把共同创立的恩格斯排除在外，创始人范围不完整。","B":"用“时代”划界，等于把马克思主义封闭在十九世纪，既否认其后续发展，也没点出阶级属性。","C":"既点明马克思恩格斯两人共同创立，又明确其无产阶级属性，与狭义界定完全对应。","D":"强调在实践中不断发展的马克思主义，属于广义的、开放的界定，与“狭义”正相反。"},"memoryTip":"狭义＝“马恩两人＋无产阶级”，缺恩格斯或丢阶级属性都要排除。"},"20004":{"solution":"注意题干四个字“经济社会历史条件”。资本主义经济发展使社会化生产与私有制的矛盾充分展开，为马克思主义提供物质基础；阶级斗争激化属阶级基础，科技进步属科学前提，必须对号入座。","optionAnalysis":{"A":"科学技术的发展是马克思主义产生的自然科学前提，不属于经济社会的历史条件。","B":"资本主义经济发展使资本主义固有矛盾充分暴露，构成马克思主义产生的经济社会历史条件。","C":"无产阶级反对资产阶级斗争日益激化是阶级基础，与“经济社会历史条件”不在同一层次。","D":"工人阶级登上历史舞台同样属于阶级基础的范畴，不是经济条件。"},"memoryTip":"三条件分家：资本主义经济发展＝经济社会条件，斗争激化＝阶级基础，自然科学＝科学前提。"},"20005":{"solution":"三大组成部分各有定位：哲学提供世界观和方法论，是整体理论的基础；政治经济学负责论证；科学社会主义是核心和归宿。题干问“基础部分”，只能落到哲学。","optionAnalysis":{"A":"马克思主义哲学揭示自然、社会和思维发展的一般规律，为整个理论体系提供世界观和方法论基础。","B":"政治经济学是对马克思主义最深刻的证明和运用，处于论证环节，不能同时充当基础。","C":"科学社会主义是马克思主义的核心和目的归宿，位置在顶端而非底层。","D":"人类学不属于马克思主义三大组成部分，教材中没有这种划分。"},"memoryTip":"三位一体定位：哲学是基础、政经是证明、科社是核心，问基础就答哲学。"},"20006":{"solution":"“经济根源”要往生产方式内部找。资本主义社会生产力和生产关系的矛盾运动是推动一切社会现象的根本动因，工业革命、经济危机只是这一矛盾的表现或结果，阶级斗争属于阶级领域。","optionAnalysis":{"A":"工业革命是生产力飞跃的标志和推动力量，本身是矛盾运动的表现，不是最终根源。","B":"经济危机是资本主义基本矛盾周期性爆发的结果，用结果解释根源，因果倒置。","C":"生产力和生产关系的矛盾运动是社会发展的根本动力，正是马克思主义产生的经济根源。","D":"阶级斗争属于政治和阶级层面的条件，它推动理论的产生，但回答的是阶级基础问题，不属于经济根源。"},"memoryTip":"见“根源”找“矛盾运动”，生产力与生产关系的矛盾才是总根子。"},"20007":{"solution":"阶级基础要看无产阶级自身的发展程度。十九世纪三四十年代工人运动兴起，无产阶级作为独立政治力量登上历史舞台，科学理论才有了物质承担者；经济发展、科技进步都不属于阶级范畴。","optionAnalysis":{"A":"科学技术发展属于自然科学前提和认识条件，回答的是理论何以可能，不是阶级基础。","B":"资本主义经济发展是经济社会历史条件，与阶级基础不同层次。","C":"无产阶级反对资产阶级的斗争日益激化，表明无产阶级成为独立政治力量，正是阶级基础。","D":"机器大工业发展是生产力条件，为阶级形成提供物质前提，本身不等于阶级基础。"},"memoryTip":"阶级基础锁定“工人运动高涨、无产阶级独立登场”，其余都是前提不是基础。"},"20008":{"solution":"“看不见的手”是斯密论述市场机制时的比喻，指个人逐利在市场自发引导下促进社会利益。马克思虽然科学揭示了价值规律的自发调节作用，但这一提法出自古典经济学，故归斯密。","optionAnalysis":{"A":"马克思科学揭示了价值规律的内容和作用机制，但“看不见的手”这一比喻并非他的用语。","B":"亚当·斯密用“看不见的手”描述市场对个人逐利行为的自发调节，与题干引语直接对应。","C":"大卫·李嘉图发展了劳动价值论和分配理论，没有提出这一比喻。","D":"威廉·配第是古典经济学创始人之一，提出劳动价值论的萌芽，与本题引语无关。"},"memoryTip":"“看不见的手”归斯密，马克思讲的是“价值规律的自发作用”，两套用语别混。"},"20009":{"solution":"题干限定了“英国古典经济学”，其核心成果是劳动价值论。马克思恩格斯在此基础上批判继承，创立科学的劳动价值论并进一步发展为剩余价值学说；辩证法来自德国古典哲学，唯物史观属独创。","optionAnalysis":{"A":"辩证法主要批判继承自黑格尔的德国古典哲学，与英国古典经济学没有对应关系。","B":"唯物史观是马克思恩格斯的独创，古典经济学没有提供现成的历史观理论可供发展。","C":"古典经济学已提出劳动价值论，马克思恩格斯加以批判继承并使之科学化，正是“进一步发展完善”的对象。","D":"剩余价值论是马克思的独创，古典经济学从未提出，谈不上“完善”。"},"memoryTip":"三大来源对号：古典经济学给劳动价值论，德国古典哲学给辩证法，空想社会主义给理想。"},"20010":{"solution":"马克思对黑格尔哲学采取扬弃态度，剥去唯心主义外壳，保留其辩证法这一合理内容，故称“合理内核”；费尔巴哈的唯物主义则被称为“基本内核”，两个称谓要对调记牢。","optionAnalysis":{"A":"辩证法正是黑格尔哲学中被马克思吸收改造的合理内容，故称“合理内核”。","B":"“基本内核”通常指费尔巴哈的唯物主义，与黑格尔辩证法对不上号。","C":"“精髓”在马克思主义语境中指具体问题具体分析，不是对黑格尔辩证法的称谓。","D":"“核心”不是教材对黑格尔辩证法的定性用语，也与“外壳与内核”的比喻结构不合。"},"memoryTip":"黑格尔＝合理内核，费尔巴哈＝基本内核：一个“辩”一个“唯”，对着记。"},"20011":{"solution":"“最深刻、最全面、最详细的证明和运用”是政治经济学的专属定位。它以剩余价值理论解剖资本主义生产方式，把哲学世界观落到经济事实的剖析上，从而验证了唯物史观。","optionAnalysis":{"A":"哲学提供世界观和方法论前提，处在基础位置，不是被论证出来的“证明和运用”。","B":"政治经济学通过剖析资本主义经济关系论证唯物史观和科学社会主义，正是最深刻的证明和运用。","C":"科学社会主义是核心和结论，处于被论证的一端，不是论证的工具。","D":"政治学不属于马克思主义三大组成部分，教材没有这一说法。"},"memoryTip":"“证明和运用”四字专指政治经济学，联想《资本论》解剖资本主义即可。"},"20012":{"solution":"一战中的俄国集中了帝国主义的一切矛盾：垄断资本与工人的矛盾、农民与地主的矛盾、民族矛盾交织，加上沙皇统治腐朽，成为帝国主义链条上最薄弱的环节，十月革命由此突破。","optionAnalysis":{"A":"德国是后起的帝国主义强国和战争挑起者，但矛盾集中程度与统治危机不及俄国。","B":"奥匈帝国是萨拉热窝事件的当事国，属于战争的导火索，并非体系最薄弱环节。","C":"中国当时是半殖民地半封建社会，被卷入战争但未成为东西方矛盾的焦点。","D":"俄国在战争中经济濒于崩溃、统治危机深重，成为帝国主义体系最薄弱环节，列宁据此提出一国首先胜利论。"},"memoryTip":"“最薄弱环节”＝俄国，与“一国首先胜利”“十月革命”串成一条链记。"},"20013":{"solution":"引文用的是比喻：哲学提供思想武器，无产阶级提供物质力量，二者结合才能实现人类解放。这说明马克思主义与无产阶级互为条件，是无产阶级自己的世界观和方法论。","optionAnalysis":{"A":"哲学作“精神武器”、无产阶级作“物质武器”，正是理论与阶级主体的结合，说明它是无产阶级的世界观和方法论。","B":"哲学属于社会意识形式，其存在方式不是物质，此说混淆了物质与意识。","C":"无产阶级是现实的物质力量，把它的存在方式说成精神，恰好颠倒了引文的比喻关系。","D":"方向说反了，掌握科学理论是无产阶级由自在阶级变为自为阶级的条件。"},"memoryTip":"口诀“哲学是精神武器、无产阶级是物质武器”，再加一句“自在在前、自为在后”。"},"20014":{"solution":"马克思主义以实践为基础，实践观点是认识论首要的和基本的观点，也是整个马克思主义哲学的首要的基本观点。联系和发展只是辩证法的总特征，历史观点不是这一命题的表述。","optionAnalysis":{"A":"实践是马克思主义首要的和基本的观点，马克思主义哲学正是在实践基础上实现唯物论与辩证法、自然观与历史观的统一。","B":"发展观点是辩证法的总特征之一，很重要但冠不上“首要的和基本的”。","C":"联系观点同样是辩证法的总特征，与“首要的基本观点”这一特定表述不匹配。","D":"“历史观点”不是教材对该命题的标准表述，也无法概括实践在马克思主义中的地位。"},"memoryTip":"见“首要的基本观点”直接答实践，其余三项都只是辩证法的一般特征。"},"20015":{"solution":"马克思主义哲学是辩证唯物主义和历史唯物主义的统一体，二者合一才完整构成无产阶级的科学世界观和方法论，只答其中一半都是残缺表述。","optionAnalysis":{"A":"辩证唯物主义主要覆盖自然领域，缺少社会历史领域的唯物主义，体系不完整。","B":"历史唯物主义只讲社会历史领域，缺了自然观这一半，单独用它表述无产阶级的世界观仍不完整。","C":"辩证唯物主义和历史唯物主义高度统一，完整表达无产阶级的科学世界观和方法论。","D":"唯物主义是笼统的派别称谓，还包括旧唯物主义，体现不出科学性。"},"memoryTip":"两个“唯物主义”并列才完整，单列一个都是半截子。"},"20016":{"solution":"三大组成部分中，科学社会主义居于核心地位，是全部理论的目的和归宿；哲学与政治经济学归根到底都在论证社会主义代替资本主义的历史必然性。","optionAnalysis":{"A":"哲学是理论基础，提供世界观和方法论，处在体系底层而非核心。","B":"政治经济学处于论证和运用环节，为结论提供经济事实支撑，本身不是整个体系的核心。","C":"科学社会主义是全部理论的落脚点，指明无产阶级的历史使命和奋斗目标，居于核心。","D":"马克思主义历史学属于具体科学门类，不是三大组成部分之一，教材中没有这种划分。"},"memoryTip":"核心答科学社会主义，记“要干什么、往哪去”的问题归它管。"},"20017":{"solution":"基本立场回答“站在谁一边”。马克思主义以人民为中心，一切为了人民、一切依靠人民，这是它区别于其他理论的根本立场；其余三项分别讲研究对象、规律认识和思想来源，属于观点或方法层面。","optionAnalysis":{"A":"这是对马克思主义研究对象的说明，回答“研究什么”，属于基本观点而非立场。","B":"该项文字本身有误，且讲的是对社会发展规律的认识，仍属观点层面。","C":"鲜明宣告以人民为中心、全心全意为人民服务，正是马克思主义的基本立场。","D":"说明马克思主义对人类思想成果和实践经验的总结，属于理论来源与科学性，不是立场。"},"memoryTip":"立场看“人民”，观点看“规律”，方法看“辩证”，三问三答不串门。"},"20018":{"solution":"恩格斯把《关于费尔巴哈的提纲》誉为“包含着新世界观的天才萌芽的第一个文件”，因为其中首次确立实践的观点，奠定了新唯物主义基石；《共产党宣言》是诞生标志，不可混用。","optionAnalysis":{"A":"《关于费尔巴哈的提纲》以实践为核心批判旧唯物主义，被恩格斯称为新世界观天才萌芽的第一个文件。","B":"《共产党宣言》是马克思主义公开问世、正式诞生的标志，评价用语与题干不同。","C":"《德意志意识形态》首次系统阐述唯物史观，地位重要，但未被冠以“第一个文件”。","D":"《资本论》是政治经济学的代表作，写作年代晚于上述文献，与“萌芽”不符。"},"memoryTip":"“天才萌芽第一文件”＝《关于费尔巴哈的提纲》，题眼是“实践”。"},"20019":{"solution":"马克思主义最崇高的社会理想是实现共产主义，即建立自由人联合体、实现人的自由全面发展。消灭阶级和国家只是实现共产主义的条件和结果，绝对自由、抽象人权都不是马克思主义提法。","optionAnalysis":{"A":"实现共产主义是马克思主义最崇高的社会理想，也是它的最终奋斗目标。","B":"消灭阶级、消灭国家是实现共产主义的必经条件和结果，不足以概括最崇高理想本身。","C":"“个人的绝对自由”是无政府主义式的错误提法，马克思主义讲的是自由人联合体中人的自由全面发展。","D":"“实现人权”是资产阶级革命时期的口号，抽象空泛，未触及社会制度的根本变革。"},"memoryTip":"最高理想一律答共产主义，警惕“绝对自由”“人权”这两个漂亮词做陷阱。"},"20020":{"solution":"题干问“最根本的世界观和方法论”，要答哲学层面的完整形态，即辩证唯物主义和历史唯物主义。实事求是、从实际出发属于党的思想路线，是马克思主义中国化的表述，层次不同。","optionAnalysis":{"A":"实事求是、理论联系实际是党的思想路线和优良作风，不是“最根本的世界观和方法论”。","B":"辩证唯物主义和历史唯物主义是马克思主义最根本的世界观和方法论，构成整个理论体系的基础。","C":"从实际出发、实事求是同样是思想路线的表述，不能与哲学形态画等号。","D":"唯物主义与辩证法在旧哲学中是分离的，此处既未提历史唯物主义，也没体现二者的统一。"},"memoryTip":"见“最根本的世界观和方法论”答完整两词；“实事求是”只配思想路线。"},"20021":{"solution":"马克思恩格斯兼具学者的严谨与革命家的担当，既能进行艰苦的理论创造，又亲自投身工人运动，这种双重品质使他们超越同时代的思想家，成为马克思主义的创立者。","optionAnalysis":{"A":"“高尚人格”过于笼统，不能说明为什么恰恰是他们完成了理论创造。","B":"“崇高理想”许多空想社会主义者也具备，解释不了马克思主义的科学性。","C":"“奋斗精神”只是对意志品质的描述，不是创立科学理论的关键条件。","D":"学者和革命家相统一的品质，使他们既有理论深度又掌握工人运动的实践，构成创立马克思主义的重要条件。"},"memoryTip":"记“学者＋革命家”两种身份合一：只会读书或只会斗争都创不出新世界观。"},"20022":{"solution":"1848年《共产党宣言》系统阐明马克思主义基本原理，公开宣告其问世，被公认为马克思主义诞生的标志；十月革命是理论变为现实的标志，剩余价值论是理论内容而非标志。","optionAnalysis":{"A":"《共产党宣言》的发表标志马克思主义公开问世，是公认的诞生标志。","B":"共产主义者同盟的出现是组织事件，组织成立不等于思想体系的诞生。","C":"十月革命的胜利是马克思主义由理论变为现实、社会主义制度建立的标志，时间晚了近七十年。","D":"剩余价值论的发现是马克思一生两大发现之一，属于理论成熟的成果，不是诞生标志。"},"memoryTip":"1848年《宣言》＝诞生，1917年十月革命＝理论变现实，两组年份分开记。"},"20023":{"solution":"哲学是世界观和方法论的统一，但并非所有哲学都科学，因此定义只能落在“理论化、系统化的世界观”。加“科学”二字或说成知识总和都会出错。","optionAnalysis":{"A":"这是马克思主义哲学的定义，用来定义一般哲学就把非科学的哲学排除在外了。","B":"错在“科学”二字，哲学有科学与非科学之分，不能说一切哲学都是关于世界观方法论的科学。","C":"哲学不是各门具体知识的简单相加，说成“总和”混淆了整体把握与机械堆积。","D":"哲学是世界观的理论化、系统化形态，同时提供方法论，与一般哲学定义吻合。"},"memoryTip":"哲学定义记“系统化理论化的世界观”，一旦加上“科学”就是错项。"},"20024":{"solution":"恩格斯明确指出，全部哲学特别是近代哲学的重大的基本问题是思维和存在的关系问题，它包含何者第一性和有无同一性两个方面，其余选项都是辩证法或认识论中的具体问题。","optionAnalysis":{"A":"运动和静止的关系属于辩证法中的运动观问题，层次低于哲学基本问题。","B":"人与周围世界的联系问题表述笼统，不是恩格斯原话所指的内容。","C":"恩格斯把思维和存在的关系问题确立为哲学基本问题，并据此划分唯物唯心与可知不可知。","D":"联系与发展的关系是辩证法总特征的问题，不属于哲学基本问题。"},"memoryTip":"哲学基本问题背恩格斯原话“思维和存在的关系问题”，别自行替换成“联系发展”。"},"20025":{"solution":"同一性问题问的是思维能否正确反映存在，即世界是否可知；第一性问题问的是谁决定谁。把同一性理解为二者可以等同，是本题最常见的错误理解。","optionAnalysis":{"A":"同一性指思维能够认识存在，不是二者可以等同，等同说抹掉了物质与意识的本质区别。","B":"思维能否认识存在、世界是否可知，正是同一性问题的本来含义。","C":"划分唯物论和唯心论的标准是第一性问题，不是同一性问题，两把尺子不能互换。","D":"思维的至上性与非至上性讲的是人的认识能力无限与有限的辩证关系，不是同一性问题的标准表述。"},"memoryTip":"同一性＝“能不能认识”；第一性＝“谁决定谁”，一句话分清两道题。"},"20026":{"solution":"两大基本派别按对第一性问题的回答划分，即唯物主义与唯心主义；辩证法与形而上学是两种发展观，可知论与不可知论是认识论上的划分，都不属于“基本派别”。","optionAnalysis":{"A":"主观唯心主义和客观唯心主义是唯心主义内部的两基本形式，不是哲学的两大派别。","B":"辩证法和形而上学是两种发展观的对立，属于哲学的另一个方面。","C":"唯物主义和唯心主义依据物质与精神何者第一性划分，构成哲学两大基本派别。","D":"可知论和不可知论依同一性问题划分，是认识论上的分野而非哲学基本派别。"},"memoryTip":"两大派别＝唯物／唯心；两种发展观＝辩证／形而上学，别把第二组当选。"},"20027":{"solution":"划分标准只能看第一性问题：承认存在第一性、思维第二性的是唯物主义，反之是唯心主义。是否承认联系发展、世界是否统一、是否可知，都是另外几把尺子。","optionAnalysis":{"A":"是否承认普遍联系和变化发展，划分的是辩证法与形而上学。","B":"世界是否统一、有几个本原，划分的是一元论与二元论，与唯物唯心的划分标准无关。","C":"承认思维和存在的关系中存在第一性，就是唯物主义，这正是划分标准。","D":"世界是否可认识，划分的是可知论与不可知论，对应哲学基本问题的第二方面。"},"memoryTip":"四把尺子一条线：第一性分唯物唯心，同一性分可知不可知，联系发展分辩证形而上学。"},"20028":{"solution":"唯物主义随实践和科学的发展经历三种历史形态：古代朴素唯物主义、近代形而上学唯物主义、现代辩证唯物主义。注意这是“形态”序列，不是派别或辩证法的序列。","optionAnalysis":{"A":"原子论只对应近代机械唯物主义的物质观，把哲学形态等同于具体科学假说，序列也错。","B":"庸俗唯物主义不是独立的历史形态，“自然唯物主义”提法也不成立，顺序混乱。","C":"朴素唯物主义、形而上学唯物主义、辩证唯物主义依次递进，正是唯物主义三阶段。","D":"朴素辩证法、唯心辩证法、唯物辩证法是辩证法的历史形态，问的是唯物主义。"},"memoryTip":"唯物三形态“朴素—形而上学—辩证”；辩证法三形态是另一串，看好题干问哪个。"},"20029":{"solution":"唯心主义按精神主体的不同分为主观唯心主义和客观唯心主义：前者把人的主观精神当本原，后者把脱离人的独立精神当本原。其余划分都错在混入了别的维度。","optionAnalysis":{"A":"唯心主义可以与辩证法或形而上学相结合，这种划分混淆了派别与发展观两个维度。","B":"可知论与不可知论是认识论上的划分，不是唯心主义的形式划分。","C":"彻底与不彻底是就唯物主义者能否把唯物主义贯彻到历史领域而言，不是唯心主义的形式。","D":"主观唯心主义和客观唯心主义依精神主体不同划分，是唯心主义的两种基本形式。"},"memoryTip":"唯心两形式“主观／客观”，判断标准只看精神是否挂在人身上。"},"20030":{"solution":"客观唯心主义把某种脱离人的独立精神当作世界本原。四项中只有“天”是外在于人的主宰力量，其余三项的“我”“心”“感知”都落在人的主观精神上。","optionAnalysis":{"A":"“万物皆备于我”把万物归到“我”的心中，以自我为出发点，属于主观唯心主义命题。","B":"“存在就是被感知”把存在归结为感知，是贝克莱式的主观唯心主义。","C":"“生死有命，富贵在天”把“天”当作支配一切的外在力量，属于客观唯心主义。","D":"“心外无物”认为离开人心就没有外物，以人心为本原，是王阳明式的主观唯心主义。"},"memoryTip":"见“天、理、上帝、绝对精神”归客观；见“我、心、感知”归主观。"},"20031":{"solution":"同一性问题问思维能否认识存在，否认这一点就是不可知论。唯心主义未必否认同一性，二元论也不等于不可知论，三者不能混为一谈。","optionAnalysis":{"A":"唯心主义只是颠倒了物质与意识的关系，黑格尔等仍主张思维与存在同一，不能一概而论。","B":"经验主义是一种认识论倾向，与是否承认世界可知没有必然联系。","C":"不可知论否认思维能够认识存在，正是对同一性的否定，与题干直接对应。","D":"二元论主张世界有两个本原，属本体论划分，并不直接等于否认认识世界的可能性。"},"memoryTip":"否认同一性＝不可知论，代表人物记休谟和康德，别错认成唯心主义。"},"20032":{"solution":"可知论与不可知论的分野在于是否承认思维能认识存在，即物质和意识有无同一性。第一性问题划分的是唯物与唯心，两把尺子不能互换使用。","optionAnalysis":{"A":"哲学基本问题包含两个方面，用它作标准过于笼统，无法区分可知与不可知。","B":"物质和意识的关系问题同样包含第一性和同一性两方面，指向不具体。","C":"物质和意识谁是第一性划分的是唯物主义与唯心主义，不是可知论与不可知论。","D":"承认物质和意识有同一性即可知论，否认即不可知论，这正是划分标准。"},"memoryTip":"同一性→可知论，第一性→唯物唯心，两句成对背，位置不许颠倒。"},"20033":{"solution":"形而上学唯物主义的三大局限是机械性、形而上学性和不彻底性：把一切运动归结为机械运动，用孤立静止片面的观点看问题，历史观上仍停留在唯心主义。","optionAnalysis":{"A":"主观性、片面性和表面性是对主观主义认识方法的描述，不是旧唯物主义局限的规范概括。","B":"直线性、循环性和盲目性不是教材对旧唯物主义的定性用语。","C":"机械性、形而上学性、不彻底性完整概括了旧唯物主义的三大局限。","D":"孤立、静止、片面地看问题只对应“形而上学性”一项，遗漏机械性和历史观上的不彻底。"},"memoryTip":"三性口诀“机械、形而上学、不彻底”，第三条就是“半截子”的病根。"},"20034":{"solution":"相信意念可以移物、直接改变物质结构，等于承认人的意识能脱离物质条件支配物质世界，把主观精神抬高为世界主宰，属于主观唯心论。","optionAnalysis":{"A":"“意念移物”让人的意识直接支配物质，正是主张精神主宰客观世界的主观唯心论。","B":"客观唯心论讲的是脱离人脑的独立精神，题中的“意念”依附于人，不符合。","C":"机械唯物主义恰恰否认意识的能动作用，与题干夸大意识作用的方向相反。","D":"实践唯物主义强调能动性以尊重客观规律为前提，不会承认意念能直接改变物质。"},"memoryTip":"看精神“挂在谁身上”：挂在人身上是主观唯心，独立存在才是客观唯心。"},"20035":{"solution":"“心诚则灵”把事情的成败完全系于主观信念，等于说意识能直接决定客观结果，这是无限夸大意识能动作用的唯心主义，而不是承认物质决定意识。","optionAnalysis":{"A":"辩证唯物主义要求以尊重客观规律为前提发挥能动性，绝不会把结果归于“心诚”。","B":"庸俗唯物主义把意识混同于物质，题干并未把思想说成物质，故不吻合。","C":"客观唯心主义讲绝对精神外化世界，题干强调的却是人的“心”，主体不对。","D":"把主观信念当成决定成败的力量，正是夸大意识能动作用的唯心主义观点。"},"memoryTip":"“心诚则灵”类俗语考的是“夸大能动作用”，不必纠结唯心主义的名称。"},"20036":{"solution":"一元论回答的是世界有几个本原，主张只有一个本原因而世界统一，与是否物质、是否发展无关；唯物主义一元论和唯心主义一元论都属于一元论。","optionAnalysis":{"A":"一元论主张世界只有一个本原，因而世界是统一的，这正是它的基本主张。","B":"世界发展变化属于辩证法的观点，与一元论要回答的本原数目问题无关。","C":"“世界是物质的”是唯物主义一元论的具体立场，把一元论窄化成了唯物论。","D":"“世界是精神的”是唯心主义一元论的具体立场，同样窄化了一元论。"},"memoryTip":"一元论只答“一个本原、世界统一”，加“物质”或“精神”就变成它的两个分支。"},"20037":{"solution":"主观唯心主义把人的主观精神（感觉、心灵、意志）当作世界本原，认为外部世界是人的精神的产物，判断关键是精神主体落在“人”身上。","optionAnalysis":{"A":"只承认理性认识可靠是唯理论的主张，属于认识论分歧，不是主观唯心的特征。","B":"只承认感性认识可靠是经验论的主张，同样属于认识论分歧。","C":"说人的精神崇高只是价值判断，没有回答世界本原问题，不构成哲学派别特征。","D":"把世界看作人的主观精神的产物，正是主观唯心主义的根本特征。"},"memoryTip":"主观唯心＝“人的精神产物”，答题抓住“人”这个主体就不跑偏。"},"20038":{"solution":"客观唯心主义把某种脱离人、脱离人脑而独立存在的精神（如理、绝对观念、上帝）当作世界本原，认为世界是这种独立精神的产物。","optionAnalysis":{"A":"认为理性认识可靠属于唯理论，是认识论主张，与客观唯心不是同一个问题。","B":"把人的意识当作世界本原，这是主观唯心主义的特征，主体落在了人身上。","C":"物质世界不以人的意识为转移是唯物主义观点，与客观唯心正相反。","D":"认为世界是某种独立精神的产物，正切中客观唯心主义“精神独立于人”的特征。"},"memoryTip":"客观唯心的标志词是“独立于人的精神”，看到“绝对观念、理、上帝”就下手。"},"20039":{"solution":"“半截子”是形象说法：旧唯物主义在自然观上坚持物质第一性，一进入社会历史领域就倒向唯心主义，即唯物主义只贯彻了“下半截”。","optionAnalysis":{"A":"形而上学性只是旧唯物主义的局限之一，解释不了“半截子”这个比喻的针对性。","B":"自然观唯物、历史观唯心，唯物主义没有贯彻到底，正是“半截子”的确切含义。","C":"机械性指把一切运动归结为机械运动，是另一条局限，与“半截”无关。","D":"该项表述本身不成立，割裂运动与静止属于形而上学，不能说成“辩证法”。"},"memoryTip":"“半截子”＝下半截自然观唯物、上半截历史观唯心，切口在历史观。"},"20040":{"solution":"古代朴素唯物主义依据直观猜测，把物质归结为水、火、气、原子等一种或几种具体形态，试图用具体事物说明世界本原，却混淆了物质与物质的具体形态。","optionAnalysis":{"A":"“存在”是极抽象的哲学范畴，不是古代朴素唯物主义对物质的归结。","B":"“绝对观念”是黑格尔式的客观唯心主义本原，用它解释物质等于把物质说成精神的产物。","C":"把物质归结为“灵魂”属于唯心主义或物活论，不是朴素唯物主义的物质观。","D":"把物质等同于水、火、气等具体形态，正是古代朴素唯物主义物质观的特点。"},"memoryTip":"朴素唯物＝具体形态，记“水、火、气、原子”，本质是“以物解释物”。"},"20041":{"solution":"近代形而上学唯物主义把物质等同于当时自然科学所认识的原子，用物质的某一具体形态的个性代替共性，因而不懂得一般与个别的辩证法。","optionAnalysis":{"A":"它恰恰以当时的自然科学成就为依据，说“没有自然科学依据”与事实相反。","B":"把物质归结为原子，以个别代替一般，正是形而上学唯物主义物质观的错误所在。","C":"它坚持物质的客观性，否认客观性的是唯心主义，不是旧唯物主义。","D":"对物质作自发猜测是古代朴素唯物主义的特点，不是近代形而上学唯物主义。"},"memoryTip":"近代唯物“以原子代物质”＝不懂一般与个别；古代唯物才是“自发猜测”。"},"20042":{"solution":"列宁的定义是“物质是标志客观实在的哲学范畴”，从物质与意识的对立中、从“不依赖人的意识又能被意识反映”这一关系上规定物质，界定角度就是物质与意识的关系。","optionAnalysis":{"A":"列宁正是通过物质不依赖意识、又能被意识反映这层关系来规定物质范畴。","B":"个别与一般的关系是古代、近代物质观失足的症结，不是列宁下定义的方式。","C":"哲学与具体科学的关系说明物质的抽象程度，不是列宁定义物质的切入角度。","D":"认识与实践的关系属于认识论范畴，与物质范畴的界定角度不同。"},"memoryTip":"列宁定义抓“客观实在＋不依赖意识又能被反映”，界定轴心是物质与意识的关系。"},"20043":{"solution":"物质的唯一特性是客观实在性，这是它区别于意识的根本标志；运动则是物质的根本属性和存在方式，两个提法各有归属，不能互换。","optionAnalysis":{"A":"运动是物质的根本属性和存在方式，讲“唯一特性”时不能用它替代客观实在性。","B":"客观实在性是物质区别于意识的唯一特性，列宁的物质定义正是突出这一点。","C":"发展的规律性不是物质的特性表述，物质本身也不等同于规律。","D":"本质的可知性讲的是世界能否被认识，属于认识论问题，不能充当物质的唯一特性。"},"memoryTip":"“唯一特性”＝客观实在，“根本属性”＝运动，两个标签各贴各的。"},"20044":{"solution":"先有设计图、后有大厦，说明观念形态的东西通过实践变成了现实的物质成果，体现意识的能动作用；但前提是材料和规律客观存在，绝不是意识产生或决定物质。","optionAnalysis":{"A":"意识产生物质是唯心主义命题，设计图只有经过施工实践才能变成大厦。","B":"意识决定物质颠倒了物质与意识的关系，与唯物主义基本原理相冲突。","C":"设计图经施工实践变为现实的大厦，正是意识向物质的转化，体现意识的能动作用。","D":"“创造物质”违背物质不灭，意识只能改变物质的具体形态，不能凭空造出物质。"},"memoryTip":"图纸变大厦，题眼在“转化”二字：意识通过实践转化为物质，不是产生物质。"},"20045":{"solution":"引文强调观念的东西来自物质的东西，又经过人脑加工改造，因而意识是客观内容与主观形式的统一，即客观存在的主观映象。","optionAnalysis":{"A":"意识不是物质，把意识说成人脑特有的物质是庸俗唯物主义的错误。","B":"人脑是意识的器官而非源泉，意识的源泉是客观存在，二者不能混同。","C":"观念的东西与物质的东西有本质区别，前者是主观映象，后者是客观实在。","D":"意识来源于客观存在又经过人脑改造，正是客观存在的主观映象。"},"memoryTip":"记“内容客观、形式主观”，看到“改造过”三字就选主观映象。"},"20046":{"solution":"物质和运动不可分割：没有不运动的物质，也没有脱离物质的运动。把二者等同，或说成可以分开，都会滑向形而上学或唯心主义。","optionAnalysis":{"A":"物质是运动的承担者，运动是物质的存在方式，说“物质就是运动”抹掉了承担者。","B":"运动是物质的根本属性，说“运动就是物质”同样把两个范畴混为一谈。","C":"物质离不开运动，运动也离不开物质，二者不可分割，这是教材的基本结论。","D":"说二者可以分开，必然导致设想无运动的物质或无物质的运动，都是错误观点。"},"memoryTip":"两句连背：没有不运动的物质，也没有无物质的运动。"},"20047":{"solution":"设想没有运动的物质，就是把物质看成静止不变的，这是形而上学唯物主义的特征；反过来设想没有物质的运动则通向唯心主义，两题成对出现。","optionAnalysis":{"A":"客观唯心论的问题是把精神当本原，不是把物质设想成不动。","B":"承认物质是本原却否认其运动，正是形而上学唯物主义的观点。","C":"二元论主张物质和精神两个本原并存，讨论的是本原数目，与是否承认物质运动无关。","D":"主观唯心论以人的精神为本原，与“有物质而无运动”的设想不符。"},"memoryTip":"题干落在“没有运动”，病根是把物质看死，锁定形而上学唯物论。"},"20048":{"solution":"设想没有物质的运动，等于承认运动可以脱离物质承担者，只能把运动归结为精神过程，这是唯心主义的运动观；与“没有运动的物质”恰好互为镜像。","optionAnalysis":{"A":"让运动脱离物质承担者，只能把运动归于精神，属于唯心论的观点。","B":"形而上学唯物主义对应的是“没有运动的物质”，与本题“没有物质的运动”方向正好相反。","C":"不可知论讲的是世界能否被认识，属于认识论问题，与运动有无物质承担者无关。","D":"可知论肯定世界可以被认识，同样属于认识论问题，不涉及运动是否有物质主体。"},"memoryTip":"题干落在“没有物质”，运动找不到承担者只能归于精神，锁定唯心论。"},"20049":{"solution":"“动中有静，静中有动”讲的是绝对运动与相对静止的相互包含：运动中有静止的成分，静止中包含着运动，二者辩证统一，而非物质与运动或有限无限的关系。","optionAnalysis":{"A":"物质和运动的统一讲的是运动离不开物质，与动静相互包含不是同一命题。","B":"绝对运动与相对静止相互渗透、相互包含，正是这句话的哲学含义。","C":"有限性与无限性的统一属于时空观问题，与动静关系不对应。","D":"唯物主义与辩证法的统一是就整个马克思主义哲学而言，范围过大，不切题。"},"memoryTip":"见“动中有静，静中有动”直接答“绝对运动与相对静止的统一”，别上升到物质与运动。"},"20050":{"solution":"惠能把风动、幡动归结为“仁者心动”，等于说运动的主体不是物质而是人的精神，否认运动是物质的根本属性，属于主观唯心主义的运动观。","optionAnalysis":{"A":"运动是物质的根本属性是唯物主义命题，与惠能把动归于“心”正相反。","B":"运动与物质不可分同样强调物质是运动的主体，与“心动”说不相容。","C":"该项颠倒了关系，精神运动以物质运动为基础，不是物质运动的一种形式。","D":"把心当作动的根源，即认定精神是运动的主体，正是惠能观点的实质。"},"memoryTip":"“仁者心动”＝精神充当运动主体，归主观唯心主义运动观，与“运动是物质根本属性”对打。"},"20051":{"solution":"题眼在否认运动绝对性、把静止绝对化，这是用静止吞掉运动的单向思维。辩证法主张运动绝对、静止相对且二者统一，只讲静止不讲运动，正是形而上学孤立静止看世界的方法，故选C。","optionAnalysis":{"A":"唯心主义回答的是物质与精神何者第一性的问题，它既可能讲运动也可能讲静止，与静止绝对化没有对应关系。","B":"唯物主义只表明物质第一性，辩证唯物主义同时坚持运动的绝对性，把静止绝对化并不是唯物主义的共同特征。","C":"形而上学以孤立、静止、片面的观点看世界，否认运动绝对性，把静止夸大为事物的常态，与题干完全吻合。","D":"相对主义恰恰相反，它夸大运动的绝对性而否认相对静止，认为一切瞬息万变、没有确定性质，方向与题干相反。"},"memoryTip":"静止绝对化找形而上学：辩证法讲动静统一，形而上学只要静，相对主义只要动。"},"20052":{"solution":"题干限定只承认绝对运动、否认相对静止。这种夸大变动的观点把事物看成没有确定性质和界限的流动，属于相对主义，它也是诡辩论的认识论基础，故选B。","optionAnalysis":{"A":"主观唯心主义以我的感觉为世界本原，讨论的是本原问题，并不直接对应否认相对静止的运动观。","B":"相对主义夸大运动的绝对性、抹煞相对静止，否认事物具有确定性质和稳定界限，正是题干所述观点。","C":"客观唯心主义把某种客观精神当作世界本原，属于本原问题上的错误，与运动静止之争不在同一层面。","D":"唯物主义在运动观上可以是辩证的，辩证唯物主义承认运动绝对、静止相对，并不导致否认静止。"},"memoryTip":"两句对着背：只要动不要静是相对主义，只要静不要动是形而上学。"},"20053":{"solution":"坐地、巡天写位置相对稳定，日行八万里、遥看一千河写随地球不停运动。静中含动、动中有静，正说明运动是绝对的、静止是相对的，故选D。","optionAnalysis":{"A":"时空具有客观性，不以人的意志为转移，所谓时空主观性本身是唯心主义时空观，不能作为诗句的哲理。","B":"物质运动的无限性与有限性统一讲宇宙整体与具体事物的关系，诗句落点在动与静的对照，不在此层。","C":"时空无限性与有限性统一讨论时空整体与具体时空的关系，与坐与行的动静对照并不吻合。","D":"坐地是不动之静，日行八万里是不停之动，静中含着动，恰好体现运动绝对性与静止相对性的统一。"},"memoryTip":"抓坐与行两字：坐是静、行是动，一句诗同写动静，就选动静统一。"},"20054":{"solution":"此题考时空的本质规定。辩证唯物主义认为时空不是独立自在的实体，而是运动着的物质的存在形式，离开物质运动就无从谈时空，故选B。","optionAnalysis":{"A":"物质的根本属性是运动，时空是运动着的物质的存在形式，把二者并列为两种根本属性混淆了层次。","B":"时间空间是运动着的物质的存在形式，准确反映了时空对物质运动的依赖关系，符合教材界定。","C":"把时空说成整理认识材料的工具，是康德式的先验形式观点，把客观时空变成了主观认识框架。","D":"感觉系列调整了的体系是马赫主义对时空的解释，把时空归结为主观感觉的产物，属于唯心主义。"},"memoryTip":"时空一句话定位：运动着的物质的存在形式，抓形式二字，别答成属性或工具。"},"20055":{"solution":"时间的一维性说的是时间只有单一方向，过去、现在、未来依次展开，不能倒流也不能重复，因此一维性的实质就是不可逆性，故选D。","optionAnalysis":{"A":"客观性指时间不依赖人的意识而存在，回答的是时空是否主观的问题，不是一维性的含义。","B":"永恒性讲时间无始无终地延续，属于时间的无限性，与一维所指的单向延伸不是一回事。","C":"顺序性只说明时间有先后次序，而循环的时间同样可以有次序，一维性强调的是去而不返。","D":"一维即单向，时间沿一个方向流逝、不能倒退重来，不可逆是对一维性最准确的概括。"},"memoryTip":"一维像一条不回头直线：三维空间可往返，一维时间不可逆。"},"20056":{"solution":"牛顿的绝对时空观把时间空间看作与物质及其运动无关的空容器，物质放进去在走、不放进去也在走。其错误正在于割裂时空同物质运动的联系，故选C。","optionAnalysis":{"A":"绝对时空观并不否认时空的客观性，它恰恰把时空当成独立存在的客观实体，方向正好说反了。","B":"牛顿认为绝对时空无限延展，并不主张时空有限，否认有限性不是它的错误所在。","C":"绝对时空观把时空当作脱离物质运动的独立容器，否认时空同物质运动的内在联系，这是要害。","D":"绝对时空观确实主张时空不变，但题干问的是错误在于否认什么，它是肯定不变而非否认不变。"},"memoryTip":"牛顿的空箱子：时空与物质运动分了家，错误记成否认联系，别误选否认客观性。"},"20057":{"solution":"狭义相对论指出时空量度随物体运动速度改变，广义相对论指出时空结构受物质分布影响，说明时空既有客观绝对的一面，又有随条件变化的一面，故选D。","optionAnalysis":{"A":"无限性指宇宙时空在范围上无边无际，相对论讨论的是时空随参照系和物质分布变化，不是无限性问题。","B":"有限性指具体时空有边界，相对论并未论证时空有限，它所揭示的是时空特性的条件性。","C":"相对论恰恰否定了牛顿式的绝对时空，把时空的绝对性限定在客观实在性上，单讲绝对性并不全面。","D":"时空作为物质存在形式具有客观绝对性，其具体特性又随运动状态和物质分布改变，是二者的统一。"},"memoryTip":"相对论推翻绝对时空观，记：客观性还在，具体特性可变，落到绝对与相对的统一。"},"20058":{"solution":"愉快时觉得时间过得快、抑郁时觉得难熬，变的是人对时间长短的主观体验，而不是时间本身。客观时间不因心情改变，可见时间观念具有相对性，故选D。","optionAnalysis":{"A":"时间具有客观实在性，把时间说成人的主观感觉，等于取消时间的客观性，属于唯心主义时间观。","B":"变化的是主观感受而非客观时间的流逝速度，说时间随感觉而变，把主观体验当成了客观过程。","C":"时间具体特性可变指相对论意义上随运动状态改变，与心情无关，用在这里偷换了可变的层次。","D":"同一段时间在不同心境下被体验为长短不同，说明人的时间观念受主观状态影响而具有相对性。"},"memoryTip":"心情变的是观念不是时间：问感受就选时间观念的相对性，别选时间本身可变。"},"20059":{"solution":"马克思把劳动看作人与社会形成的起点：人在劳动中结成生产关系，进而生成全部社会关系。劳动实践因此成为人类社会赖以存在和发展的基础，故选B。","optionAnalysis":{"A":"生产活动是劳动实践的最基本形式，但题干问的是更根本的基础范畴，教材以劳动实践统摄生产活动。","B":"劳动实践创造了人本身，也在其中形成生产关系和其他社会关系，是人类社会存在和发展的基础。","C":"意识活动是社会的精神现象，由社会实践决定，把意识当作社会基础颠倒了社会存在与意识的关系。","D":"阶级斗争只是阶级社会发展的直接动力，原始社会并不存在，不能成为一切社会形态的基础。"},"memoryTip":"社会基础记劳动：劳动造人、劳动结关系；阶级斗争只是阶级社会的动力，别混。"},"20060":{"solution":"自然界是自在的存在，社会是人的实践活动生成的存在，二者既相区别又相统一。把它们联结起来并实现统一的基础正是实践，故选B。","optionAnalysis":{"A":"运动是物质的根本属性和存在方式，范围过宽，万物皆动，无法说明自然存在与社会存在的特殊区分。","B":"实践以物质生产为基本形式，既改造自然又形成社会关系，是自然界与人类社会分化又统一的现实基础。","C":"精神生产属于社会意识领域的活动，由物质实践派生，不能充当自然存在与社会存在统一的基础。","D":"物质生产是实践的最基本形式，但教材表述这一统一的基础是实践，物质生产只是其中的核心部分。"},"memoryTip":"自然与社会分也实践、合也实践，记实践是枢纽；物质生产只是实践的最基本形式。"},"20061":{"solution":"命题含两个要点：世界是物质的，坚持了唯物主义；世界处在不断的历史发展中，坚持了辩证法。二者合一就是唯物辩证法的观点，故选C。","optionAnalysis":{"A":"唯物主义只说对了物质第一性这一半，未包含历史发展，旧唯物主义恰恰缺少发展观。","B":"形而上学用静止不变的观点看世界，与处在不断的历史发展中直接冲突。","C":"物质体现唯物主义立场，不断的历史发展体现辩证法的发展观，两者结合正是唯物辩证法的观点。","D":"唯心辩证法也讲发展，但把发展归结为精神的自我运动，不承认世界的物质性，一切辩证法过于笼统。"},"memoryTip":"两句拆开看：物质定唯物，发展定辩证，合起来才叫唯物辩证法。"},"20062":{"solution":"普遍真理讲矛盾的普遍性，各国具体实际讲矛盾的特殊性。二者结合的依据是普遍性寓于特殊性之中，特殊性包含普遍性，故选C。","optionAnalysis":{"A":"同一性与斗争性讲矛盾双方的关系，说明事物发展的动力，与结合所要求的共性和个性关系不对应。","B":"主次矛盾原理讲抓重点、分轻重，解决工作重心问题，不是真理与实际的结合问题。","C":"矛盾普遍性与特殊性即共性与个性，普遍真理必须通过各国特殊实际体现，这正是结合的哲学依据。","D":"必然与偶然讲发展趋势与实现形式的关系，与真理和实际的普遍特殊结构无关。"},"memoryTip":"结合就是共性落到个性：见普遍真理加具体实际，直接选普遍性与特殊性原理。"},"20063":{"solution":"物质统一性原理要求承认世界本原是物质、意识是物质的产物。落到工作方法上，就是一切从实际出发、实事求是，故选C。","optionAnalysis":{"A":"承认世界是多样性的统一属于理论命题本身，是对原理的复述，不是在具体工作中的运用。","B":"承认物质对意识的根源性同样是理论层面的表述，说明原理内容，尚未转化为工作方法。","C":"既然世界统一于物质，做决策、定政策就必须以客观实际为依据，这是原理在实际工作中的生动体现。","D":"反对二元论是坚持一元论的理论态度，仍属理论斗争，不是实际工作中的方法体现。"},"memoryTip":"原理落地只有一个口径：一切从实际出发；其余三项都在理论层面打转。"},"20064":{"solution":"辩证唯物论既坚持世界统一于物质，又承认物质形态的多样性和层次差别，是多样性基础上的统一，故选B。","optionAnalysis":{"A":"形而上学唯物论把统一性归结为某一种具体物质形态，用水、火、原子解释一切，实际上抹掉了多样性。","B":"辩证唯物论主张世界本原是物质，而物质表现形态无限多样，实现了唯物论基础与辩证多样性的结合。","C":"折中主义把不同观点无原则地拼凑起来，缺乏统一基础，不能说明世界的统一性。","D":"二元论主张物质和精神两个平行本原，根本否认世界的统一性，与题干立场相反。"},"memoryTip":"多样性加统一只属辩证唯物论：旧唯物论有统一无多样，二元论干脆无统一。"},"20065":{"solution":"世界统一性问题问的是千差万别的事物最终归于什么。唯物论答物质，唯心论答精神，分歧焦点就在统一于物质还是统一于精神，故选D。","optionAnalysis":{"A":"实践与认识的关系属于认识论范畴，不是世界本原之争的表述方式。","B":"运动与静止是物质存在方式之争，属于辩证法与形而上学的分歧，不是唯物论与唯心论的分野。","C":"存在一词含义含混，既可指物质也可指精神，无法标示两派的对立立场。","D":"唯物论主张世界统一于物质，唯心论主张统一于精神，这一对立正是两派的根本分歧。"},"memoryTip":"统一性问题只有两种答案：物质或精神；其余选项都是把别的争论搬过来充数。"},"20066":{"solution":"二元论认为物质和精神是两个各自独立、互不派生的本原，世界因此被劈成两半，等于否认万物归一的统一性，故选C。","optionAnalysis":{"A":"二元论并未否认物质的存在和地位，它给物质留了一个本原位置，否认物质性不是它的要害。","B":"二元论同样承认精神是独立本原，并不否认精神的存在，故不能选否认世界的精神性。","C":"二元论设两个平行本原，取消了万物归一的可能，直接否定了世界的统一性，这是它的根本缺陷。","D":"联系性是辩证法范畴，二元论的问题不在于是否承认相互联系，而在于本原的二元设定。"},"memoryTip":"二元即两个本原，也就没有了那个一，所以它否认的永远是统一性。"},"20067":{"solution":"意识是自然界长期发展的产物，更是社会劳动的产物。劳动使猿脑变人脑、使交往需要催生语言，在动物心理向人类意识飞跃中起决定作用，故选D。","optionAnalysis":{"A":"人脑是意识的物质器官，为人脑形成提供生理条件，但器官本身不自动产生意识，决定因素是劳动。","B":"物质文明是意识活动成果的积累，人类意识先于物质文明出现，用它解释意识起源属于因果倒置。","C":"语言是意识产生的重要推动力量，但语言本身也在劳动交往中产生，还不能起最终决定作用。","D":"生产劳动改变了人的生理结构，又创造了语言和交往需要，是动物心理发展为人类意识的决定性环节。"},"memoryTip":"意识起源两源一决定：自然前提加社会劳动，决定项始终是劳动，语言是劳动的产物。"},"20068":{"solution":"列宁这句话的意思是，感觉和意识不是凭空出现的，它由一切物质都具有的类似感觉的反映特性长期发展而来，因而是关于意识起源的正确论断，故选D。","optionAnalysis":{"A":"物活论认为一切物质都有意识，题干只讲反映的特性，反映特性不等于感觉和意识，二者不能混同。","B":"庸俗唯物主义把意识当成大脑分泌的物质，取消了意识与物质的区别，题干并未作此主张。","C":"古代朴素唯物主义用具体物质形态解释世界，题干讨论的是反映特性的历史发展，与此无关。","D":"承认低级的反映特性是感觉和意识的历史前提，恰好说明了意识由物质派生的起源过程，观点正确。"},"memoryTip":"反映的特性不等于意识：这是意识起源论，不是物活论，界限就在有没有感觉。"},"20069":{"solution":"客观存在的主观映象一句中，客观存在指意识反映的对象和内容来自客观世界，主观映象指反映形式与结果存在于人脑之中，故选C。","optionAnalysis":{"A":"意识不是沟通主客观的桥梁，实践才是二者联系和转化的桥梁，主体定位错误。","B":"客观精神是黑格尔式的本原，意识并非客观精神与主观感觉拼合的产物，这一说法混淆了本原与反映。","C":"意识的内容来源于客观世界，具有客观性；其感性形式和加工结果存在于人脑，具有主观性，概括准确。","D":"该选项把内容与形式的主客观属性完全颠倒，事实是内容客观、形式主观。"},"memoryTip":"八字口诀内容客观、形式主观，顺序不能颠倒，D项就是把两个词换了位置。"},"20070":{"solution":"文与可长期观察真竹，把竹的形貌神态内化于心，作画时才胸有成竹。这说明意识对客观世界的反映不是照镜子，而是经过主体加工的能动反映，故选C。","optionAnalysis":{"A":"意识是物质长期发展的产物讲的是人类意识的种系起源，与画家个人观察创作的过程不在同一层次。","B":"意识是人脑的机能讲的是生理基础，说明意识离不开人脑，但不能说明观察积累与创作的关系。","C":"长期观察形成胸中之竹，再物化为笔下之竹，正体现意识对客观对象的主动选择、加工和再现。","D":"物质不依赖意识的客观实在性讲物质第一性，虽然正确，却解释不了胸有成竹这一反映过程。"},"memoryTip":"胸有成竹是先观察后有形象，落点在能动反映；别选人脑机能，那是讲器官不讲过程。"},"20071":{"solution":"面对同一对象，仁者见仁、智者见智，差别不在对象而在主体：立场、经验、知识结构不同，反映结果就不同。这说明意识受主体状态的影响，故选C。","optionAnalysis":{"A":"意识的内容来自客观世界并受对象制约，把意识说成主体的自由创造，等于否认了意识的客观来源。","B":"意识必须依赖认识客体才能形成，说意识不受客体制约，夸大了主体性而取消了反映论前提。","C":"同一客体在不同主体那里得到不同反映，根源在于主体的立场、经验和知识差异，即主体状态影响意识。","D":"意识的形式是主观的，内容是客观的，说内容也主观，就否定了意识的客观来源。"},"memoryTip":"见仁见智错在对象、区别在主体：答主体状态影响意识，别答自由创造。"},"20072":{"solution":"唯心主义把意识看作先于物质、不依赖物质的东西，甚至认为物质是意识的产物。它在意识本质问题上的错误就在于否认意识对物质的依赖性，故选C。","optionAnalysis":{"A":"唯心主义并不否认意识的作用，反而把意识抬高为决定力量，说它否认意识的决定作用是反了方向。","B":"夸大物质对意识决定作用的是机械唯物主义和庸俗唯物主义，不是唯心主义。","C":"唯心主义把意识当成独立自足的本原，割断意识与物质的联系，这是它在意识本质问题上的根本错误。","D":"片面强调意识依赖物质的是旧唯物主义，方向恰好与唯心主义相反。"},"memoryTip":"意识本质两种偏差：唯心不依赖，旧唯物只依赖；辩证唯物论讲依赖又有能动。"},"20073":{"solution":"错误思想内容尽管歪曲，仍是对客观世界的反映，只是把对象的某一方面夸大或颠倒。人脑不会凭空产生观念，其根源终归在客观世界，故选C。","optionAnalysis":{"A":"人脑是思维的器官，判断失误是反映过程中的偏差，器官本身不是思想的来源。","B":"主观想象是意识活动的表现形式，它属于被派生者，不能反过来充当错误思想的最终来源。","C":"意识内容无论正确与否都来自客观世界，错误思想是客观事物在人脑中的歪曲反映，根源仍在客观世界。","D":"用落后的思想意识解释错误思想的来源，是同义反复，并未回答根源问题。"},"memoryTip":"正确思想与错误思想同源，都出于客观世界，区别只在反映得对不对。"},"20074":{"solution":"意识本身不能直接改变物质，只有通过实践活动，把观念转化为行动、把目的物化到对象上，才能引起客观世界的变化，故选B。","optionAnalysis":{"A":"主观努力属于意识范围内的状态，不超出观念领域，无法直接作用于客观事物。","B":"实践是主观见之于客观的物质活动，意识的反作用必须借助实践这一中介才能实现，故为基本途径。","C":"科学活动只是实践的一种具体形式，外延过窄，不能涵盖意识反作用的一般途径。","D":"思想斗争发生在观念领域，仍在主观范围之内，不能转化为对客观世界的实际改变。"},"memoryTip":"意识想不动物体，必须靠做：见反作用途径就选社会实践，别选主观努力。"},"20075":{"solution":"荀子说心不在焉，黑白在前也看不见、雷鼓在侧也听不到。感官对象客观存在，能否感知取决于心是否专注，说明意识活动具有能动性，故选B。","optionAnalysis":{"A":"客观性指意识内容来自客观世界，本题强调的恰是主体是否用心，落点不在客观来源。","B":"同一感官对象，心不在则视而不见、听而不闻，说明意识不是被动接收，而能主动选择和调节感知。","C":"对象性指意识总是指向一定对象，本题中对象一直存在，问题出在主体的注意状态。","D":"任意性意味着意识可不受制约地随意产生，这本身是错误表述，也非荀子原意。"},"memoryTip":"心不使焉四字是题眼：心不发动就看不见，考能动性，不考客观性。"},"20076":{"solution":"物质与意识的关系是辩证的：物质第一性、决定意识，同时意识具有相对独立性并对物质有能动反作用，既不能颠倒也不能割裂，故选D。","optionAnalysis":{"A":"承认物质决定意识是对的，但否认意识的反作用，退回到机械唯物主义，丢掉了辩证法。","B":"把意识说成决定者、物质反而有能动作用，主次完全颠倒，是唯心主义的表述。","C":"物质决定意识与意识决定物质并列，等于承认两个决定者，滑向二元论。","D":"前半句坚持唯物论的物质决定作用，后半句坚持辩证法的意识能动反作用，完整准确。"},"memoryTip":"一句话锁死：物质决定、意识能动，两个动词不能换位也不能删掉后一个。"},"20077":{"solution":"意识能动作用的发挥有两种结果，关键在于是否符合客观规律。只有正确反映客观规律，观念才能在实践中转化为预期结果，故选C。","optionAnalysis":{"A":"调动个人积极性只是主观条件之一，若方向违背规律，积极性越高危害越大，不能成为前提。","B":"集体智慧有助于形成正确认识，但仍属主观条件，不能替代对客观规律的把握。","C":"意识能动作用必须以尊重客观规律为基础，认识符合规律才能指导实践取得成功，这是根本前提。","D":"克服保守思想是思想解放的要求，与能否正确发挥能动作用没有必然的前提关系。"},"memoryTip":"能动作用的前提永远在客观规律一侧，凡答积极性、智慧、思想的主观条件都排除。"},"20078":{"solution":"在意识作用问题上，唯心主义把意识的能动性无限放大，认为意识可以决定物质、创造世界。其错误正是片面夸大意识的能动作用，故选B。","optionAnalysis":{"A":"否认意识反作用的是机械唯物主义，唯心主义恰恰把反作用夸大到决定一切的程度。","B":"唯心主义脱离物质制约谈意识作用，把能动性膨胀为世界本原，这正是它在意识作用问题上的错误。","C":"片面强调意识依赖物质的是旧唯物主义，与唯心主义的偏向正好相反。","D":"既肯定物质决定作用又强调意识能动作用，是辩证唯物主义的正确观点，不构成错误。"},"memoryTip":"两极对照：唯心夸大，机械唯物否认，辩证唯物论既承认又限定。"},"20079":{"solution":"唯物辩证法研究世界的普遍联系和永恒发展，联系的观点和发展的观点是它的两个总特征，全部规律和范畴都由此展开，故选D。","optionAnalysis":{"A":"矛盾与运动是辩证法的核心内容和根本属性，但教材把总特征专指联系和发展。","B":"绝对与相对是辩证法的一对范畴关系，属具体原理层面，不是理论体系的总体特征。","C":"普遍与特殊是矛盾问题的重要内容，同样属于具体原理，不能概括辩证法的全貌。","D":"联系的观点和发展的观点贯穿辩证法全部规律与范畴，是理论体系的总特征。"},"memoryTip":"总特征只有两个：普遍联系、永恒发展；矛盾是核心，别把核心当特征。"},"20080":{"solution":"辩证法与形而上学在联系、发展、矛盾三个层面都对立，但焦点是是否承认事物内部矛盾。承认矛盾才有联系和发展，否认矛盾必然走向孤立静止，故选C。","optionAnalysis":{"A":"联系观点与孤立观点的对立确实存在，但它是是否承认矛盾这一焦点在外部的表现，不是根本焦点。","B":"发展观点与静止观点的对立同样是表现之一，根源仍在于是否承认内部矛盾推动发展。","C":"是否承认矛盾决定能否坚持联系和发展，否认矛盾就必然孤立静止地看问题，故为对立的焦点。","D":"是否承认质变只是发展观中的具体分歧，层次低于是否承认矛盾这一根本问题。"},"memoryTip":"三对立中矛盾是根：承认矛盾就承认联系和发展，焦点只有这一个。"},"20081":{"solution":"否定之否定规律揭示事物经过两次否定、三个阶段，仿佛回到出发点却在更高阶段。方向是前进的，道路是曲折的，故选B。","optionAnalysis":{"A":"渐进性与飞跃性的统一由量变质变规律揭示，说明发展采取两种状态，不是否定之否定的内容。","B":"两次否定使事物自我完善、螺旋上升，说明总趋势前进而具体道路曲折，正是该规律所揭示的。","C":"斗争性与同一性的统一属于对立统一规律，讲矛盾推动发展，与三段式过程不对应。","D":"共性与个性的统一属于矛盾普遍性与特殊性的关系，是矛盾问题的精髓，与本题规律不符。"},"memoryTip":"三规律分工：量变质变怎么变，对立统一为何变，否定之否定往哪变——螺旋上升。"},"20082":{"solution":"量变与质变的界限在于变化是否突破度的临界。保持在度内是量变，超出度则事物失去原有的质而转化为他物，故选C。","optionAnalysis":{"A":"变化是否显著只是外观感受，量变积累到一定程度同样显著，显著与否不能作为根本标准。","B":"发展是否迅速明显讲的是变化速度，速度快慢与是否发生质变没有必然对应关系。","C":"度是保持事物质的量的界限，变化在度内为量变，越出度则发生质变，这是区分的根本标志。","D":"部分质变发生在总的量变过程之中，本身仍处量变阶段，不能用来划分量变与质变。"},"memoryTip":"一把尺子量到底：过没过度。度内是量变，越度是质变，其它标准都是表面现象。"},"20083":{"solution":"这句话把是与否、真与假绝对对立，不承认对立面之间可以相互渗透、相互转化。这种非此即彼的思维方式正是形而上学的典型特征，故选B。","optionAnalysis":{"A":"唯心主义回答世界本原问题，这句话谈的是思维方法，未涉及物质与精神何者第一性。","B":"只承认对立、否认统一和转化，把事物看成非此即彼的僵死对立，是形而上学思维方式的实质。","C":"诡辩论走另一个极端，它抹煞是非界限、把差别说成没有差别，与绝对对立正好相反。","D":"绝对主义含义笼统，未点明这是一种看待矛盾双方关系的思维方法，不如形而上学准确。"},"memoryTip":"是就是是不是就是否即非此即彼，见绝对对立选形而上学；抹煞界限才选诡辩论。"},"20084":{"solution":"发展不是一般的变化，而是前进上升的变化。其根本内容是旧事物灭亡、新事物产生，新事物具有旧事物无可比拟的优越性，故选B。","optionAnalysis":{"A":"运动变化范围更广，既有前进也有倒退，把发展等同于任何变化就取消了发展的方向性。","B":"新事物产生、旧事物灭亡揭示了发展的实质内容，说明发展是质变中的前进上升。","C":"质变本身有前进与倒退两种可能，笼统说处于不断质变中，不能说明发展为什么是上升的。","D":"由低级到高级、由简单到复杂是发展的表现形态和趋势，实质仍在于新旧事物的更替。"},"memoryTip":"发展实质一句话：新事物产生、旧事物灭亡；低级到高级是表现，运动变化是更大的筐。"},"20085":{"solution":"柳宗元讲天地万物自己运行、自己停息、自己流动，冷热交替推动变化，肯定事物自己运动且由内部对立推动，含朴素辩证法思想，故选B。","optionAnalysis":{"A":"唯心主义把世界本原归为精神，柳宗元讲的是自然万物自身运动，立场是唯物的。","B":"承认事物自动自休、由阴阳冷热交错而变，即承认内在矛盾推动运动变化，属于辩证法观点。","C":"形而上学主张外力推动、静止不变，与自动自休、交错而动的自发运动观相反。","D":"诡辩论故意混淆是非、抹煞确定界限，柳宗元的话讲自然规律，并无此意。"},"memoryTip":"抓自动、交错两词：自己动又对立相交，就是辩证法；靠外力推才叫形而上学。"},"20086":{"solution":"条件指制约事物存在和发展的各种因素。承认一切具体事物都有其存在条件，就是承认联系的条件性，这是辩证唯物论的基本观点，故选C。","optionAnalysis":{"A":"机械论用单一外力机械决定一切，否认事物内部根据，与条件论不是同一命题。","B":"形而上学否认普遍联系，往往脱离条件孤立地看问题，与一切都有条件相冲突。","C":"辩证唯物论认为联系是有条件的，具体事物的存在发展依赖一定条件，条件变了状态也随之改变。","D":"外因论只承认外部条件而否认内因根据，题干并未否定内因，故不能归为外因论。"},"memoryTip":"有条件属于条件论，不等于外因论：外因论的错在只讲外因，题干只讲联系有条件。"},"20087":{"solution":"规律是事物运动发展过程中内在的、本质的、必然的、稳定的联系。它客观存在，不以人的意志为转移，故选C。","optionAnalysis":{"A":"思维对本质的概括和反映是科学规律、科学认识，属于主观反映形式，把客观规律与认识混同了。","B":"把规律当成整理感性材料的思维形式，是康德式的主观建构，否认了规律的客观性。","C":"内在、本质、必然、稳定的联系正是唯物辩证法对规律的界定，抓住了客观性和重复性。","D":"联系和发展的基本环节指内容与形式、本质与现象等范畴，是认识世界的环节，不是规律的定义。"},"memoryTip":"规律四定语：内在、本质、必然、稳定；概括反映讲的是人对规律的认识，不是规律本身。"},"20088":{"solution":"必然与偶然相互依存、相互渗透：必然通过大量偶然开辟道路，偶然背后隐藏着必然。所以必然的东西通过偶然表现，偶然的东西体现着必然，故选D。","optionAnalysis":{"A":"偶然性影响事物发展的速度和具体面貌，甚至使过程出现曲折，说它可以忽略不计是片面的。","B":"偶然性虽难精确预测，但并非不可认识，人们可以通过大量重复把握其统计趋势。","C":"把必然与偶然归结为可选择与不可选择，混淆了客观联系与人的选择，二者都是客观的。","D":"必然寓于偶然之中、通过偶然实现，偶然是必然的表现形式和补充，二者相互贯通。"},"memoryTip":"记必然藏在偶然里：抛硬币每次偶然，次数多了频率稳定就是必然，两者互相包含。"},"20089":{"solution":"事物的性质主要由其本质属性决定，本质属性是内在的、起决定作用的属性。因此区分事物的依据是本质属性，故选A。","optionAnalysis":{"A":"本质属性体现事物的内在根据，决定一事物之所以为该事物，是区分不同事物的根本依据。","B":"各方面属性的总和包含大量非本质属性，仅凭属性堆砌无法抓住性质，反而模糊界限。","C":"量的规定性只能区分同类事物的多少和大小，不能判定事物在性质上的差别。","D":"以人的直觉作为区分依据，把客观标准换成了主观感受，违背唯物主义的认识路线。"},"memoryTip":"区分靠本质不靠总和：属性加起来只是清单，本质属性才定性质。"},"20090":{"solution":"度是保持事物质的稳定性的量的限度、幅度和范围，是质与量的统一。在度内事物保持自身，越出度则发生质变，故选C。","optionAnalysis":{"A":"关节点是度的两端、量变引起质变的转折处，是度的界限所在，不等于度本身。","B":"临界点同样指度两端的界限，把一个点当成了整个区间，范围理解错误。","C":"度是事物能够保持自身质的量的活动区间，表述完整，涵盖了质与量两个方面。","D":"保持一定量丢掉了质，度量统一体的落脚点是保持一定的质，故表述不准确。"},"memoryTip":"度是区间，关节点是端点：问度答范围，问关节点才答临界点。"},"20091":{"solution":"过是超出度，不及是未达到度，两者都偏离了事物的度。防止这两种偏向的办法就是把握度，在度的范围内推进工作，故选D。","optionAnalysis":{"A":"抓主要矛盾讲的是工作重点，解决轻重缓急问题，与把握分寸、防止过头或不足无关。","B":"认识事物的量是把握度的必要条件，但仅知道数量还不能判定何处为过、何处为不及。","C":"确定事物的质解决是什么的问题，不能回答做到什么程度才合适。","D":"度规定了质量统一的界限，把握住度就能恰到好处，避免过头与不足两种偏向。"},"memoryTip":"过与不及都是两头越界，中间那条线就是度；防偏靠适度，不靠抓重点。"},"20092":{"solution":"鲁迅批评的是写人过了头：为显刘备仁厚反而像虚伪，为显诸葛亮多智反而近乎妖异。人物塑造超出恰当分寸而走向反面，说明要把握事物的度，故选B。","optionAnalysis":{"A":"两重性指事物同时具有正面与反面，鲁迅说的是刻画失度而走向反面，不是讲两面并存。","B":"优点写到极端就转化为缺陷，正是超出度的表现，启示做事要适度、防止过犹不及。","C":"既肯定又否定是辩证否定观的内容，用于对待旧事物，与人物描写的分寸问题不对应。","D":"把事物看作整体强调整体与部分的关系，与写过头这一失度现象无关。"},"memoryTip":"似伪、近妖都是过了头：优点写到极端变缺点，答案永远落到度。"},"20093":{"solution":"自由竞争到垄断，资本主义的根本性质没有改变，仍是资本主义；但阶段特征发生根本变化，属于总的量变过程中的部分质变，故选C。","optionAnalysis":{"A":"根本性质变意味着资本主义被否定，而垄断阶段仍属资本主义，社会形态性质未变。","B":"单纯量变忽略了垄断取代自由竞争带来的阶段性根本变化，对变化程度估计不足。","C":"社会形态未变是总量变，自由竞争转为垄断是阶段性质变，二者统一即部分质变。","D":"质变过程中量的扩张指质变发生时新质在数量上迅速扩展，与阶段更替不是同一情形。"},"memoryTip":"同一社会形态内部换阶段叫部分质变，社会形态被替换才叫根本质变。"},"20094":{"solution":"总量不变、仅调整排列结构就引起性质变化，说明量变既包括数量增减也包括构成方式变化，结构变化达到一定程度同样引起质变，这是唯物辩证法观点，故选D。","optionAnalysis":{"A":"形而上学只承认数量增减，把结构变化排除在量变之外，否认结构也能引起质变。","B":"诡辩论混淆是非界限，本题讲的是结构变化与质变关系的客观原理，与之无关。","C":"唯心主义夸大意识作用，本题讨论物质结构的客观变化，不涉及意识第一性问题。","D":"唯物辩证法认为量变包括数量增减和构成方式变化，结构改变到一定程度即引起质变。"},"memoryTip":"量变两条路：加数量、换排列；同素异形体就是结构变引起质变的现成例子。"},"20095":{"solution":"扬弃是辩证否定的实质，包含克服与保留双重含义：克服旧事物中过时的东西，保留其中积极合理的因素，故选D。","optionAnalysis":{"A":"彻底抛弃是形而上学的否定观，把否定看成简单消灭，割断了新旧事物之间的联系。","B":"非连续性只是否定的一个方面，否定是发展的环节，但扬弃还包含继承，不能只讲一半。","C":"连续性讲的是肯定和继承的一面，同样只是扬弃的一个侧面，单讲连续会走向保守。","D":"既克服又保留，既有所否定又有所继承，才能实现新旧事物的联系与发展，是扬弃的完整含义。"},"memoryTip":"扬弃等于克服加保留，两个词缺一不可；彻底抛弃是形而上学，全盘照搬是保守。"},"20096":{"solution":"蝴蝶效应强调初始的微小扰动经过一系列中间环节逐步放大，最终影响远处事物。它说明事物可以通过中介链条发生联系，故选D。","optionAnalysis":{"A":"联系的普遍性是说事物总处在联系之中，蝴蝶效应讲的是具体传导链条，并未把联系扩大到无边无际。","B":"该说法描述的是客观的因果传导过程，并非把联系说成主观随意，与否认客观性无关。","C":"蝴蝶效应恰恰展示了直接联系与间接联系等多样形式，不是否认联系的多样性。","D":"微小扰动经大气运动等一连串中介环节放大传导，体现了事物通过中间环节相互联系。"},"memoryTip":"蝴蝶效应就是中介链条：一个传一个，答案落在通过一系列中间环节发生联系。"},"20097":{"solution":"童谣从缺一枚钉子推到最后国家灭亡，一环扣一环地传导。这正说明事物处在普遍联系之中，微小环节也能牵动全局，故选A。","optionAnalysis":{"A":"钉子、蹄铁、战马、骑士、战事、国家层层相连，任一环节缺失都影响整体，体现联系的普遍性。","B":"童谣呈现的是一条因果链条而非单纯的状态更替，事物是变化的过于笼统，抓不住传导关系。","C":"现象与本质的关系讲外在表现和内在根据，童谣里没有透过现象看本质这一层。","D":"发展曲折性讲前进中的反复，童谣讲的是连锁影响，不涉及发展的道路问题。"},"memoryTip":"一环扣一环就是普遍联系，别把因果链条答成变化或曲折性。"},"20098":{"solution":"对立统一规律揭示事物发展的源泉和动力，是理解其他规律和范畴的钥匙，因而在唯物辩证法体系中处于核心地位，故选D。","optionAnalysis":{"A":"量变质变规律回答发展的状态和形式，是基本规律之一，但不处于核心位置。","B":"否定之否定规律回答发展的方向和道路，其内容同样要靠对立统一来说明。","C":"普遍联系和永恒发展是唯物辩证法的总特征和研究对象，不是体系内部的核心。","D":"对立统一规律揭示了普遍联系的根本内容和发展的内在动力，是领会整个辩证法体系的钥匙。"},"memoryTip":"核心是对立统一，总特征是联系发展，两大特征三大规律不能串位。"},"20099":{"solution":"毛泽东在《矛盾论》中指出，矛盾的普遍性与特殊性、共性与个性、绝对与相对的关系，是关于事物矛盾问题的精髓，故选A。","optionAnalysis":{"A":"共性个性、绝对相对的道理贯穿矛盾学说全部内容，不懂它就不能理解矛盾问题的其他方面，故称精髓。","B":"同一性与斗争性的关系讲矛盾的基本属性，是理解矛盾运动的起点，但不被称为精髓。","C":"主要矛盾与非主要矛盾讲矛盾和矛盾群的不平衡，属于矛盾特殊性原理的具体运用。","D":"矛盾主要方面与非主要方面讲矛盾双方地位不平衡，用于确定事物性质，同样不是精髓。"},"memoryTip":"精髓只记共性与个性，这是《矛盾论》原话；主次矛盾、主次方面只是重要内容。"},"20100":{"solution":"列宁指出马克思主义的最本质的东西、活的灵魂就在于具体地分析具体情况，毛泽东在《矛盾论》中引述这一思想，强调不同矛盾要用不同方法解决，故选D。","optionAnalysis":{"A":"分析同一性与斗争性属于矛盾基本属性的理论说明，是具体分析的工具之一，不等于活的灵魂。","B":"分析主次矛盾是抓重点的方法，仍属具体分析在特定情形下的运用，层次更低。","C":"分析内外因关系说明发展的根据与条件，同样是具体分析所涉及的一方面内容。","D":"具体情况具体分析要求从矛盾特殊性出发区别对待，是马克思主义方法论的根本要求，故称活的灵魂。"},"memoryTip":"活的灵魂一句话记死：具体分析具体情况；其余三项都是这条原则下的具体操作。"},"20101":{"solution":"题干把“联系”当作哲学范畴来界定，题眼在于联系不是相似性，而是关系中的相互作用。教材的规范表述是事物之间以及事物内部诸要素之间的相互影响、相互制约和相互作用，只有C把作用的三种形态说全了。","optionAnalysis":{"A":"“有共同点”说的是事物之间的相似或共性，属于比较之后得出的结果，而联系强调彼此影响、彼此制约，相似并不等于相互作用。","B":"“统一的物质世界的一部分”回答的是世界本原问题，属于世界的物质统一性原理，不是联系范畴的内涵。","C":"相互影响、相互制约、相互作用，正是教材对联系的界定，既包括事物之间，也包括事物内部诸要素之间的关系。","D":"“没有确定的界限”取消事物之间的区别，是相对主义和诡辩论的说法，反而否认了具体联系的存在。"},"memoryTip":"记“三相互”口诀：相互影响、相互制约、相互作用。联系是关系中的作用，看到“有共同点”立即排除。"},"20102":{"solution":"董仲舒把古今天下视为完全同一，实质是否认社会历史的变化更替，用静止不变的目光看待事物。辩证法确认运动变化发展，这种否认发展的主张只能归入形而上学。","optionAnalysis":{"A":"唯物论回答的是物质与精神何者为本原，此话没有讨论世界本原，只是断言古今无变化，与唯物论不构成对应。","B":"唯心论指以精神为第一性，此句并未把世界本原归给精神，它的问题出在发展观而非本原观。","C":"辩证法确认事物处在运动变化发展之中，而这句话恰恰抹掉了古今差别，与辩证法方向相反。","D":"把古今之天下看作始终同一，否认事物的运动变化和发展，正是孤立、静止看问题的形而上学观点。"},"memoryTip":"听到“古今一样、始终不变”就判形而上学；变化发展归辩证法，这是发展观上的一对死对头。"},"20103":{"solution":"题眼在“不仅……也……”的递进：既承认对立双方界限分明，又承认在一定条件下界限可以打通。既看到确定界限又看到相互贯通，正是辩证思维区别于非此即彼的形而上学的标志。","optionAnalysis":{"A":"形而上学只承认“非此即彼”，把对立绝对化，恰好排斥“亦此亦彼”，与题干态度相反。","B":"诡辩论把“亦此亦彼”绝对化，抹杀事物质的规定性，变成怎么都行，而题干仍保留了“非此即彼”这一面。","C":"辩证法既看到对立面的确定界限，又看到条件变化中的相互过渡，两句并存正是辩证思维的完整表达。","D":"不可知论怀疑人能否认识世界，讨论的是认识的界限，与题干讲事物界限的相对性不是同一问题。"},"memoryTip":"口诀“既此既彼是辩证，只此只彼是形而上学，啥都行是诡辩”，三个词对应三种立场。"},"20104":{"solution":"矛盾的同一性回答对立面之间相互联结的一面，教材表述为相互依存、相互贯通的性质和趋势，含双方互为存在前提以及在一定条件下相互转化两层意思。抓住“相互依存、相互贯通”即可锁定答案。","optionAnalysis":{"A":"相互排斥、相互分离的性质和趋势是矛盾的斗争性，方向恰好与同一性相反。","B":"同一性是包含差别和对立的同一，把同一说成完全一致，等于取消了矛盾本身。","C":"相互依存指双方互为存在条件，相互贯通指一定条件下相互转化，这正是同一性的规范表述。","D":"同一以差别和对立为前提，双方无差别、完全等同属于抽象同一，是形而上学而非辩证法。"},"memoryTip":"同一性管“联”，斗争性管“分”：依存加贯通是同一性，见到“完全一致”一律排除。"},"20105":{"solution":"矛盾转化不是随意变向，而是对立面走向自己相反的一方，如失败中孕育成功、坏事可以引出好结果。转化的方向由对立面之间的内在联系决定，同时离不开一定条件。","optionAnalysis":{"A":"说可以向任何方向转化，等于取消了对立面的确定关系，是相对主义、诡辩论的说法。","B":"矛盾双方因相互贯通而在一定条件下走向自己的对立面，这是转化方向的确定含义。","C":"由坏向好只是转化的一种情形，事实上好事也可能变坏，此说把转化范围缩小了一半。","D":"由低级向高级概括的是事物发展的总趋势，不能用来界定矛盾双方的相互转化。"},"memoryTip":"抓“对立面”三个字：转化是走到自己的对面，既不是随便走，也不是必然变好。"},"20106":{"solution":"主要矛盾与次要矛盾讲的是诸多矛盾之间的地位差别：主要矛盾在矛盾体系中居支配地位，对事物发展过程起决定作用。凡选项落到“矛盾方面”的，说的都是同一矛盾内部的主次，必须分开。","optionAnalysis":{"A":"这描述的是矛盾的主要方面，它讲一对矛盾内部谁居支配地位，而不是矛盾体系中的主要矛盾。","B":"处于支配地位、对事物发展过程起决定作用的矛盾，正是主要矛盾的规定，与题干吻合。","C":"处于从属地位、对事物发展不起决定作用的是非主要矛盾，恰好是主要矛盾的反面。","D":"贯穿事物发展始终并规定事物及其过程性质的是根本矛盾，它与主要矛盾不是同一概念。"},"memoryTip":"矛盾之间分主次叫主要矛盾，一个矛盾内部两方面分主次叫主要方面；看清“体系”还是“方面”。"},"20107":{"solution":"题干先设定“同质”，即质上相同、没有质的差别，此时把同类事物区分开的只能是量的规定，如规模、速度、程度、结构比例。质相同则度也相同，唯一能当尺子的只剩量。","optionAnalysis":{"A":"度是保持事物质的稳定性的量的限度，同质事物的度相同，无法据此把它们分开。","B":"同质事物之间没有质的差异，区别只能落在量的规定性上，量的不同使同类事物彼此有别。","C":"规定性兼含质和量两个方面，笼统提规定性没有点出在同质前提下真正起作用的那一面。","D":"特殊矛盾规定事物的质，特殊矛盾不同就意味着质不同，与题干设定的“同质”直接冲突。"},"memoryTip":"题眼是“同质”二字：质已经被锁定，区别的尺子只剩“量”，质同则量异。"},"20108":{"solution":"矛盾即对立统一，其基本属性只有两个：同一性指对立面相互依存、相互贯通，斗争性指相互排斥、相互分离。二者相互联结，共同构成矛盾的两种基本属性。","optionAnalysis":{"A":"普遍性和特殊性讲的是矛盾的共性与个性，被称为矛盾问题的精髓，不是矛盾自身的属性。","B":"同一性与斗争性正是矛盾的两个基本属性，一个讲联结，一个讲排斥，缺一不成其为矛盾。","C":"绝对性和相对性多用于描述真理、认识或运动，属于另一组范畴，不是矛盾的属性划分。","D":"对抗性与非对抗性区分的是矛盾斗争的形式，是斗争性的表现方式，不是基本属性本身。"},"memoryTip":"矛盾属性只此一对：同一性加斗争性。普遍性特殊性是“精髓”，对抗非对抗是“形式”，都不能顶上。"},"20109":{"solution":"主要矛盾与非主要矛盾、主要方面与非主要方面的原理落到方法论，要求既全面看问题、不遗漏次要矛盾，又抓住重点、不平均用力，这就是两点论与重点论的统一。","optionAnalysis":{"A":"均衡论主张各方面平均看待、不分主次，正是两点论和重点论要反对的错误倾向。","B":"一点论只抓一点不及其余，与均衡论一样都是片面性，两个错误拼不成正确方法。","C":"两点论要求兼顾主次，重点论要求抓住主要矛盾和主要方面，二者统一才是正确方法论。","D":"一点论否认次要矛盾和次要方面的存在，与两点论正相反，二者无法统一。"},"memoryTip":"方法论口径固定为“两点论加重点论”；出现“均衡论”“一点论”的选项整句报废。"},"20110":{"solution":"事物内部都包含肯定和否定两方面：肯定方面维持事物存在，否定方面促使事物灭亡、推动事物向新质转化。题干问否定方面，落点就是“促使其灭亡”。","optionAnalysis":{"A":"“处于主导地位”没有说明主导的是维持还是瓦解，且哪一方居主导取决于具体条件，不能用作定义。","B":"否定方面不等于消极方面，辩证否定是扬弃，是新事物产生的环节，把它等同于消极是误解。","C":"维持事物存在的方面是肯定方面，与题干所问的否定方面正好相反。","D":"促使事物灭亡、促成质变的方面正是否定方面，它是事物自我否定和发展的内在根据。"},"memoryTip":"肯定＝维持存在，否定＝促其灭亡；还要记住否定是扬弃不是“消极”，这里最易设坑。"},"20111":{"solution":"两句诗都用“新”取代“旧”的画面：沉舟旁边千帆竞发，病树前头万木争春，新叶催陈叶、前波让后波。共同指向的哲学道理是新事物必然战胜旧事物这一发展的总趋势。","optionAnalysis":{"A":"矛盾是事物发展的动力，讲的是内部对立推动变化，诗句没有展示对立面又斗争又统一的过程。","B":"本质与现象的统一讲如何透过现象把握本质，诗句属于新旧更替而非表里关系。","C":"量变质变的统一强调积累与飞跃，诗句中并未出现数量积累达到质变的环节。","D":"新事物代替旧事物不可抗拒，正是两首诗共同表达的发展总趋势，与题干诗意吻合。"},"memoryTip":"诗中见“新叶催陈叶、前波让后波”，一律归到“新事物代替旧事物”，不必往矛盾或量变上靠。"},"20112":{"solution":"“白马非马”把“白”这一属性与“马”这一共性割裂，用个别否认一般。马是共性，白马是带色的个别，个别之中包含一般，不能说个别不是一般，错误就在割裂普遍性与特殊性的关系。","optionAnalysis":{"A":"内因外因讲事物发展的根据与条件，公孙龙的命题不涉及发展动力问题。","B":"同一性与斗争性讲对立面的联结与排斥，此命题的错误不在对立面之间的关系上。","C":"主要方面与次要方面讲一对矛盾内部的主次，白马非马不是主次颠倒的问题。","D":"共性与个性相互联结，白马作为个别包含马的共性，割裂普遍性与特殊性正是症结所在。"},"memoryTip":"“白马非马”本质是以个性否认共性，答案口径是“割裂矛盾的普遍性和特殊性”。"},"20113":{"solution":"“不积跬步”“不积细流”强调点滴积累，“至千里”“成江海”是积累达到一定程度后的飞跃。全句讲的是量变积累到一定程度必然引起质变。","optionAnalysis":{"A":"跬步、细流的积累是量变，至千里、成江海是质变，说明质变由量变积累引起，与题干吻合。","B":"因果关系被颠倒，是量变引起质变，而非质变引起量变。","C":"相互渗透指量变中包含部分质变、质变中有量的扩张，题干只展示积累引起飞跃，未涉及渗透。","D":"否认量变的作用与题干强调积累正好相反，量变是质变的必要准备。"},"memoryTip":"见到“积”字就往量变上想：积少成多、积小成大，对应量变引起质变。"},"20114":{"solution":"三大规律各有分工：对立统一回答事物为什么发展，质量互变回答发展呈现什么状态，否定之否定回答发展走什么道路。题干问对立统一规律，落点就是发展的源泉和动力。","optionAnalysis":{"A":"“辩证形式”不是对立统一规律的专属表述，讲发展的状态和形式的是质量互变规律。","B":"趋势和道路由否定之否定规律揭示，指前进性与曲折性的统一。","C":"不同状态指量变与质变两种基本状态，属于质量互变规律的内容。","D":"矛盾是事物发展的源泉和动力，对立统一规律正是从内部矛盾说明发展的原因，与题干吻合。"},"memoryTip":"三规律三问：对立统一答“为什么”，质量互变答“什么样”，否定之否定答“往哪走”。"},"20115":{"solution":"否定之否定规律讲两次否定、三个阶段，呈现螺旋式上升、波浪式前进，回答的是事物发展的方向和道路问题。题干问这一规律揭示什么，就要答方向道路。","optionAnalysis":{"A":"前进性与曲折性的统一就是发展的方向和道路，正是否定之否定规律所揭示的内容。","B":"形式和状态是质量互变规律的落点，量变与质变讲的才是发展的状态。","C":"结构和功能属于系统论的范畴，讲要素配置与作用，与三大规律的分工不对应。","D":"源泉和动力由对立统一规律揭示，来自事物内部矛盾，不是否定之否定规律。"},"memoryTip":"否定之否定＝螺旋上升，认“方向道路”；题目问“往哪走”就选它，问“为什么”才选动力。"},"20116":{"solution":"质量互变规律讲事物发展经过量变和质变两种状态，通过量变到质变的飞跃实现发展，因此揭示的是发展的状态和形式，而不是方向和动力。","optionAnalysis":{"A":"把质量互变规律概括为“辩证形式”过于笼统，教材落点是发展的状态，不是泛泛的形式。","B":"量变与质变是发展的两种基本状态，交替飞跃构成发展的形式，与题干吻合。","C":"方向和道路由否定之否定规律揭示，指螺旋式上升、波浪式前进。","D":"源泉和动力属于对立统一规律的内容，讲内部矛盾如何推动发展。"},"memoryTip":"质量互变的标准落点是“状态和形式”，与“方向道路”“源泉动力”三分天下，各有归属。"},"20117":{"solution":"同一片风景，忧心的穷人与贩卖矿物的商人感受不同，说明感觉不是被动复印对象，而受主体的需要、处境和知识结构制约，这正是人的感觉具有主体性。","optionAnalysis":{"A":"先验论主张认识先于经验而存在，题干强调的是现实处境对感觉的塑造，不是天赋观念。","B":"主观唯心主义把世界归于主观精神，题干并未否认风景的客观存在，只是说感受因人而异。","C":"感觉受主体需要、利益和知识背景影响而呈现差别，正是感觉主体性的表现，与题意吻合。","D":"经验论讨论知识是否全部来自经验，题干讲的是不同主体对同一对象感受不同，不涉及这一争论。"},"memoryTip":"同一对象、不同感受＝主体性；变的不是对象，而是主体的处境和需要筛选了感觉。"},"20118":{"solution":"“洞中方七日，世上几千年”用神话夸张表现同一段时间在不同境遇中长短悬殊，说明时间的具体特性随物质运动状态和参照条件而变化，体现的是时间的相对性。","optionAnalysis":{"A":"时间的客观性指时间不依人的意志为转移，诗句并未否认这一点，讲的是长短的相对。","B":"时间的有限性讲具体事物有时间起止，诗句不是讨论物质运动过程是否有始有终。","C":"可知性讲人能不能认识时间，诗句没有涉及认识能力问题。","D":"“七日”对“几千年”的悬殊，说明时间的具体度量依赖条件，正是时间相对性的生动体现。"},"memoryTip":"“七日”撞上“千年”就是相对性；客观性说的是时间不由人定，两问方向完全不同。"},"20119":{"solution":"滥挖甘草当下换来经济收益，是眼前的直接联系；植被破坏、土地荒漠化、沙尘暴成灾，要经过若干中间环节才显现，是长远的间接联系。挖甘草者只算眼前账，忽略了后者。","optionAnalysis":{"A":"他们恰恰只盯经济收益这一客观事实，并未否认客观性，也不是主观能动性发挥过度的问题。","B":"题干不涉及运动与静止的关系，土地荒漠化本身就是长期变化积累的结果。","C":"得利是眼前直接联系，生态灾难是长远间接联系，只顾前不顾后，正是题干所指。","D":"挖甘草既改变物与物的关系也改变人与人的关系，但题干的落点在时间跨度上的直接与间接之分。"},"memoryTip":"生态类材料的万能题眼：眼前得利是直接联系，长远受害是间接联系，答案几乎必选此项。"},"20120":{"solution":"和谐社会强调和而不同、协调共存、互利共赢，其哲学依据在于矛盾双方相互依存、相互贯通，可以在一定条件下共存共荣，这就是矛盾的同一性原理。","optionAnalysis":{"A":"矛盾普遍性说明处处有矛盾，为承认矛盾提供依据，但不能直接说明为什么应当和谐共处。","B":"斗争性强调对立面的排斥与冲突，用来说明矛盾的不可调和，与构建和谐社会的取向不合。","C":"同一性讲对立面相互依存、相互贯通，正是求同存异、协调发展的直接辩证法依据。","D":"特殊性要求具体问题具体分析，是工作方法的依据，不是和谐共处的直接依据。"},"memoryTip":"和谐取“同”：同一性讲依存与贯通，是和谐社会的直接依据；斗争性讲冲突，方向不对。"},"20121":{"solution":"历史是客观过程，是逻辑的基础；逻辑是思维对历史的概括再现，需要舍弃偶然、抓住本质，故称对历史的“修正”。这一表述既坚持历史的第一性，又肯定逻辑的能动概括，属于历史与逻辑相统一。","optionAnalysis":{"A":"主观唯心主义会把逻辑抬到历史之上，而题干明确说历史是逻辑的基础，方向正相反。","B":"历史为逻辑提供基础，逻辑对历史作本质层面的修正再现，正是二者相统一的表述。","C":"题干同时承认历史的基础地位和逻辑的修正作用，并非单方面抬高逻辑。","D":"割裂会表现为只要历史不要逻辑，或只要逻辑不要历史，题干把两者联系起来而非割裂。"},"memoryTip":"“基础”加“修正”两句并存＝历史与逻辑相统一；只剩一半才是割裂，别被“修正”二字带偏。"},"20122":{"solution":"个别到一般是归纳，从大量个别事实中概括共同本质；一般到个别是演绎，用一般原理推出对个别事物的结论。题干给出正是这两个往返方向，对应归纳与演绎。","optionAnalysis":{"A":"归纳由个别走向一般，演绎由一般走向个别，与题干两个方向一一对应。","B":"分析与综合处理的是整体与部分的关系，把对象拆解或整合，不涉及个别与一般的往返。","C":"从抽象到具体是由抽象规定上升为思维具体，走的是另一条思维道路，方向不对应。","D":"实践到认识讲认识的来源与形成过程，不是思维形式的划分。"},"memoryTip":"“个别↔一般”背“归纳↔演绎”；“整体↔部分”才是分析与综合，两对别对调。"},"20123":{"solution":"唯物辩证法的一系列方法中，矛盾分析方法居于核心地位，因为对立统一规律是辩证法的实质和核心，所以它是认识世界和改造世界的根本方法。","optionAnalysis":{"A":"具体问题具体分析是矛盾特殊性原理的要求，是重要方法，但属于矛盾分析方法的具体运用。","B":"实事求是是党的思想路线的核心，属于思想路线层面，不是辩证法意义上的根本方法。","C":"矛盾分析方法由辩证法的核心规律决定，是认识世界和改造世界的根本方法，与题干吻合。","D":"辩证否定方法用于对待新旧事物，是辩证法的一个具体方法，不居根本地位。"},"memoryTip":"“根本方法”固定搭配矛盾分析方法，理由链是：对立统一是实质和核心，方法跟着规律走。"},"20124":{"solution":"系统是由相互联系的要素按一定结构组成的整体，系统的存在说明联系不是抽象口号，而是通过具体要素、具体结构、具体功能实现，体现物质世界普遍联系的具体性。","optionAnalysis":{"A":"系统以要素、结构、功能展现联系的实际形态，正是普遍联系具体性的体现，与题干吻合。","B":"曲折性讲发展道路的起伏反复，系统本身不涉及前进中的迂回。","C":"过程性讲事物有产生、发展和灭亡的历史，系统侧重同时态的结构联系。","D":"总体趋势指发展方向，系统讲的是内部要素的联结方式，不是趋势问题。"},"memoryTip":"系统＝要素加结构加整体功能，落点在“联系的具体性”；一旦选项谈发展道路、趋势就离题。"},"20125":{"solution":"客观辩证法是自然界和人类社会自身的辩证运动，主观辩证法是这一运动在人脑中的反映，即思维的辩证法。二者内容同一、形式不同，本质上是统一的，而不是两套并列的辩证法。","optionAnalysis":{"A":"说包含关系会颠倒基础，主观辩证法是对客观辩证法的反映，二者是反映与被反映的关系。","B":"把二者说成两种不同的辩证法，等于承认有两套辩证法，抹掉了思维对存在的反映关系。","C":"绝对对立会切断思维与存在的联系，无法解释思维规律为何能把握客观世界。","D":"主观辩证法是客观辩证法的自觉反映，内容一致、形式有别，本质上统一，与题干吻合。"},"memoryTip":"一个内容、两种形式：客观在先，主观是反映，结论永远落在“本质上统一”。"},"20126":{"solution":"气候由纬度、地形等稳定因素与大气环流、洋流交互作用而形成，某一因素突然“掉链子”引发厄尔尼诺，说明偶然因素虽不决定趋势，却能扰动进程、改变表现。因此偶然因素不可忽视。","optionAnalysis":{"A":"决定发展趋势的是必然因素和内部根据，偶然因素只影响进程的快慢与样态，不能起根本决定作用。","B":"偶然因素会影响发展的速度和具体形式，说它可有可无就否认了它对进程的实际作用。","C":"厄尔尼诺这一偶然扰动连锁引发极端天气，说明偶然因素不可忽视，与题干吻合。","D":"确定不移是必然性的特征，偶然恰恰是不确定的，把偶然说成确定不移混淆了二者。"},"memoryTip":"必然定趋势，偶然定样态：偶然不决定方向但能添乱，标准答案落在“不可忽视”。"},"20127":{"solution":"同一品种在淮南为橘、在淮北为枳，果实味道不同，原因被点明为“水土异也”。这说明条件改变会导致事物性质改变，即发展变化以时间、地点和条件为转移。","optionAnalysis":{"A":"水土就是条件，条件变则果实之性变，正是变化以时间地点条件为转移，与题干吻合。","B":"中介说讲联系需要中间环节，题干并未讨论通过什么环节衔接，而是讲条件对性质的影响。","C":"网结说讲每一事物都处在联系之网中，侧重联系的普遍性，不解释同种为何异地变味。","D":"过程性讲事物的历史发展，题干比较的是两地并存的橘与枳，不是同一物的历时过程。"},"memoryTip":"“水土异也”四字就是条件，见条件改变引起性质改变，选“以时间地点条件为转移”。"},"20128":{"solution":"“马”命形，是共性；“白”命色，是个性。公孙龙由“命色者非命形”推出白马非马，是用个性否认共性、割裂共性与个性的联系，在辩证法上就是割裂矛盾普遍性与特殊性的联系。","optionAnalysis":{"A":"形态与功能的关系讲结构与作用，命题讨论的是名与实的概念关系，不涉及功能问题。","B":"马为共性、白马为个性，个性之中包含共性，割裂二者联系正是该命题的错误所在。","C":"内容与形式讲内在要素与外在表现方式，白马非马不是形式脱离内容的问题。","D":"本质与现象讲表里关系，而题干的核心是一般与个别、共性与个性的关系。"},"memoryTip":"两处“白马非马”同一考点：本质都是以个性否认共性，表述换成“割裂普遍性与特殊性”即可。"},"20129":{"solution":"题干强调“天帮忙很重要，但人努力才是根本”，即治霾既要按大气运动规律办事，又要主动减排。这正说明尊重客观规律是正确发挥主观能动性的前提。","optionAnalysis":{"A":"承认规律、按规律办事，人的努力才有效，这正是尊重客观规律作为发挥主观能动性前提的含义。","B":"掌握客观规律的根本前提是实践，把有意识的思想活动当作根本前提，颠倒了实践与认识的关系。","C":"客观规律性与主观能动性相统一的基础是实践，不是认识活动。","D":"题干落点是被认识和把握的规律如何指导治霾，强调的是尊重规律，此项与主旨偏离。"},"memoryTip":"“人努力才是根本”不等于唯意志论，而是先尊规律再发挥：规律始终排在能动性前面。"},"20130":{"solution":"该观点从“意识是反映”直接推出“鬼神意识必有鬼神对象”，把反映理解为照镜子式的直接对应，忽视了意识对感性材料的加工改造和虚幻联结。错误在于把意识当成对存在的直观反映。","optionAnalysis":{"A":"这种观点把人脑中的鬼神形象直接安到外部世界，是缩小而非夸大意识的能动创造作用。","B":"意识是物质的产物这一判断本身正确，不是该观点的错误所在，问题出在反映方式的简单化。","C":"直观反映论认为有什么影像就必有什么对象，忽略意识的加工与虚构能力，正是错误所在。","D":"题干不涉及人类意识自然演化的阶段问题，与从动物心理到人类意识的演进无关。"},"memoryTip":"鬼神意识的错在“照镜子”：反映是能动加工，不是一一对应的直观摹写。"},"20131":{"solution":"少量盐提味，一把盐入口又苦又咸，同一事物在不同数量下性质相反，说明必须把握事物的度。寓言给人的启示是在认识和实践中掌握适度原则，防止过犹不及。","optionAnalysis":{"A":"量变引起质变本身不错，但寓言的重心不是积累必然飞跃，而是超过限度就走向反面。","B":"盐适量则美、过量则苦，说明要把握度的界限、坚持适度原则，与寓言吻合。","C":"断言现象不能通向本质，属于不可知论，与人们可以透过现象认识本质的原理相违。","D":"自我否定讲新事物取代旧事物，寓言讲的是同一事物因量超过限度而变味，不是自我否定。"},"memoryTip":"“加一点好、加一把坏”就是度的界限，答“适度原则”；别一看到积累就去选量变质变。"},"20132":{"solution":"前一种观点把自由理解为认识规律并据以有计划地支配规律为人的目的服务，既承认规律客观性又肯定人的能动性，是唯物辩证的自由观；后一种把自由说成随心所欲，否认规律制约，是唯意志论。","optionAnalysis":{"A":"前者承认规律并强调认识利用规律，属唯物辩证观点；后者鼓吹随心所欲不受规律约束，属唯意志论，判断正确。","B":"机械唯物主义只讲规律决定、否认人的能动选择，而前者明确讲为一定目的服务，不是机械决定论。","C":"把前者判为主观唯心主义、后者判为唯物辩证法，恰好把两种性质颠倒过来。","D":"这组观点讨论自由与必然的关系，属于认识论问题，不是历史观上的唯心与唯物之分。"},"memoryTip":"自由两派对照记：认识并利用规律＝唯物辩证；“由自”即随心所欲＝唯意志论。"},"20133":{"solution":"题干限定“从实践的活动机制看”，即把实践解剖为主体、客体、中介三个要素及其相互作用。主体借助工具手段等中介能动地作用于客体，构成现实的实践过程。","optionAnalysis":{"A":"主体借助中介能动地作用于客体，正是实践活动的运行机制，与题干限定吻合。","B":"道德行为和政治活动属于实践的具体形式，是个别形态，不是活动机制层面的界定。","C":"科学实验是实践的基本形式之一，同样是个别形式，不能概括实践的一般机制。","D":"这是对实践的通俗化描述，未揭示主体、中介、客体的结构关系，与“活动机制”不对应。"},"memoryTip":"题眼是“活动机制”：主体—中介—客体三元结构；若问“有哪些形式”才答生产、社会政治、科学实验。"},"20134":{"solution":"实践主体不是笼统的人，而是具备相应能力、实际参与改造世界活动的人。主体能力包括知识经验、技能方法等，能力与活动缺一不可，因此要把“人”限定为从事现实实践的人。","optionAnalysis":{"A":"绝对精神是黑格尔式的客观精神实体，把实践主体归给它，属于客观唯心主义。","B":"具有主体能力并从事现实社会实践活动的人，构成实践主体的完整规定，与教材表述一致。","C":"只说“人”过于宽泛，尚未从事实践活动、不具备相应能力的人并不能现实地充当主体。","D":"意识是主体的属性与机能，把意识当主体，是唯心主义的主体观。"},"memoryTip":"主体＝人＋能力＋现实活动，三个条件齐了才算；光看到“人”字就选，最容易失分。"},"20135":{"solution":"实践客体是实践活动所指向的对象，只有进入主体实践范围、被主体实际作用的那部分世界才成为客体。客观世界范围更大，未纳入实践领域的部分仍是自在之物。","optionAnalysis":{"A":"把客体说成绝对精神的对象化，是客观唯心主义表述，取消了客体的客观实在性。","B":"客观物质世界是整体范围，其中只有进入实践活动的那部分才转化为现实客体，此说过宽。","C":"客体不依赖人的意识，说它是意识的创造物属于主观唯心主义。","D":"实践活动所指向的对象，正是实践客体的界定，体现了客体与实践活动的相关性。"},"memoryTip":"客体＝被实践指向的那部分世界；客观世界外延更大，把整体当客体是典型陷阱。"},"20136":{"solution":"实践中介是连接主体与客体的桥梁，既包括物质性工具和作为工具延伸的语言符号系统，也包括运用、操作这些工具的程序和方法，缺了“怎么用”就不完整。","optionAnalysis":{"A":"工具手段加操作程序和方法，正是实践中介的完整内容，与题干吻合。","B":"对事物存在发展有联系的各种要素总和，接近“条件”或“环境”的表述，不是中介的界定。","C":"构成事物一切要素的总和描述的是系统或事物本身，与中介概念不符。","D":"“受命于主观、见之于客观”描述的是实践的直接现实性特点，不是中介。"},"memoryTip":"中介＝器物加用法：既要工具手段，也要操作程序，两条腿齐备才叫中介。"},"20137":{"solution":"价值关系回答客体能否满足主体需要，即客体对主体的意义，表现为有用性、效益性。它不同于认识关系，讲主体对客体的能动反映的是认识关系。","optionAnalysis":{"A":"价值关系是客体属性对主体的客观意义，不是主体单方面的物质欲望和要求。","B":"主体对客体的能动反映属于认识关系，回答的是对象“是什么”，不是“有什么用”。","C":"改造和变革客体是实践关系的内容，强调实际作用与改变，不是价值评价。","D":"客体满足主体需要的属性即有用性和效益性，正是价值关系的实质，与题干吻合。"},"memoryTip":"三种关系一句话分清：实践管改造，认识管反映，价值管有用。见“有用性”就选价值。"},"20138":{"solution":"恩格斯这句话强调社会的技术需要给科学提出课题、提供动力，推动科学不断向前，落点是实践的需要推动认识发展，即实践是认识发展的动力。","optionAnalysis":{"A":"认识的来源讲认识从实践中产生，题干强调的不是科学从哪里来，而是什么力量把它推向前进。","B":"技术推动科学只是字面转述，未揭示哲学关系，且把实践需要窄化为技术本身。","C":"社会需要提出新课题、提供新手段，推动科学不断前进，正是实践作为认识发展动力的表现。","D":"把科学进步当作实践的目的，颠倒了目的与手段，实践才是认识的目的和归宿。"},"memoryTip":"“需要推动前进”是动力；问“从哪里来”才是来源，问“用来干什么”是目的，三问答法别混。"},"20139":{"solution":"马克思这句话把思维是否具有真理性的判定权交给实践，强调在实践结果中验证思维的现实性和力量，即实践是检验认识真理性的唯一标准。","optionAnalysis":{"A":"来源和动力回答认识从何产生、为何发展，题干问的是真伪如何判定，指向检验标准。","B":"实践之外没有别的判定标准，在实践中证明思维的现实性，正是实践作为唯一检验标准的表述。","C":"实践检验本身是有目的、有理论参与的活动，说它不需要理论指导是错误的。","D":"认识活动不能替代实践的直接现实性，二者作用不同，不能等量齐观。"},"memoryTip":"题眼“是否具有真理性”就是检验标准；来源、动力、目的三种问法都用同一批干扰项。"},"20140":{"solution":"“把它创造出来”就是用实践把预想变为现实。理论认识具有普遍性却不具备直接现实性，只有实践能把观念的东西转化为客观存在，所以实践高于理论认识。","optionAnalysis":{"A":"认识可以超前于实践，科学预见就是例证，说认识总是滞后于实践是片面的。","B":"实践是认识的基础和先导，认识对实践有反作用，但不能说二者互为先导。","C":"实践兼具普遍性品格和直接现实性品格，能变观念为现实，正是“创造出来”的哲学含义。","D":"实践与认识是辩证统一而非合二为一，合一论抹掉了二者的区别。"},"memoryTip":"实践高在“直接现实性”：能把想法变成现实，理论再普遍也差这一步。"},"20141":{"solution":"主体与客体之间同时存在实践关系、认识关系、价值关系和审美关系，其中实践关系是基础，其余关系都在实践关系上派生，因此最根本的关系是实践关系。","optionAnalysis":{"A":"认识关系是主体在观念上把握客体，由实践关系派生，不居根本地位。","B":"价值关系是客体满足主体需要的关系，同样以实践的改造为前提。","C":"主体通过实践改造客体，其他关系都由此产生，实践关系是主客体最根本的关系。","D":"审美关系是主体对客体的情感体验，属于较高层次的派生关系。"},"memoryTip":"一基三派：实践关系是地基，认识、价值、审美三座楼都盖在它上面。"},"20142":{"solution":"感性认识以感觉、知觉、表象反映事物的外部现象，理性认识以概念、判断、推理把握事物的本质和规律，二者的根本区别在于反映的深度和层次不同。","optionAnalysis":{"A":"感性认识可能被假象迷惑，理性认识也可能出错，用可靠与否区分二者不成立。","B":"理性认识同样来源于实践，书本知识归根到底是前人实践的结晶。","C":"感性认识停留在现象层面，理性认识深入到本质和内部联系，这是二者的根本区别。","D":"直接经验与间接经验的区分说的是知识获得途径，不能等同于感性认识与理性认识。"},"memoryTip":"感性与理性只有一条分水岭：现象对本质；来源都是实践，可靠与否不是判别标准。"},"20143":{"solution":"感觉反映个别属性，知觉把多种感觉综合成关于事物整体的形象，表象是感知形象在记忆中的再现。题干把眼耳鼻舌身所得属性在意识中联系起来形成整体形象，正是知觉。","optionAnalysis":{"A":"感觉只反映事物的个别属性，如颜色、形状、味道中的某一项，尚未构成整体形象。","B":"把多种感觉综合起来形成关于对象的完整形象，正是知觉的特征，与题干吻合。","C":"表象是感知过的事物在头脑中重现的形象，题干描述的是当场感知，不是事后回忆。","D":"分析是把对象分解为部分的思维操作，属于理性认识的方法，不是感性反映形式。"},"memoryTip":"感觉抓一点，知觉抓整体，表象靠回忆：三者按“个别—整体—重现”排队，别错位。"},"20144":{"solution":"唯理论片面夸大理性认识的可靠性、否认感性经验，经验论片面夸大感性经验、否认理性思维。两派各有片面的真理，又都把感性或理性之一绝对化，正确评价只能是各有片面的真理性。","optionAnalysis":{"A":"唯理论否认感性经验的作用，同样带片面性，不能全盘肯定。","B":"经验论否认理性思维把握本质的能力，同样片面，不能判为完全正确。","C":"两派各抓住认识过程中的一个环节并加以夸大，都有合理成分也有片面性，评价中肯。","D":"两派并非一无是处，各自揭示了感性或理性的重要作用，全盘否定不符合实际。"},"memoryTip":"唯理论重理性、经验论重经验，两家都“抓一头”：答案固定为各有片面的真理。"},"20145":{"solution":"真理与谬误的对立只有在确定范围内才具有绝对意义，超出这个范围、条件改变后二者可以相互转化。这一表述既承认对立，又承认转化的条件性，属于唯物辩证法的观点。","optionAnalysis":{"A":"形而上学把真理与谬误的对立绝对化，否认任何条件下可以转化，与本句正相反。","B":"承认对立有确定界限、又承认界限之外可转化，正是唯物辩证法关于真理与谬误关系的观点。","C":"诡辩论抹杀二者的原则界限，宣称怎么都行，而本句仍肯定有限范围内的对立有意义。","D":"相对主义只讲转化不讲界限，本句恰恰强调界限，因此不属于相对主义。"},"memoryTip":"“有限范围内”五个字是关键：有界限又能转化是辩证法，无界限才是诡辩和相对主义。"},"20146":{"solution":"真理与谬误相比较而存在、相斗争而发展，二者的对立在确定范围内是绝对的，但超出条件范围又会相互转化。所以相互关系是在一定条件下可以互相转化。","optionAnalysis":{"A":"二者只在确定范围内绝对对立，说“任何情况下”都绝对对立，就把对立绝对化了。","B":"否认转化可能，与真理超出适用范围就变成谬误这一事实不符。","C":"条件具备时真理会转化为谬误，谬误也可能转化为真理，这正是二者的辩证关系。","D":"真理与谬误存在原则区别，抹掉这条界限就是把真假混为一谈，滑向相对主义。"},"memoryTip":"真理跨出适用范围即变谬误：对立有前提，转化有条件，两句话一起记。"},"20147":{"solution":"把真理说成“人造的供人使用的工具”，等于用人的需要和效用取代客观标准，否认真理的客观内容，属于实用主义真理观，实质是主观唯心主义。","optionAnalysis":{"A":"以人的需要、效用裁定真伪，把真理归结为主观制造，正是主观唯心主义真理观。","B":"客观唯心主义把真理归于某种客观精神，而此说把真理归于人的制造和使用，落点在个人。","C":"辩证唯物主义坚持真理是主观形式与客观内容的统一，与工具论正相反。","D":"机械唯物主义在真理观上仍承认客观内容，不会把真理说成可以任意制造的工具。"},"memoryTip":"“人造”加“有用”就是实用主义，归主观唯心；客观唯心讲的是“天理”“绝对精神”，别混。"},"20148":{"solution":"真理是主观认识与客观对象相符合，但并非一切对客观事物的反映都是真理：错误的认识也是对客观事物的反映，只是歪曲的反映。该命题把一般认识等同于真理。","optionAnalysis":{"A":"反映有正确与歪曲之分，把一切反映都当真理，正是混淆真理性认识与一般认识，与题干吻合。","B":"辩证唯物主义要求主观与客观相符合，不认为任何反映都是真理，此命题不属于其真理观。","C":"旧唯物主义虽坚持反映论，但承认认识有对有错，不会把一切反映都等同于真理。","D":"题干的问题不在真理客观性与规律客观性的混淆，而在把认识与真理画等号。"},"memoryTip":"反映不等于真理：反映可能是歪曲的，真理要求相符合。这是一般认识与真理的分界。"},"20149":{"solution":"“听其言必责其用，观其行必求其功”主张对言论要看实际效用，对行为要检验实际成效，落点是以实践结果判断认识是否正确，即强调实践对认识的检验作用。","optionAnalysis":{"A":"题干不是要认识去指导行动，而是用行动和功效去核对言论，方向是检验而非指导。","B":"以“用”“功”衡量言与行，就是用实践效果验证认识，正是实践对认识的检验作用。","C":"该说法要求言行接受实效检验，恰恰反对认识脱离实践。","D":"它主张用实效检验言行，并未否定认识对实践的指导作用，说实践可以脱离认识恰与题干取向相反。"},"memoryTip":"“责其用、求其功”就是看效果：凡讲功效验言、以行验知的，都归“实践检验认识”。"},"20150":{"solution":"承认知识的相对性，就是承认任何真理都是具体的、历史的、有待发展，从而避免把已有认识凝固化、绝对化，因此可以防止认识的僵化。","optionAnalysis":{"A":"相对性若被绝对化才会滑向诡辩论，承认相对性本身并不必然导致诡辩。","B":"相对性不等于怀疑一切，承认认识的局限恰恰是为了推进认识，不会必然归结为怀疑主义。","C":"不可知论否认世界的可知性，而承认相对性仍肯定认识可以不断深化。","D":"承认知识有条件、有待深化，就能防止思想僵化，避免把阶段性成果当成终极真理。"},"memoryTip":"相对性是一把防锈刀，用来防僵化；把它推到绝对相对，才变成诡辩与不可知论。"},"20151":{"solution":"题眼是“智力如何发展”与“学会改造自然界”两处。改造自然就是实践，恩格斯把智力发展的根据落在这一过程上，说明推动认识前进的动力来自实践，而不是自然界本身。","optionAnalysis":{"A":"自然界是认识的客体和对象，本身不会自动推动认识；离开改造自然的实践，自然界无法充当认识发展的动力。","B":"人通过改造自然界的实践不断提出新课题、提供新工具、锻炼思维能力，正是实践推动认识发展，与题干完全吻合。","C":"认识具有能动性本身不假，但引文的重心在“如何学会改造”，即实践过程，不是泛泛谈论能动性。","D":"“能认识自然”只说明认识的可能性，没有回答智力凭什么“发展”，落点过于浅表。"},"memoryTip":"抓“改造自然界”四字：改造即实践，智力随实践长，动力归实践而非自然界。"},"20152":{"solution":"列宁把两条认识路线对举：一条由客观事物到感觉、思想，一条由思想、感觉到客观事物。前者坚持物质在先，后者坚持意识在先，正是唯物主义认识论与唯心主义认识论的分野。","optionAnalysis":{"A":"“从物到感觉和思想”坚持物质第一性，“从思想和感觉到物”坚持意识第一性，二者恰好对应唯物主义认识论与唯心主义认识论的对立。","B":"经验论与唯理论争的是知识来自感性还是理性，属于同一阵营内部的派别分歧，与两条认识路线不是一回事。","C":"反映论与先验论的对立虽同唯物、唯心相关，但列宁这两句话划分的是认识从何处出发的路线，标准表述为唯物主义与唯心主义认识论的对立。","D":"可知论与不可知论争的是世界能否被认识，列宁的命题讲的是认识的出发点，不是认识的可能性问题。"},"memoryTip":"看箭头起点：“物→感觉”是唯物，“感觉→物”是唯心，起点决定阵营。"},"20153":{"solution":"诗句用“纸上”与“躬行”对照，说的是书本上得来的知识终究浅薄，亲自去做才能真知。这指向实践是认识的来源，真切的知识根植于亲身实践。","optionAnalysis":{"A":"实践确实推动认识发展，但诗句对比的是“纸上”与“躬行”两条获知途径，落点在知识从何而来，而非认识如何深化。","B":"检验真理性要回答认识对不对，诗句讲的是“终觉浅”，即书本知识不真切，强调来源不足而非真假未验。","C":"“躬行”就是亲身实践，只有亲身去做才能获得真切知识，与“实践是认识的来源”完全对应。","D":"诗句只说书本知识浅，并未否认间接经验的价值，这一说法把事情绝对化了。"},"memoryTip":"“躬行”对“纸上”：一个是源，一个是流，书本知识是转手得来，亲身实践才是源头。"},"20154":{"solution":"列宁这句话把理论置于行动之前，强调没有理论就不会有自觉的革命行动，讲的是理论对实践的能动反作用，即革命理论对革命实践的指导。","optionAnalysis":{"A":"理论源于实践并服务于实践，说理论比行动更重要，颠倒了实践的基础地位。","B":"革命运动根源于社会矛盾和物质实践，把运动说成理论的派生物，是典型的唯心史观。","C":"理论一经掌握群众就能转化为物质力量，为革命行动指明方向和道路，正是指导作用的体现，与题干吻合。","D":"革命运动成败最终由实践条件和客观规律决定，理论只能起指导作用，不能“最终决定”。"},"memoryTip":"记“理论开路、实践走路”：理论管方向，实践定成败，反作用不等于决定作用。"},"20155":{"solution":"“有准备的头脑”不是眼睛更亮，而是头脑中已有知识储备和理论框架。巴斯德强调的是理性因素在观察中的指导作用，有理论准备才抓得住偶然机遇。","optionAnalysis":{"A":"发挥主观能动性是认识事物的普遍前提，但题干用“有准备”特指头脑中的知识与理论准备，此项说得太泛。","B":"感性经验人人都在积累，机遇偏爱的是有理论武装的观察者，落点不在感性经验多少。","C":"善于观察、善于思考只是表面描述，没有点出“准备”的实质是理性认识对感性材料的指导。","D":"已有理论框架能使人从偶然现象中看出门道，说明认识活动需要理性指导，与“有准备的头脑”吻合。"},"memoryTip":"“有准备的头脑”＝带着理论去看，机遇只给有理性准备的人，别选“多观察”。"},"20156":{"solution":"马克思先说搬运夫与哲学家的原始差别比家犬与猎犬还小，再说鸿沟由分工掘成。分工属于社会实践的具体形式，可见才智差异主要来自后天实践。","optionAnalysis":{"A":"原文说“差别小得多”，是程度判断，并未断言毫无先天差别，绝对化表述失真。","B":"主观努力固然起作用，但引文把根源归于“分工”这一社会实践活动，不是个人努力程度。","C":"分工是社会实践的具体形式，社会分工不同造成才智分化，正说明聪明才智主要来源于后天实践。","D":"社会政治地位与分工不能画等号，引文讲的是分工造成的实践差异，不是政治地位决定才智。"},"memoryTip":"家犬猎犬差别大、搬运夫与哲学家差别小——鸿沟是“分工”掘的，分工即实践。"},"20157":{"solution":"真理是主观认识与客观对象相符合，谬误是歪曲的反映。二者界限只能看认识是否如实反映客观事物的本质和规律，其他标准都站不住。","optionAnalysis":{"A":"符合利益和愿望是主观效用标准，对人有用的未必是真，这是实用主义真理观。","B":"以是否符合某种学说作标准，是把真理的裁判权交给权威，混淆了真理与对理论的信仰。","C":"真理的本性是主观与客观相符合，如实反映事物本质和规律者为真，歪曲者即谬误，界限正在此处。","D":"多数人接受与否属于主观认定，历史上多数人长期相信错误认识的情形并不少见。"},"memoryTip":"真理看“符不符客观”，不看“有没有用、谁说的、多少人信”。"},"20158":{"solution":"真理的绝对性包含两层含义：任何真理都有不依赖于主体的客观内容，以及人类认识能够把握无限发展的世界。选项中能与之一致的只有客观性。","optionAnalysis":{"A":"具体性讲的是真理有条件、有范围，属于真理的辩证性质，不是绝对性的含义。","B":"真理的绝对性首先指其内容客观、不因人而异，承认客观真理也就承认了绝对真理，此项吻合。","C":"终极性意味着认识可以到此为止，这是形而上学的绝对主义，教材明确否定。","D":"全面性是真理具体性提出的整体要求，讲认识的完整程度，与绝对性不在同一层含义。"},"memoryTip":"绝对性两含义：内容客观不动摇＋认识能到底；凡带“终极、穷尽”的选项都是陷阱。"},"20159":{"solution":"相对主义把真理的相对性一面无限放大，否认其中任何客观的、绝对的内容，最终走向“怎么都行”。所以它的错误在于夸大相对性、否认绝对性。","optionAnalysis":{"A":"相对主义正是只承认真理有条件、可变，否认其中包含的客观内容，此项准确指出其病灶。","B":"夸大绝对性、否认相对性的是绝对主义，与相对主义方向正好相反。","C":"只讲客观性而否认相对性，同样属于绝对主义的表现，不是相对主义的错误。","D":"一定条件下对同一对象的真理性认识只有一个，这是真理的一元性，是正确观点而非错误。"},"memoryTip":"相对主义＝只认“相对”，绝对主义＝只认“绝对”，各砍一刀就记牢。"},"20160":{"solution":"理论创新源于实践又反作用于实践，它在社会变革中先行一步，为制度变革和事业发展提供思想准备，因此被称作社会发展和变革的先导。","optionAnalysis":{"A":"社会发展趋势由社会基本矛盾运动决定，理论创新只能反映和引导，不能“决定”趋势。","B":"变革力度取决于实践条件和人民群众的力量，理论创新在其中不起决定作用。","C":"理论创新往往先于社会变革发生，为变革扫清思想障碍，教材表述即“先导”，与题干一致。","D":"国家兴旺发达的最终源泉在实践和生产力发展，“最终”二字使该项失当。"},"memoryTip":"理论创新只记“先导”二字：先想一步、引导一步，却决定不了趋势和成败。"},"20161":{"solution":"马克思主义认识论以实践为首要的和基本的观点，正是把实践引入认识论，才科学说明了认识的来源、动力、标准和目的。其余三项属于辩证法总特征范畴。","optionAnalysis":{"A":"实践观点是马克思主义认识论首要的和基本的观点，认识的来源、动力、检验标准和目的都要由实践来说明。","B":"联系的观点是唯物辩证法的总特征之一，属于辩证法领域，不是认识论的首要观点。","C":"发展的观点同样属于唯物辩证法的总特征，用来揭示世界的运动变化。","D":"矛盾观点是唯物辩证法的实质和核心，讲事物发展的动力，不能替换认识论的首要观点。"},"memoryTip":"两个“首要”别混：认识论首要是实践，辩证法核心是矛盾。"},"20162":{"solution":"实践有基本形式之分，物质生产是最基本的实践，因为它解决人与自然的关系，是社会存在和发展的基础。四项中只有农民播种小麦属于物质生产。","optionAnalysis":{"A":"农民播种小麦是改造自然、获取物质生活资料的生产活动，属于物质生产实践，因而是最基本的实践形式。","B":"医生做手术是处理人与人社会关系、服务社会生活的活动，不属于物质生产实践。","C":"法官审理案件属于处理社会关系的实践，性质与地位都低于物质生产实践。","D":"科学实验是探索性、试验性的实践，虽重要但只是基本形式之一，不是最基本的。"},"memoryTip":"见“种地、做工、采矿”就选物质生产；看病、办案归社会关系，实验归科学实验。"},"20163":{"solution":"“存在就是被感知”把个人感知当作存在的前提，用主观感觉吞掉客观世界，是典型的主观唯心主义命题，出自贝克莱。","optionAnalysis":{"A":"客观唯心主义把某种客观精神如理、绝对观念、上帝当作世界本原，与个体感觉不是一回事。","B":"把存在归结为个人的感知，等于说未被感知便不存在，以主观感觉为本原，属于主观唯心主义。","C":"庸俗唯物主义把意识看作大脑分泌的物质，混淆物质与意识，与题干命题方向相反。","D":"机械唯物主义坚持物质第一性，只是解释方法上机械，不会把存在归为感知。"},"memoryTip":"命题里出现“我感知、我思、我心”即主观唯心；出现“理、绝对精神、天”才是客观唯心。"},"20164":{"solution":"旧唯物主义和唯心主义都没能驳倒不可知论，要害在于不懂实践。马克思主义把科学的实践观引入认识论，用实践的成功证明思维与存在的同一性。","optionAnalysis":{"A":"感觉论者可以一面讲感觉、一面怀疑感觉之外有物，仅凭感觉无法回答世界是否可知。","B":"本质与现象统一的观点旧唯物主义早有，但没有实践作桥梁，仍说不清人如何把握本质。","C":"感性认识与理性认识的统一属于认识过程内部关系，不能解决主观能否符合客观这一根本问题。","D":"实践是联结主观与客观的桥梁，实践证明认识同对象相符，才真正驳倒了不可知论。"},"memoryTip":"驳不可知论只有一把钥匙——实践；其余选项都还在认识圈子里打转。"},"20165":{"solution":"真理一元性讲的是对同一对象的真理性认识只有一个，不因认识主体不同而改变，所以一元性落在内容上，表达形式则可以多样。","optionAnalysis":{"A":"认识上的一元性说法不成立，认识恰恰因人而异、多种多样，一元性指的是真理内容。","B":"形式上真理可以用不同语言、不同理论体系表述，形式恰恰是多样的。","C":"表现上的多元正是真理形式多样的体现，不能用来解释一元性。","D":"同一对象只有一个符合客观的正确认识，这一唯一性落在内容上，故真理一元性是内容上的一元性。"},"memoryTip":"形式可以百花齐放，内容只能一个答案——一元性管内容不管形式。"},"20166":{"solution":"把客体仅仅看成人直观认识的对象，就是离开实践、把认识当成被动照镜子，这正是旧唯物主义直观反映论的特征。辩证唯物主义则强调客体是实践改造的对象。","optionAnalysis":{"A":"主观唯心主义把客体看作感觉的复合，比“直观对象”走得更远，方向并不相同。","B":"客观唯心主义把客体视为客观精神的外化，根本不承认独立自在的物质客体。","C":"辩证唯物主义既承认对象的客观性，又强调对象在实践中被改造和被认识，不会只讲直观。","D":"旧唯物主义离开实践理解认识，把人看作消极直观的接受者，只把客体当直观对象，此项正确。"},"memoryTip":"“仅仅直观”是旧唯物主义的名片：直观、消极、不懂实践，三词连记。"},"20167":{"solution":"“认识是主体对客体的反映”是反映论的基本命题，一切唯物主义都坚持反映论，区别只在于旧唯物主义直观被动、辩证唯物主义以实践为基础。","optionAnalysis":{"A":"唯物主义的共同前提是物质第一性、意识是物质的反映，因此一切唯物主义都承认识是对客体的反映。","B":"唯心主义主张认识是精神自身的产物或对理念的回忆，恰恰否认反映论。","C":"形而上学唯物主义的错误在直观、消极、不懂实践和辩证法，“反映”这一基本立场并不错。","D":"辩证唯物主义把反映论推进为能动反映，但反映论本身并非它独有，旧唯物主义同样承认。"},"memoryTip":"“反映论”是唯物主义全家共有，辩证唯物主义只是把它变得能动。"},"20168":{"solution":"实践的基本形式包括物质生产、处理社会关系和科学实验，其中物质生产解决人与自然的关系，是其他一切活动的基础，因而最基本。","optionAnalysis":{"A":"处理社会关系的实践以物质生产为基础并受其制约，地位从属于物质生产。","B":"科学实验是探索规律的重要形式，但它是从物质生产中分化出来的，不能充当最基本形式。","C":"物质生产提供人类生存所需的物质资料，决定社会面貌，是当之无愧的最基本实践形式。","D":"教育实践属于处理社会关系、传递经验的活动，不在实践的基本形式之列。"},"memoryTip":"三种基本形式排座次：生产第一，社会关系第二，科学实验第三。"},"20169":{"solution":"辩证唯物主义认为认识不是照镜子，也不是内心自省，而是主体在实践中对客体的能动反映，是摹写与创造的统一。","optionAnalysis":{"A":"把认识说成主体对认识要素的建构，强调主体构造对象，容易滑向唯心主义建构论。","B":"以实践为基础，既坚持反映论又突出主体能动性，正是辩证唯物主义对认识本质的规定。","C":"内省说认为反省内心即可获得真知，属于唯心主义直觉主义，与反映论相反。","D":"信息选择只描述认识过程中的一个环节，把局部当整体，无法概括认识的本质。"},"memoryTip":"认识的本质记三个词：实践是基础，能动是特征，反映是实质，缺一不可。"},"20170":{"solution":"检验认识对错的标准既不能来自主观，也不能来自权威，只能是能把主观与客观联结起来的社会实践，实践结果证明认识是否符合实际。","optionAnalysis":{"A":"以伟人之言为据是权威标准，权威的话本身也需要实践检验，不能充当真理尺度。","B":"以吾人之心为据是主观标准，各人心中标准不同，无法判定客观是非。","C":"众人意见属于多数人的主观认定，多数人赞同并不等于符合客观。","D":"实践具有直接现实性，能把认识变为现实并加以对照，是判断观点对错的唯一标准。"},"memoryTip":"四把尺子只留一把：伟人、我心、众人都属主观，社会实践才落地。"},"20171":{"solution":"直接经验是亲身实践所得，间接经验是从他人和书本得来的知识，后者归根到底源于前人的直接经验，所以二者是认识的“源”与“流”的关系。","optionAnalysis":{"A":"感性认识与理性认识按反映深度划分，直接经验与间接经验按获得途径划分，两组概念不能对应。","B":"第一性与第二性讲物质与意识的关系，直接经验和间接经验都是认识，同处第二性一侧。","C":"一切真知都发源于直接经验，间接经验只是他人直接经验的传递，故为源与流的关系，此项正确。","D":"理论与实践是另一对范畴，直接经验不等于理论，间接经验也不等于实践。"},"memoryTip":"亲身得来是“源”，书本转手是“流”；源流不是第一性第二性。"},"20172":{"solution":"尊重知识、尊重人才，实质是重视知识分子的作用，也就是重视科学理论对实践的指导。理论来自实践，一旦形成又能反过来指导实践。","optionAnalysis":{"A":"理性认识依赖感性认识讲的是认识的来源顺序，题干强调的却是理论对现代化建设实践的反作用。","B":"知识和人才的价值在于用科学理论指导实践、提高实践成效，正体现理论对实践的指导作用。","C":"理论来源于实践本身不错，但那是理论的产生问题，说明不了为什么要“尊重知识、尊重人才”。","D":"认识的反复性、无限性、上升性讲认识过程的特点，与尊重知识人才没有直接对应。"},"memoryTip":"“尊重知识、尊重人才”问的是理论的反作用，别答成理论从哪里来。"},"20173":{"solution":"感性认识由感官直接接触外物产生，反映现象和外部联系，特点是直接性、形象性，形式为感觉、知觉、表象。它是认识过程的起点，有待上升为理性认识。","optionAnalysis":{"A":"反映事物本质和内部联系的是理性认识，题干问的是感性认识，此项偷换了对象。","B":"前半句对，反映现象；但加上“不可靠的反映”就错了，感性认识是认识的起点，本身具有可靠性。","C":"通过感觉器官直接获得、形象具体，正是感性认识的规定，与题干相符。","D":"借助思维对事物作间接、抽象的把握，这是理性认识的特征，与感性认识正好相反。"},"memoryTip":"感性三形式“感、知、表”，特点是直接加形象；抽象的统统归理性。"},"20174":{"solution":"理性认识借助概念、判断、推理把握事物的本质和内部联系，因而具有抽象性和间接性，这是它区别于感性认识的根本特点。","optionAnalysis":{"A":"对感性材料进行加工是形成理性认识的过程，不是理性认识本身的特点。","B":"感觉、知觉、表象是感性认识的三种形式，不是理性认识的特点，此处张冠李戴。","C":"理性认识离开具体形象，通过抽象思维间接把握对象，特点正是抽象性、间接性。","D":"形象性、直接性恰恰是感性认识的特点，拿来描述理性认识正好说反了。"},"memoryTip":"感性直接形象，理性抽象间接，两组特点对号入座不要交换。"},"20175":{"solution":"概念、判断、推理是思维的基本形式，三者都在思维层面运作，属于理性认识；感性认识的形式是感觉、知觉、表象，两组切勿混淆。","optionAnalysis":{"A":"直接经验讲知识获得的途径，并不用概念、判断、推理来划分形式。","B":"间接经验同样按途径划分，概念判断推理是思维形式，不是经验的分类。","C":"感性认识的形式只有感觉、知觉、表象三种，概念、判断、推理不属于其中。","D":"概念揭示本质，判断展开关系，推理推出新知，三者构成理性认识的三种形式。"},"memoryTip":"口诀对照记：“感觉、知觉、表象”进感官，“概念、判断、推理”动脑子。"},"20176":{"solution":"承认理性认识依赖感性认识，坚持了唯物论；承认感性认识有待上升为理性认识，则体现了认识过程的辩证运动。前者是认识论的唯物论，后者是认识论的辩证法。","optionAnalysis":{"A":"认识论的唯物论对应的是理性认识依赖于感性认识，与本项方向正好相反。","B":"感性认识必须发展到理性认识，讲的是认识由浅入深的辩证运动，属于认识论的辩证法。","C":"认识论的形而上学把感性与理性割裂开来，正是这一命题所要反对的做法。","D":"唯心论否认认识来源于客观世界，与题干强调的上升过程无关。"},"memoryTip":"“依赖感性”是唯物论，“有待上升”是辩证法，一问一答配成对。"},"20177":{"solution":"感性认识和理性认识都在实践中产生、在实践中联结：实践提供感性材料，也提供思维加工的现实需要和检验尺度，所以统一的基础是社会实践。","optionAnalysis":{"A":"实践既产生感性材料又推动思维加工，是二者相互过渡、相互渗透的现实基础。","B":"感性材料只是认识的原料，本身不能把感性和理性联结起来。","C":"理性抽象是思维加工的方法和结果，属于理性认识内部环节，不是统一的基础。","D":"认识能力是主体的条件，且受实践制约，不能充当二者统一的基础。"},"memoryTip":"凡问“基础、源泉、标准”，先想实践；“感性材料”只是原料不是基础。"},"20178":{"solution":"两者的根本区别在反映的层次：感性认识反映现象和外部联系，理性认识反映本质和内部联系，这是划分二者的根本标志。","optionAnalysis":{"A":"感性认识可能带表面性，但并非必然错误；理性认识也可能出错，不能一概而论。","B":"现象与本质之分正是二者的根本区别所在，与题干要求一致。","C":"感性认识和理性认识归根到底都来源于实践，理性认识并非从抽象思维中凭空产生。","D":"把来源分为日常生活和科学实验不成立，二者的来源都是社会实践。"},"memoryTip":"现象归感性，本质归理性；不要拿“对错”“来源”去区分这两者。"},"20179":{"solution":"只信自己经验、轻视理论指导，是把感性经验绝对化，停留于局部经验而拒绝理论概括，这与哲学上夸大感性认识的经验论相通。","optionAnalysis":{"A":"先验论认为认识先于经验、与生俱来，题干中的人恰恰只信经验，方向相反。","B":"唯理论夸大理性、轻视经验，与题干中轻视理论的做法正好对立。","C":"客观唯心主义把客观精神当本原，与凭经验办事没有对应关系。","D":"经验论夸大感性经验、贬低理性思维，题干所述正是它在实际工作中的表现。"},"memoryTip":"“只信经验”配经验论，“只信书本”配唯理论，两边各打五十大板。"},"20180":{"solution":"唯理论夸大理性认识的作用，轻视感性经验和具体实际，落到工作中就是从本本出发、照搬理论，也就是教条主义。","optionAnalysis":{"A":"经验主义是经验论在实际工作中的表现，与唯理论的指向正好相反。","B":"唯理论把理论绝对化，脱离实际条件套用本本，正是教条主义的思想根源。","C":"相对主义是真理观上夸大相对性、否认绝对性，与唯理论无直接对应。","D":"诡辩论是辩证法的歪曲运用，指概念灵活性的滥用，不属于唯理论的后果。"},"memoryTip":"一对反义词记牢：经验论生经验主义，唯理论生教条主义。"},"20181":{"solution":"认识过程有两次飞跃：从实践到认识，主要是认识世界；从认识到实践，主要是改造世界。二者的区别正在于前者重在认识、后者重在改造。","optionAnalysis":{"A":"现象与本质都属于第一次飞跃内部由感性到理性的深化，不是两次飞跃的分界。","B":"第一次飞跃的成果是理性认识而非感性认识，感性认识只是它的起点。","C":"第一次飞跃以形成理性认识、认识世界为主，第二次飞跃以指导实践、改造世界为主，区别正在此。","D":"目的说反了：第一次飞跃的目的是认识世界，第二次飞跃才是改造世界并检验发展理论。"},"memoryTip":"第一次“想明白”，第二次“干出来”；先认识后改造，顺序不能倒。"},"20182":{"solution":"复杂事物受本质暴露程度和主体条件限制，正确认识不可能一次完成，需要经过实践、认识、再实践、再认识的多次反复才逐步逼近。","optionAnalysis":{"A":"从感性到理性只是第一次飞跃，走完这一步还谈不上形成正确认识。","B":"回到实践一次也不够，客观过程尚未充分展开时认识仍会反复。","C":"一个完整过程只完成一次循环，对本质尚未充分暴露的复杂事物往往仍不充分。","D":"多次反复、不断深化才符合认识发展的规律，与复杂事物的特点吻合。"},"memoryTip":"越复杂越要“来回跑”：实践—认识—再实践，反复多次才靠得住。"},"20183":{"solution":"恩格斯讲思维的至上性，是指人类认识按其本性能把握无限发展的世界；非至上性，是指每一代人、每一个人的认识都受历史条件限制。这种既肯定又限定的说法正是辩证唯物主义。","optionAnalysis":{"A":"诡辩论靠偷换概念、抹杀确定界限，与这种有条件的统一不是一回事。","B":"折衷主义把对立观点无原则拼凑，题干讲的却是同一认识能力的两个辩证方面。","C":"形而上学要么只讲至上、要么只讲非至上，容纳不了二者的统一。","D":"既承认人类认识能够把握世界，又承认具体认识受历史条件限制，正是辩证唯物主义的思维观。"},"memoryTip":"人类整体“至上”，具体个人“非至上”；一个能力两个侧面，不是两个真理。"},"20184":{"solution":"群众路线讲从群众中来、到群众中去，先把分散意见集中起来，再回到群众中坚持下去，这与实践、认识、再实践的认识路线同构，二者完全一致。","optionAnalysis":{"A":"群众路线的“集中—坚持”正是认识两次飞跃的运用，二者在内容和过程上完全一致。","B":"群众路线以马克思主义认识论为哲学基础，说没有关系显然不成立。","C":"群众路线是认识论的运用，二者是理论与运用的关系，说成根本对立完全错误。","D":"关系被颠倒了：马克思主义认识论是群众路线的理论基础，群众路线是它的运用。"},"memoryTip":"“从群众中来”对应从实践到认识，“到群众中去”对应从认识到实践。"},"20185":{"solution":"真理是标志主观同客观相符合的哲学范畴，即人们对客观事物及其规律的正确反映。判断真理靠是否符合客观，不靠人数多少或是否经过检验程序。","optionAnalysis":{"A":"真理的定义就是主体对客观事物及其规律的正确反映，与题干完全契合。","B":"多数人同意只是共识，共识可能是错误的，人数多少不决定真假。","C":"无人反对更不是真理标准，压制不同意见同样能制造出表面的一致。","D":"经过实践检验的认识未必是真理，错误认识同样会被实践检验并否定，该表述不准确。"},"memoryTip":"真理＝正确反映；不是“多数”，不是“无反对”，也不止是“被检验过”。"},"20186":{"solution":"真理的客观性有两层：内容来自客观世界，检验标准是客观的社会实践。真理的形式则是主观的，不能把形式也说成客观。","optionAnalysis":{"A":"把真理当人类经验的组织形式，是以主观经验取代客观内容，属于主观真理论。","B":"真理内容不依赖于主体，检验它的实践也是客观的，这正是客观性的两层含义。","C":"指导作用讲的是真理的功能，功能有效并不等于回答了客观性问题。","D":"真理以概念、判断等思维形式存在，形式是主观的，说形式客观恰恰说反了。"},"memoryTip":"真理“内容客观、形式主观”，两个半句要成对记，别只说一半。"},"20187":{"solution":"把真理归结为思想形式、经验的组织形式，等于用主观经验吞掉客观内容，取消了真理的客观性，是典型的主观真理论。","optionAnalysis":{"A":"唯物主义真理论坚持真理内容来自客观世界，与题干命题相反。","B":"该命题只看形式、只讲经验的组织，把真理变成主观构造物，正是主观真理论。","C":"客观真理论强调真理内容不依主体而转移，题干恰恰否认这一点。","D":"形而上学真理论指把真理绝对化、凝固化，与题干的主观化方向不同。"},"memoryTip":"见到“真理是组织形式、思想形式”就判主观真理论，形式论必滑向主观。"},"20188":{"solution":"真理与谬误同属认识，区别不在地位或效用，而在是否如实反映对象：正确反映对象的是真理，歪曲反映对象的是谬误。","optionAnalysis":{"A":"真理和谬误都既有绝对性一面又有相对性一面，用绝对、相对划线不成立。","B":"有用与有害是效用评价，实用主义用它代替真假标准，并不构成根本区别。","C":"谬误同样是主观对客观的反映，只是歪曲的反映，说它纯属主观就取消了它的客观根源。","D":"正确反映与歪曲反映的对立，正是真理与谬误的根本分界，此项表述准确。"},"memoryTip":"两者都是“反映”，差别只在“正”与“歪”一字，与有用无用无关。"},"20189":{"solution":"真理与谬误有原则界限，不能混淆；二者的统一表现在一定条件下相互转化：真理超出适用范围会变成谬误，谬误被纠正可以转化为真理。","optionAnalysis":{"A":"真理中并不包含谬误，二者界限分明，把真理说成含有谬误等于取消了界限。","B":"二者不是因果链条上的相互产生，而是认识性质上的对立与转化关系。","C":"条件变化使真理越界成谬误、谬误被纠正成真理，这正是二者统一性的内容。","D":"否认确定的界限会滑向相对主义，真理与谬误在一定范围内界限是确定的。"},"memoryTip":"统一＝有条件转化，不是“互相包含”，也不是“没有界限”。"},"20190":{"solution":"真理都是具体的，有特定对象、条件和范围。一旦超出适用条件，把它搬用到别的场合，真理就会转化为谬误，这正是转化的原因。","optionAnalysis":{"A":"客观性说明真理不因人而异，恰恰是真理可靠的基础，不构成转化的原因。","B":"真理的具体性决定它受条件制约，越出条件便走向反面，与题干因果关系吻合。","C":"真理中并不包含谬误，转化是条件变化引起的，不是内部含有谬误。","D":"抹杀二者界限是相对主义的错误说法，也不能说明真理为何会转化。"},"memoryTip":"真理“越界即错”，前提是它具体、有条件；别答成“真理含谬误”。"},"20191":{"solution":"承认真理客观，就是承认有不依赖于主体的正确内容，这样的真理具有不可推翻的一面，即真理的绝对性。客观性与绝对性在教材中是相通的。","optionAnalysis":{"A":"承认客观性恰恰确认真理的确定性，说成不确定性正好与客观性相反。","B":"相对性讲的是认识广度和深度的有限，不能由承认真理客观直接推出来。","C":"可变性指真理随条件发展而深化，也不是客观性的直接推论。","D":"客观真理即绝对真理，承认客观性必然承认真理的绝对性，此项正确。"},"memoryTip":"链式记忆：客观性推出绝对性，有条件、有限度推出相对性，两条线别接错。"},"20192":{"solution":"真理的相对性指人们在一定条件下对客观事物本质及其发展规律的正确认识在广度、深度上都是有限的，需要继续扩展和深化。","optionAnalysis":{"A":"任何真理都包含绝对真理的成分，说它不含绝对性就割裂了二者。","B":"有条件、有限度地正确反映对象，正是真理相对性的含义，与题干一致。","C":"包含谬误的认识整体上已不是真理，真理与谬误不能混为一谈。","D":"错误认识中可能含有正确成分，但它本身是谬误，不是真理的相对性。"},"memoryTip":"相对性＝“有条件、有限度、待深化”，不等于“有错、含谬误”。"},"20193":{"solution":"绝对性和相对性是同一真理的两重属性：任何真理都既有客观内容、不可推翻的一面，又有条件限制、有待发展的一面，并非两种真理。","optionAnalysis":{"A":"它们不是两种性质相同的真理，而是同一条真理的两个方面。","B":"也不是两种性质不同的真理，把属性说成两个真理就割裂了统一。","C":"同一客观真理同时具有绝对性和相对性，二者是它的两种属性，此项准确。","D":"说成不同真理的两个方面同样错误，绝对性和相对性的载体始终是同一个真理。"},"memoryTip":"“一个真理、两重属性”：不是两个真理，也不是两种性质。"},"20194":{"solution":"科学理论不能穷尽真理、只能在实践中不断开辟认识真理的道路，说的是任何真理都有待扩展和深化，这正是真理的相对性。","optionAnalysis":{"A":"客观性讲真理内容不依赖于主体，回答的是真假依据，与“不能穷尽”无关。","B":"绝对性讲真理包含不可推翻的客观内容，与“不断开辟道路”所体现的有限性相反。","C":"认识的广度深度有限、需要不断发展，正是相对性的表现，与题干吻合。","D":"全面性是真理具体性提出的要求，不是对认识无限发展的说明。"},"memoryTip":"“不能穷尽、还要发展”是相对性；“推翻不了、内容客观”才是绝对性。"},"20195":{"solution":"实践高于理论认识，在于实践具有直接现实性：它能把观念变成现实，直接对照检验认识，而理论始终停留在观念领域。","optionAnalysis":{"A":"实践是客观物质活动，但并不“独立”于意识之外自足存在，表述不当。","B":"直接现实性是实践独有的品格，能把主观认识转化为客观结果，故高于理论。","C":"社会历史性是实践的特点，说明实践受历史条件制约，不是“高于”理论的根据。","D":"自觉能动性理论认识同样具备，不能成为实践高出一筹的理由。"},"memoryTip":"实践凭什么高？凭“直接现实性”——能变成现实，理论只能想。"},"20196":{"solution":"检验认识的真理性，检验的是主观认识同客观事物及其规律是否符合，此外没有别的对象。实践只是检验的途径和标准。","optionAnalysis":{"A":"清晰明白只是逻辑形式上的要求，说得清楚明白并不等于说得符合客观。","B":"真理是主观与客观相符合，检验就是看这种符合是否成立，此项正确。","C":"与既有理论一致只是逻辑检验，理论本身也要接受实践检验。","D":"以方针政策作标准是把真理标准交给权威，混淆了政治要求与真理性。"},"memoryTip":"检验的对象是“符不符客观”，不是清不清楚、合不合本本和文件。"},"20197":{"solution":"实践标准的不确定性来自实践本身的历史局限：一定历史阶段的实践不能完全证实或驳倒现有认识，需要以后的实践加以补充。","optionAnalysis":{"A":"任何时代的实践都受条件和水平限制，检验往往不够充分，这正是不确定性的原因。","B":"原则上没有不可检验的认识，暂时检验不了只是条件不具备，不能作为不确定性依据。","C":"有意识有目的是实践的自觉能动性，说明实践区别于本能活动，与标准的不确定性无关。","D":"不同人标准不同是主观主义说法，实践标准对所有人是同一的。"},"memoryTip":"确定性靠“最终能检验”，不确定性因“当下检验不全”，根源在历史局限。"},"20198":{"solution":"党的思想路线是实事求是：一切从实际出发是前提，理论联系实际是根本方法，在实践中检验和发展真理是途径，核心则是实事求是。","optionAnalysis":{"A":"一切从实际出发是思想路线的前提和基础，为实事求是提供客观依据。","B":"理论联系实际是根本方法和根本要求，属于实事求是的内在规定。","C":"实事求是统摄其他三个方面，是党的思想路线的核心，也是其精髓所在。","D":"在实践中检验和发展真理是坚持实事求是的途径和归宿，不是核心。"},"memoryTip":"四句排位：实事求是居中作核心，出发、联系、检验都围着它转。"},"20199":{"solution":"主观与客观、理论与实践的联结不能靠观念自身完成，只有社会实践才能把二者沟通起来，因而是统一的基础和途径。","optionAnalysis":{"A":"客观事物是认识的对象，本身不会主动出面把主观认识与理论统一起来。","B":"主观认识属于要被检验的一方，拿它作基础等于自己证明自己。","C":"科学理论来自实践并需实践检验，只能指导统一而不能充当统一的途径。","D":"实践具有直接现实性，能把主观见之于客观，是二者统一的现实基础和途径。"},"memoryTip":"凡是问“统一的基础和途径”，答案几乎都是社会实践。"},"20200":{"solution":"真理既是绝对的又是相对的，讲的是同一真理的两重属性及其相互联结，属于真理问题上的辩证法；真理的客观性才属于唯物论。","optionAnalysis":{"A":"唯物论对应的是真理的客观性，回答真理内容从哪里来的问题。","B":"把绝对与相对统一起来看，正是矛盾分析方法在真理观上的运用，属于辩证法。","C":"历史观讨论社会历史领域的根本问题，与真理属性不在同一层面。","D":"二元论主张两个平行本原，这里讲的是一条真理的两个方面，不是二元论。"},"memoryTip":"真理“客观性”归唯物论，“绝对又相对”归辩证法，两问两答别串门。"},"20201":{"solution":"题干的关键词是把实践置于认识论的基础地位。旧唯物主义坚持反映论却脱离实践，唯心主义把认识归于精神，只有辩证唯物主义把实践引入认识论，明确实践是认识的来源、动力、目的和检验标准。","optionAnalysis":{"A":"旧唯物主义虽主张意识反映物质，却把认识看成对客体的消极直观，不理解实践对认识的决定作用，故不能说一切唯物主义都持此观点。","B":"形而上学唯物主义正是离开实践、离开辩证法谈认识，把认识理解为照镜子式的直观反映，与题干判断相反。","C":"辩证唯物主义把实践观点作为首要的基本观点，认定认识来源于实践又服务于实践，与题干表述完全一致。","D":"彻底唯心主义把认识归结为精神自身的活动或天赋观念，根本不承认认识依赖于物质实践。"},"memoryTip":"凡把实践放在认识论首位，就锁定“辩证”二字；旧唯物主义缺的恰是实践这一环。"},"20202":{"solution":"题干引的是相对主义说法：是非没有确定界限，等于取消了判定真假的客观尺度。真理检验标准问题追问的是“用什么判定认识真假”，该观点否认存在这样的客观标准，故属否认真理客观标准的相对主义。","optionAnalysis":{"A":"该说法认定是非随人随时而变，没有统一尺度可循，正是取消检验真理的客观标准，与题干设问角度直接吻合。","B":"强调真理客观性意味着承认有独立于主观的确定标准，与该说法的是非两可恰好相反。","C":"否认真理客观性指否认认识内容与客体相符合，题干追问的是判定标准而非真理内容本身，属答非所问。","D":"该说法恰恰否认有客观标准，若认为它在强调客观标准，就与“此亦一是非”的语义完全相反。"},"memoryTip":"“此亦一是非”是相对主义的招牌句，见它即选“无客观标准”。"},"20203":{"solution":"袁隆平的话把书本、电脑与田间劳动对立起来，落点是“田里才能种出水稻”，强调知识最终来自实践。书本与电脑提供的是间接经验，其根源仍在他人实践，故题干指向实践是知识的基础和来源。","optionAnalysis":{"A":"书本知识与电脑技术都是间接经验，归根到底由前人和他人的实践得来；田间育种说明实践才是知识的源头，与题意吻合。","B":"题干强调的是实践产生认识，方向是实践到认识；该项讲认识反过来提高实践水平，虽成立却把因果链倒置。","C":"理论因是否如实反映客观对象而有正确与错误之分，错误理论会把实践引向失败，该表述本身错误。","D":"两次飞跃中第二次飞跃即认识到实践更为重要，因为认识的目的在于指导实践，该项判断与教材相反。"},"memoryTip":"“田里才种得出水稻”——间接经验追根到底还是实践给的，知识之源在实践。"},"20204":{"solution":"社会存在包括地理环境、人口因素和物质资料生产方式。前两者只是自然前提，起加速或延缓作用；生产方式才是社会发展的决定力量，它决定社会性质、结构和面貌，制约社会形态更替。","optionAnalysis":{"A":"生产方式是社会存在中最本质的部分，生产力与生产关系的矛盾推动社会运动，因而对社会发展起决定作用。","B":"地理条件只提供物质前提，作用表现为加速或延缓，不能决定社会制度的性质与更替。","C":"社会意识由社会存在派生，虽有反作用，但属于被决定的一方，不能充当决定因素。","D":"人口因素同样只是自然前提，其数量质量影响发展速度，却决定不了社会形态的性质。"},"memoryTip":"决定作用只给“生产方式”；地理和人口一律记作“前提＋加速延缓”。"},"20205":{"solution":"社会意识相对独立性有几种表现：与社会存在变化不同步、与经济发展水平不平衡、有历史继承性、各形式相互影响。但最能体现“相对独立”的，是它能反过来作用于社会存在，这是独立性最突出的表现。","optionAnalysis":{"A":"不同步性只说明社会意识变化可能滞后或超前，是独立性的一种表现，但不及反作用突出。","B":"历史继承性说明社会意识有自身发展脉络，属表现之一，程度次于能动反作用。","C":"能动反作用表明社会意识不只是被动结果，还能推动或阻碍社会发展，正是相对独立性最突出的表现。","D":"不平衡性指意识水平与经济水平可能不一致，属表现之一，不是最突出者。"},"memoryTip":"“最突出”只对应反作用：意识能反过来推或拖社会存在。"},"20206":{"solution":"生产关系包括生产资料所有制、生产中人与人的关系、产品分配关系三项。其中所有制回答生产资料归谁所有，决定人们在生产中的地位和分配方式，是整个生产关系的基础。","optionAnalysis":{"A":"生产资料所有制决定劳动者与生产资料的结合方式，进而决定生产中的地位和分配，是生产关系中最根本的方面。","B":"分配和交换由所有制决定，是生产关系的结果性环节，不能反过来充当决定者。","C":"人在生产中的地位与相互交换关系由所有制形式派生，处于被决定的位置，不能反过来充当基础。","D":"管理者与生产者的地位差别是人与人类关系的具体表现，根源仍在所有制。"},"memoryTip":"生产关系三层，所有制是地基；地位和分配都由它派生。"},"20207":{"solution":"路线、方针、政策属于上层建筑中的政治与思想成分，经济迅猛发展属于经济基础的巩固和发展。前者促进后者，说明上层建筑并非消极被动，而是对经济基础有积极能动的反作用。","optionAnalysis":{"A":"经济基础决定上层建筑是唯物史观的基本原理，说经济基础发展道路由上层建筑决定，颠倒了决定关系。","B":"上层建筑只能反作用于经济基础，发展方向归根到底由生产力与生产关系的矛盾决定，该项夸大了上层建筑。","C":"正确反映经济基础要求的路线方针政策，通过调动生产者和保护所有制关系推动经济发展，正是积极能动作用的体现。","D":"社会主义社会同样受两大规律制约，只是矛盾性质不同、可通过改革自我完善，否认规律制约属错误。"},"memoryTip":"政策促经济——上层建筑“反作用”的标准例证，别升级成“决定”。"},"20208":{"solution":"上层建筑是建立在一定经济基础之上的意识形态以及相应的制度、组织和设施。它由观念上层建筑和政治上层建筑两部分构成，整体上属于思想关系范畴，其性质由经济基础决定。","optionAnalysis":{"A":"社会经济制度即占统治地位的生产关系总和，属于经济基础，不是上层建筑。","B":"科学技术属于生产力范畴，是渗透性要素，既非意识形态也非制度设施。","C":"社会生产关系构成了经济基础本身，与上层建筑分属两个层次。","D":"该项准确概括了上层建筑的两部分构成及其对经济基础的依赖关系，与定义完全一致。"},"memoryTip":"上层建筑＝观念（意识形态）＋政治（制度组织设施），立在经济基础之上。"},"20209":{"solution":"社会形态不是单一要素，而是经济基础与上层建筑的统一体，并且这种统一以一定发展阶段的生产力为物质前提。它因此成为区分不同社会性质的整体标志。","optionAnalysis":{"A":"生产力与生产关系的统一是生产方式，回答社会存在中如何生产，尚未包括政治与观念结构。","B":"该项同时点出生产力前提、经济基础与上层建筑两个层面，完整对应社会形态的内涵。","C":"社会存在与社会意识的统一过于宽泛，社会形态特指经济结构与上层建筑的统一。","D":"物质世界与精神世界的统一是哲学基本问题的展开，不是历史唯物主义的社会形态概念。"},"memoryTip":"生产方式＝生产力＋生产关系；社会形态＝经济基础＋上层建筑，两对别串。"},"20210":{"solution":"唯物史观把生产力与生产关系、经济基础与上层建筑这两对矛盾的运动概括为人类社会发展的基本规律，它贯穿一切社会形态，是判断社会发展方向的总线索。","optionAnalysis":{"A":"生产方式内部矛盾只涉及生产力与生产关系一对，范围小于题干要求的一般规律。","B":"两项矛盾合起来才构成贯穿人类始终的一般规律，该项表述完整。","C":"社会存在与社会意识的关系是历史观的基本问题，属哲学基本问题在社会历史领域的体现，不是规律表述。","D":"物质生产与精神生产的关系是派生现象，不能取代两对社会基本矛盾。"},"memoryTip":"一般规律要“两对并存”：生产力—生产关系、经济基础—上层建筑，成对记。"},"20211":{"solution":"阶级斗争是阶级社会发展的直接动力，它推动生产力发展和生产关系调整，但最集中的成果是打碎旧制度、建立新制度，即实现社会形态的更替。","optionAnalysis":{"A":"阶级斗争能解放生产力，但生产力发展还依赖科学技术等条件，不是其推动作用最突出之处。","B":"生产关系变革常是阶级斗争的直接结果，但变革本身仍要落到社会形态更替才算完成。","C":"社会形态更替把经济、政治、思想领域的变革集中起来，是阶级斗争推动作用最突出的表现。","D":"科技进步有自身逻辑，并不由阶级斗争直接决定，把它当作突出表现属张冠李戴。"},"memoryTip":"阶级斗争的“突出表现”落在制度换轨——社会形态更替，不是日常改良。"},"20212":{"solution":"生产力包括劳动者、劳动资料和劳动对象。劳动者是主导因素，但衡量水平要用可客观比较的尺度，即劳动资料尤其是生产工具，它标志着人类改造自然的物质装备程度。","optionAnalysis":{"A":"劳动者技术水平重要，却是主观能力，难以充当客观尺度，且水平高低最终通过工具体现。","B":"产品质量受工艺、管理等影响，是生产结果，不能直接衡量生产力发展水平。","C":"生产工具是生产力发展水平的客观标志，工具变革划分经济时代，与题干“客观尺度”吻合。","D":"劳动对象的广度深度反映利用自然的范围，归根到底仍由工具水平决定。"},"memoryTip":"衡量生产力看“工具”，马克思按工具把历史分为石器、青铜、铁器、机器时代。"},"20213":{"solution":"生产关系是一个由多方面构成的体系，其中生产资料所有制回答生产资料归谁占有，决定生产过程中人与人的地位和产品分配方式，因而处于最基本、决定的地位。","optionAnalysis":{"A":"生产中人的地位和相互关系由所有制决定，属于被决定环节。","B":"产品分配形式是所有制和人们在生产中地位的结果，不能充当决定者。","C":"消费关系是生产关系在再生产中的延伸环节，由所有制和分配方式决定，更不具备基础地位。","D":"生产资料所有制关系是全部生产关系的起点，决定生产经营成果的归属，故为最基本方面。"},"memoryTip":"先定“归谁所有”，才有“什么地位”和“怎么分配”，所有制是生产关系第一层。"},"20214":{"solution":"上层建筑对社会的反作用有两种方向：促进或阻碍。判断标准不在它自身完善程度或阶级属性，而在于它所维护的经济基础当时是否适合生产力发展的要求。","optionAnalysis":{"A":"上层建筑自我完善可能有利于也可能不利于新经济基础，不能据此判定作用性质。","B":"国家政权是上层建筑的核心，但它服务于何种经济基础才决定作用性质，属中间环节。","C":"阶级性说明上层建筑代表谁的利益，却不直接回答它推动还是阻碍社会发展。","D":"经济基础适合生产力时，维护它的上层建筑起促进作用；反之起阻碍作用，该项抓住了判定标准。"},"memoryTip":"上层建筑好坏看“站队”：站在适合生产力的经济基础一边就促进，反之阻碍。"},"20215":{"solution":"国家是阶级矛盾不可调和的产物，是经济上占统治地位的阶级进行政治统治的工具，其核心是暴力机关。因此国家的实质是阶级统治的暴力机关。","optionAnalysis":{"A":"国家表面上调和矛盾，实质是统治阶级用来压制被统治阶级的工具，把调和当实质属掩盖阶级性。","B":"国家总是属于一定阶级，不存在超阶级的独立力量，该项属超阶级国家观。","C":"军队、警察、法庭、监狱等强制机关构成国家权力的核心，说明国家是阶级统治的暴力机关。","D":"管理公共事务是国家承担的社会职能，服务于政治统治，不能等同于国家实质。"},"memoryTip":"国家实质抓住“阶级统治＋暴力机关”两层，别被“公共管理”职能迷惑。"},"20216":{"solution":"“自然历史过程”强调的是社会同自然界一样，受不以人的意志为转移的客观规律支配，因而可以被科学地认识。它并不否认社会运动的特殊性，也不否认人的自觉活动。","optionAnalysis":{"A":"社会运动包含有意识的人的活动，与自然过程有本质区别，只能说二者都是客观规律过程。","B":"该项指出社会发展有客观规律可循，正是“自然历史过程”的实质含义。","C":"社会意识具有能动反作用，认为它无能为力属机械决定论，也曲解了命题。","D":"精神起决定作用属唯心史观，与社会发展是客观过程正相反。"},"memoryTip":"“自然历史”重在“有规律、可认识”，不是把社会等同于自然界。"},"20217":{"solution":"生产方式回答人类怎样谋取物质生活资料，由生产力（内容）和生产关系（形式）两方面构成，二者的统一构成社会的物质生产方式。","optionAnalysis":{"A":"生产力与生产关系的统一正是生产方式的完整定义，既含技术内容又含社会形式，与题干吻合。","B":"社会存在与社会意识的统一涵盖整个社会生活，范围远大于生产方式。","C":"自然与社会的统一讲的是人类世界这一更宏观范畴，不能缩小为物质资料生产方式。","D":"生产资料与生产者只是生产力内部的要素关系，缺了生产关系这一面。"},"memoryTip":"生产方式＝生产力（内容）＋生产关系（形式），一“内容”一“形式”记牢。"},"20218":{"solution":"社会政治结构指政治上层建筑，包括政治法律制度及军队、警察、法庭、政府机构等设施。其中掌握强制力的国家政权居于核心，其他政治组织与制度都围绕它展开。","optionAnalysis":{"A":"政治思想属于观念上层建筑，为政治结构提供理论依据，但不是政治结构的实体核心。","B":"哲学是系统化的世界观，属意识形态范畴，离政治结构更远。","C":"国家政权掌握暴力强制力，是政治上层建筑的核心，其他机关与制度都由它派生。","D":"阶级和政党围绕国家政权活动，其地位取决于是否掌握政权，不能取代政权本身。"},"memoryTip":"政治结构核心是“权”：国家政权；政治思想只是它的理论外衣。"},"20219":{"solution":"社会存在包括地理环境、人口因素和物质资料生产方式。前两者提供物质条件，是社会存在和发展的自然前提；生产方式才是决定力量。题干问“自然前提”，答案落在前两者。","optionAnalysis":{"A":"全部自然界中只有进入人的实践活动范围的部分才构成社会条件，说“全部”范围过宽。","B":"地理环境与人口因素共同构成社会赖以存在的自然物质条件，符合“自然前提”的限定。","C":"生产方式是决定力量，属于社会存在的核心，而不是“自然前提”。","D":"人类世界是自然与社会相统一的整体概念，不能充当自然前提本身。"},"memoryTip":"问“前提”答地理＋人口，问“决定”答生产方式，两个限定词分开记。"},"20220":{"solution":"地理环境提供生产和生活的自然条件，其优劣影响劳动生产率和社会分工，但只能加快或减慢发展速度，不能决定社会制度的性质与更替。","optionAnalysis":{"A":"决定作用属于生产方式，地理环境决定论已被唯物史观否定。","B":"地理环境通过生产过程影响劳动生产率，作用虽非决定却不是无足轻重。","C":"地理条件好坏直接影响投入产出效率，从而加速或延缓社会发展，符合教材表述。","D":"国家民族存亡由社会内部矛盾和综合国力决定，地理条件不能起决定作用。"},"memoryTip":"自然条件（地理、人口）统一记“加速或延缓”，见“决定”即排除。"},"20221":{"solution":"人民群众指推动历史发展的社会力量，其主体是从事物质资料生产的劳动群众及其知识分子，因为物质生产是社会存在和发展的基础。","optionAnalysis":{"A":"先进阶级是人民群众中的重要部分，但“主体”限定为劳动群众，此项范围偏窄且重心偏移。","B":"劳动群众承担物质生产，是社会生存发展的承担者，构成人民群众的主体。","C":"杰出人物属于个人范畴，作用再大也不能代替群众的主体地位。","D":"知识分子是人民群众的一部分，但单独抽取某一群体不足以界定主体。"},"memoryTip":"人民群众主体锁定“劳动者”——谁生产物质资料，谁是历史主体。"},"20222":{"solution":"社会主义改革是社会主义制度的自我完善和发展，不是改变根本制度，而是调整不适应生产力发展的体制机制。判断改革得失的根本标准在于是否有利于解放和发展生产力。","optionAnalysis":{"A":"改革坚持社会主义方向，改变根本制度就变成社会革命性质，与改革前提相悖。","B":"完善制度是改革的性质与途径，但落脚点是扫除生产力发展的体制障碍，尚非“根本目的”。","C":"解放和发展生产力是改革的根本目的与根本标准，与社会主义本质要求一致。","D":"实现社会公平是改革追求的重要目标之一，但不能取代生产力标准这一根本尺度。"},"memoryTip":"改革两句话：性质是“完善制度”，目的是“解放和发展生产力”，问目的选后者。"},"20223":{"solution":"“剧中人”指人民群众身处既定历史条件之中、受规律制约；“剧作者”指他们通过实践创造历史。既受制约又主动创造，正是历史唯物主义关于历史主体与客观规律相统一的观点。","optionAnalysis":{"A":"唯心史观夸大个别人物或精神力量，通常把群众写成被动配角，与题干并提两种身份不合。","B":"折中主义是无原则地把对立观点拼在一起，题干表述有内在统一逻辑，不是简单拼凑。","C":"该项既承认历史条件对人的制约，又承认人民群众的创造作用，符合历史唯物主义基本立场。","D":"历史循环论主张社会周而复始，否认发展，与题干强调创造历史不符。"},"memoryTip":"“剧中人”记受制约，“剧作者”记能创造，一句台词装下唯物史观两条原理。"},"20224":{"solution":"劳动是人类最基本的实践活动，是人与自然之间的物质变换过程。生产关系、阶级、国家、意识都由劳动发展派生，因此劳动发展史是理解整个人类社会发展的钥匙。","optionAnalysis":{"A":"阶级斗争只在阶级社会存在，无法解释无阶级社会的历史，作为钥匙范围不全。","B":"思想发展史由物质生产决定，用它解释历史属于以意识说明存在的唯心路径。","C":"劳动是社会实践的最基本形式，一切社会关系在劳动中生成，故为理解社会发展的钥匙。","D":"文化发展史是精神生活的一个侧面，同样受物质生产制约，不能作钥匙。"},"memoryTip":"钥匙是“劳动”：劳动派生一切社会关系，先有劳动史才有其他史。"},"20225":{"solution":"列宁的阶级定义从生产资料占有关系出发，把阶级归结为在一定社会经济结构中处于不同地位的社会集团。这种地位差别本质上是经济关系差别，故阶级是经济范畴。","optionAnalysis":{"A":"思想范畴指观念层面的东西，阶级虽有自己的意识形态，但其划分依据不在思想。","B":"阶级划分的根据是对生产资料的占有关系及由此决定的社会地位，属经济范畴。","C":"阶级形成后会有政治表现，但政治是经济地位的上层表现，不是实质规定。","D":"文化范畴属观念层面，由经济地位派生，用它界定阶级恰恰颠倒了决定与被决定的关系。"},"memoryTip":"阶级看“钱袋子”归属——列宁的定义落在经济结构中的不同地位。"},"20226":{"solution":"英雄史观把历史归结为帝王将相、杰出人物的意志与活动，认为少数人的思想决定社会走向，其理论前提正是社会意识决定社会存在，属唯心史观。","optionAnalysis":{"A":"人是社会历史的主体是唯物史观命题，英雄史观恰恰把主体缩小为少数英雄。","B":"意识具有能动作用本身正确，但英雄史观把它夸大为决定作用，用此项概括其出发点不准确。","C":"把少数英雄的意志看作历史本源，等于主张意识第一性，正是英雄史观的理论出发点。","D":"受偶然性支配是唯心史观的一个推论，其更深根据仍是意识决定存在。"},"memoryTip":"英雄史观＝“思想决定历史”的别名，根源是社会意识决定社会存在。"},"20227":{"solution":"人民群众创造历史体现在物质财富、精神财富的创造和社会变革的决定力量三方面。其中最根本的是他们作为生产力的体现者，通过生产劳动提供社会存在和发展的物质基础。","optionAnalysis":{"A":"人数多只是量的规定，不能说明为何具有创造历史的决定作用。","B":"劳动群众是生产力中最活跃的因素，掌握生产工具进行物质生产，因此成为历史创造者的根本依据。","C":"先进思想由实践产生并需群众掌握，把它当作根本原因属唯心主义解释。","D":"掌握历史规律是先进政党等力量的认识成果，不能作为群众创造历史的根据。"},"memoryTip":"根本原因只有一条：群众是生产力的体现者，物质生产撑起整个社会。"},"20228":{"solution":"杰出人物的产生有必然性的一面：时代需要、阶级需要决定了“需要这样的人物”；也有偶然性的一面：由谁出现、在何时何地出现带有偶然。二者统一，必然通过偶然实现。","optionAnalysis":{"A":"纯粹偶然论否认历史条件对人物的筛选作用，无法解释为何特定时代会产生特定类型的人物。","B":"纯粹必然论把具体人物的身世机遇也视为注定，属机械决定论，无法解释个体的偶然性。","C":"时代需要提供必然，具体人物出场体现偶然，二者统一才是完整回答。","D":"该项把偶然与必然分配到不同人物身上，割裂了同一过程中的两个方面。"},"memoryTip":"“时势造英雄”记必然，“谁成为英雄”记偶然，二者合成偶然与必然的统一。"},"20229":{"solution":"恩格斯的合力论指出，历史由无数个人意志相互作用形成，结果不取决于哪一个人的意志。这说明影响历史的因素是复杂交错的，但合力仍受客观规律支配，历史可以被认识。","optionAnalysis":{"A":"合力论恰是要说明众多意志背后有客观规律，认为无规律可循是对该理论的误读。","B":"历史合力有规律即可被科学把握，说无法认识属不可知论。","C":"无数意志与经济、政治、文化条件相互作用，形成复杂因素系统，正是合力论要表达的内容。","D":"每个人的意志都作为一个分力参与合力，该项否认了个人的参与，与原意相反。"},"memoryTip":"合力≠无规律：说的是“因素复杂”，结论仍是历史有规律、可认识。"},"20230":{"solution":"社会关系分为物质关系和思想关系。生产关系是不依人的意志为转移的物质关系，其他政治的、思想的关系都建立其上，因此是最基础的关系。","optionAnalysis":{"A":"生产关系是人们在社会生产中结成的物质关系，决定其他一切社会关系，符合题意。","B":"血缘关系在早期社会影响较大，但其地位随生产方式变化，不构成最基础关系。","C":"政治关系是生产关系在政治领域的集中表现，属派生的上层关系，不能充当最基础的关系。","D":"思想关系属观念层面，由物质关系决定，不能充当基础。"},"memoryTip":"基础只认“物质关系”，生产关系的另一张名片就是物质关系。"},"20231":{"solution":"人口因素是社会存在和发展的必要条件，其数量、质量、结构和分布影响生产与消费，但只能制约和影响社会发展速度，不能决定社会制度的性质与更替。","optionAnalysis":{"A":"社会制度性质由占主导的生产关系决定，人口状况相近而制度不同的国家比比皆是。","B":"制度更替根源于生产力与生产关系的矛盾，人口变动不是根本动力。","C":"适度的人口规模与较高质量有利于发展，失调则拖累发展，故为制约和影响作用。","D":"国家贫富强弱取决于生产方式与综合国力，人口多少不能单独决定。"},"memoryTip":"人口和地理同档：都是“制约影响”，凡带“决定”的选项一律排除。"},"20232":{"solution":"地理环境影响社会发展的路径是间接的：它通过影响劳动生产率、生产部门布局和分工方式来起作用，而不是直接改变人的心理或生理结构。","optionAnalysis":{"A":"心理素质受社会文化与实践塑造，地理环境不经心理渠道直接决定社会发展。","B":"人的生理结构变化极其缓慢，与社会发展速度不对应，且非地理作用的主渠道。","C":"民族气质属文化心理现象，是长期社会生活的产物，不是地理环境作用的主要中介。","D":"地理条件优劣先影响生产的成本与效率，再影响整个社会，生产过程中介说符合教材。"},"memoryTip":"自然条件必须“过生产这道关”才起作用，中介是生产过程。"},"20233":{"solution":"劳动是人与自然之间的物质变换过程，人通过生产劳动有意识地改造自然，又在劳动中结成社会关系。因此生产劳动是把人与自然联结起来的中介。","optionAnalysis":{"A":"地理环境是人活动的对象和场所，属于被改造的一方，不是联结的中介。","B":"生产劳动使人从自然界分化出来又与之保持物质变换，正是联结人与自然的中介。","C":"社会关系是劳动过程中形成的人与人关系，解决的是人与人的联结。","D":"社会意识属观念层面，只能反映人与自然的变换过程，不能承担物质变换的中介职能。"},"memoryTip":"人与自然之间只隔一层“劳动”，劳动既是分化点也是联结点。"},"20234":{"solution":"物质资料生产方式指人类谋取生活资料的方式，包含生产力与生产关系两个方面：前者说明用什么生产，后者说明在何种社会形式下生产。","optionAnalysis":{"A":"劳动者与劳动工具只是生产力内部要素，缺少生产关系这一半。","B":"劳动资料与劳动对象同属生产力的物的要素，依然不完整。","C":"生产资料不是与生产关系并列的一方，它是生产力的构成要素，搭配错误。","D":"生产力与生产关系的统一才构成完整生产方式，与定义一致。"},"memoryTip":"凡问“生产方式包括”，答案就是生产力＋生产关系，其他组合都是拆零件。"},"20235":{"solution":"劳动是人区别于动物的根本标志，而劳动是从制造和使用工具开始的。动物只能利用现成自然物，人则制造工具并借此改造自然，因此制造使用工具成为根本标志。","optionAnalysis":{"A":"制造和使用工具标志人开始了生产劳动，从而与动物的本能活动划界，符合教材表述。","B":"宗教信仰是社会发展一定阶段的产物，并非人与动物的分野。","C":"动物也有信号交流，语言文字是人类社会长期发展的结果，不是根本标志。","D":"某些高等动物已有初步心理活动，单凭意识不足以划出人与动物的根本界限。"},"memoryTip":"分界线画在“造工具”上：动物用现成的，人自己造。"},"20236":{"solution":"科学技术不是生产力的独立要素，而是渗透性要素。它通过武装劳动者、革新生产工具、拓展劳动对象、改进管理，转化为直接生产力，所以马克思说科学是生产力。","optionAnalysis":{"A":"生产力的独立要素只有劳动者、劳动资料、劳动对象三类，科学技术渗透其中而非独立并列。","B":"把诸要素组合起来的是生产过程和管理，科学技术提供的是知识手段，不能独自充当组合者。","C":"科学技术在未应用于生产前只是知识形态，物化后才成为直接生产力，说它本身就是直接要素不准确。","D":"科技通过渗透到劳动者、工具、对象和管理中提高效率，完成由知识形态向现实生产力的转化。"},"memoryTip":"科技是“渗透型”要素，记四个渗透点：人、工具、对象、管理。"},"20237":{"solution":"先进生产力以现代科学技术为支撑，劳动者素质提高、工具革新、对象拓展都依赖科技进步，因此科学技术成为先进生产力的集中体现和主要标志。","optionAnalysis":{"A":"劳动者是生产力中最活跃的因素，但先进与否要看其掌握的科技水平，本身不是标志。","B":"生产工具是生产力水平的客观尺度，属另一层表述；题干问“先进生产力的集中体现”，指向科技。","C":"现代科技进步决定要素素质和劳动效率，是先进生产力的集中体现和主要标志。","D":"劳动对象随科技拓展，属于被带动的方面，不具标志意义。"},"memoryTip":"两问要分清：问“水平尺度”答工具，问“先进生产力标志”答科学技术。"},"20238":{"solution":"社会意识形态包括艺术、道德、政治法律思想、哲学、宗教等形式。政治法律思想直接反映并维护一定阶级的经济利益和政治统治，对其他形式起主导作用，因而是核心。","optionAnalysis":{"A":"艺术以形象方式反映生活，受政治法律思想影响，地位不在核心。","B":"道德依靠舆论和习俗调整关系，规范性强但方向由政治法律思想引导。","C":"政治法律思想离经济基础最近、阶级性最鲜明，为其他意识形态提供方向，故为核心。","D":"哲学提供世界观方法论，是理论基础，但直接维护统治的仍是政治法律思想。"},"memoryTip":"意识形态的“核心”给最靠近政权的那一个：政治法律思想。"},"20239":{"solution":"社会关系分为物质关系和思想关系，生产关系属物质关系。上层建筑包括观念形态和政治制度设施，它们以思想的社会关系为基础，归根到底属于思想关系范畴。","optionAnalysis":{"A":"物质关系指不以人的意志为转移的生产关系，上层建筑恰恰建立在其上而非属于它。","B":"上层建筑体现人们的意志与制度安排，属思想的社会关系，列宁正是如此区分两类关系。","C":"经济关系即生产关系，属经济基础，与上层建筑分属不同层次。","D":"财产关系是所有制关系的法律表现，仍属经济基础范畴。"},"memoryTip":"两类社会关系：生产关系＝物质，上层建筑＝思想，天平两端别放反。"},"20240":{"solution":"社会关系中最主要最基础的是生产关系。它是不依人的意志形成的物质关系，决定政治关系、思想关系、道德关系等一切其他社会关系的性质。","optionAnalysis":{"A":"道德关系属观念性社会关系，由生产关系决定并随其变化。","B":"思想关系是比较宽泛的类别，其中生产关系才是物质基础，此项把派生当基础。","C":"产品分配关系只是生产关系的一个环节，不能涵盖整个基础。","D":"生产关系是人们在生产中结成的物质关系，构成其他一切社会关系的基础。"},"memoryTip":"道德、思想、分配都是“分支”，主干只有生产关系这一条。"},"20241":{"solution":"生产资料所有制关系说明生产资料归谁所有，它决定劳动者在生产中的地位和产品分配方式，从而决定整个生产关系的性质，是生产关系的基础。","optionAnalysis":{"A":"所有制关系决定生产资料的占有格局，进而规定生产关系的性质，符合题意。","B":"人的地位和相互交换关系由所有制派生，属被决定环节。","C":"分配关系是所有制和人们生产地位的结果，由前者派生，不具有决定生产关系性质的功能。","D":"是否适应先进生产力是评判生产关系优劣的标准，不是决定其性质的内在根据。"},"memoryTip":"所有制是“母”，地位与分配是“子”；性质问题一律回到所有制。"},"20242":{"solution":"杰出人物能够提出先进思想、组织群众、推动变革，从而加快或延缓历史进程。但历史发展方向由社会基本矛盾决定，个人无法改变规律与制度性质。","optionAnalysis":{"A":"历史方向由生产力与生产关系的矛盾运动决定，任何个人都不能决定。","B":"杰出人物的作用表现为影响历史进程的快慢与具体面貌，即加速历史发展，符合教材表述。","C":"社会性质由占主导地位的生产关系决定，个人无论多有影响都无法加以决定。","D":"规律是客观的，人物只能认识和利用而不能决定，该项属唯心史观。"},"memoryTip":"个人作用限定在“速度与面貌”，凡“决定方向、性质、规律”全错。"},"20243":{"solution":"生产关系一定要适合生产力状况的规律，揭示了社会发展的最终动力，是贯穿人类始终的最基本规律；上层建筑要适合经济基础状况的规律由它派生。","optionAnalysis":{"A":"对立统一规律是唯物辩证法的实质核心，属辩证法领域，不是社会发展规律。","B":"上层建筑适应经济基础的规律同样重要，但以生产力与生产关系的规律为基础，属次一级。","C":"生产力是最革命最活跃的因素，生产关系必须与之适合，这条规律构成社会发展的最基本规律。","D":"阶级斗争规律只在阶级社会起作用，不具备贯穿人类始终的普遍性。"},"memoryTip":"“最基本”给生产力那条；上层建筑那条由它派生，阶级斗争只管阶级社会。"},"20244":{"solution":"人口因素是社会物质生活的必要条件，其规模、素质、结构影响生产发展和社会稳定，但作用限于加速或延缓社会发展，不能决定制度性质与更替。","optionAnalysis":{"A":"制度更替根源于社会基本矛盾，人口变动最多起催化作用。","B":"人口适度与素质提高有利于发展，失调则阻碍发展，表现为加速或延缓。","C":"社会性质与面貌由生产方式决定，人口状况不能充当决定者。","D":"社会能否存在取决于物质资料生产，人口只是必要条件而非决定条件。"},"memoryTip":"人口的动词永远是“加速或延缓”，主语一旦换成“决定”就错。"},"20245":{"solution":"上层建筑由经济基础决定：经济基础的性质决定上层建筑的性质，经济基础变更则上层建筑迟早随之变革。因此上层建筑的根本性质取决于它所依赖的经济基础。","optionAnalysis":{"A":"经济基础是占统治地位的生产关系，它决定上层建筑的性质与变革方向，符合题意。","B":"政治制度本身是上层建筑的组成部分，不能用自身说明自身的根本性质。","C":"国家政权是上层建筑的核心，其性质同样由经济基础决定，属被决定者。","D":"意识形态是上层建筑的观念部分，不能反过来规定整体性质。"},"memoryTip":"“根本性质”往上追一层：上层建筑追到经济基础就到底了。"},"20246":{"solution":"生产劳动是人改造自然以满足自身需要的物质活动，它既让人从自然界分化出来形成社会，又使人始终与自然保持物质变换，因此是既区别又联系的基础。","optionAnalysis":{"A":"劳动使人摆脱动物式适应自然的状态并结成社会关系，同时又是人与自然之间的物质变换，符合题意。","B":"地理环境是人活动的场所和对象，只体现自然一面，说明不了二者的区别与联系如何生成。","C":"生产资料是劳动的产物和条件，本身不能承担分化与联结的双重功能。","D":"社会意识属观念层面，只能反映人与自然的物质变换，与自然界的直接物质联系无关。"},"memoryTip":"劳动一身两职：既把人从自然中“拉出来”，又把人和自然“连起来”。"},"20247":{"solution":"社会革命是阶级社会形态更替的根本途径，其核心是打破旧的上层建筑、建立新的政治统治。因此革命的根本问题是国家政权问题，政权转移标志革命成败。","optionAnalysis":{"A":"建立革命政党是革命的组织准备，服务于夺取政权这一目标。","B":"国家政权是上层建筑的核心，旧制度靠它维护，新制度靠它确立，故为革命的根本问题。","C":"革命理论提供思想指导，属主观条件，不能代替政权变革。","D":"发展生产力是革命的最终目的和结果，但革命首先要解决的是政权归属。"},"memoryTip":"革命问“根本问题”就答政权；理论、政党、生产力都是准备或结果。"},"20248":{"solution":"经济体制改革调整的是生产关系及其具体形式。改革后国民经济迅速发展，说明适合生产力的生产关系能推动生产力发展，即生产关系对生产力具有反作用。","optionAnalysis":{"A":"体制属于生产关系的具体形式，改革促发展体现生产关系反作用于生产力，表述准确。","B":"生产力决定生产关系是唯物史观基本原理，说生产关系决定生产力颠倒了因果。","C":"只有适合生产力状况的变革才促进发展，不适合的会阻碍，该项把条件绝对化了。","D":"生产力是最终决定力量，生产关系变化通过反作用影响而非决定生产力变化。"},"memoryTip":"改革改的是“关系”，发展的是“生产力”，锁定“反作用”，别写成决定。"},"20249":{"solution":"社会历史观的基本问题是社会存在与社会意识的关系问题。它回答社会历史的本原是物质还是精神，从而划分唯物史观与唯心史观，是哲学基本问题在历史领域的贯彻。","optionAnalysis":{"A":"物质和意识的关系是哲学基本问题的一般表述，尚未落到社会历史领域。","B":"社会存在与社会意识何者第一性，直接划分两种历史观，构成社会历史观的基本问题。","C":"人与人的关系是具体社会关系问题，由基本问题派生出解释。","D":"个人与群体的关系属于历史主体范畴的讨论，不是基本问题。"},"memoryTip":"哲学基本问题“下沉”到社会领域，就成了社会存在与社会意识的关系。"},"20250":{"solution":"社会经济形态由占统治地位的生产关系总和构成，而生产关系以生产资料所有制为基础，所有制性质不同，经济形态便不同，故区分标志是生产资料所有制的性质。","optionAnalysis":{"A":"生产力与生产关系的统一是生产方式，其中生产力不属于社会经济形态的划分依据，不能作标志。","B":"所有制性质决定生产关系性质，从而决定经济形态性质，是区分社会经济形态的基本标志。","C":"分配方式由所有制决定，属结果性标志，不能独立充当标准。","D":"人们在生产中的地位同样由所有制派生，不能作为基本标志。"},"memoryTip":"划分经济形态看“所有制”，因为它决定生产关系性质；分配和地位都是结果。"},"20251":{"solution":"题干问的是“根本原因”，必须追到社会存在决定社会意识这一总原理上。支配物质生产资料的阶级同时支配着精神生产资料，其思想才得以占据统治地位，所以根源在经济关系而非人数或宣传手段。","optionAnalysis":{"A":"人数多少只是阶级力量对比的表层现象，历史上统治阶级往往只是人口的少数，人数不能解释思想的统治地位。","B":"被统治阶级无权是思想统治得以维持的条件和结果，而不是统治阶级思想占统治地位的原因，因果被倒置了。","C":"占统治地位的物质关系必然表现为占统治地位的思想关系，经济上的统治地位是思想统治的现实基础，与题意吻合。","D":"宣传机器属于思想统治的传播手段，是派生的、被经济地位决定的因素，只能扩大影响而不能构成根本原因。"},"memoryTip":"记一句：“占统治地位的思想，不过是占统治地位的物质关系在观念上的反映。”"},"20252":{"solution":"关键在于区分社会意识形式中哪些立于经济基础之上、哪些不直接反映经济基础。自然科学揭示自然规律，不为特定经济基础服务，因而属于非上层建筑的社会意识形式。","optionAnalysis":{"A":"自然科学确实没有阶级性，但“没有阶级性”不等于“属于上层建筑”，上层建筑专指建立在经济基础之上的政治法律制度与意识形态。","B":"自然科学、语言学、形式逻辑等不直接反映经济基础、不随经济基础更替而改变性质，属非上层建筑的社会意识形式，表述准确。","C":"上层建筑总是特定经济基础的产物并为其服务，自然科学对任何社会制度都适用，把它归入某一经济基础的上层建筑不成立。","D":"必然性与偶然性的辩证统一是辩证法的一对范畴，说明的是事物联系发展的状态，与自然科学的社会意识归属无关。"},"memoryTip":"自然科学“无阶级性、又非上层建筑”，两头都要记住，最容易错选成“没有阶级性的上层建筑”。"},"20253":{"solution":"理论出发点指整个命题赖以建立的基石。唯物史观先确认社会存在决定社会意识、物质生产是社会存在的基础，而物质生产的主体正是人民群众，由此才推出人民群众创造历史。","optionAnalysis":{"A":"社会革命是历史的火车头，讲的是革命对历史进步的推动作用，属于社会发展动力问题，不是人民群众观的立论基石。","B":"阶级斗争是阶级社会发展的直接动力，只在阶级社会范围内适用，无法支撑贯穿一切社会形态的群众史观。","C":"社会存在决定社会意识是唯物史观的总出发点，社会存在的主体是从事物质生产的群众，正是该原理逻辑地引出群众是历史创造者。","D":"社会意识相对独立性说明的是意识对存在的反作用，方向恰好相反，不能作为群众创造历史的出发点。"},"memoryTip":"串成一条链：社会存在决定社会意识→物质生产是基础→生产者是人民群众。"},"20254":{"solution":"国家不是从来就有的，而是阶级出现后阶级对立无法调和的产物。恩格斯指出国家是阶级矛盾不可调和的表现，其作用是缓和冲突、把冲突控制在秩序范围内。","optionAnalysis":{"A":"“调和”二字正好说反了，如果阶级矛盾真能调和，就不需要凌驾于社会之上的国家权力了。","B":"社会契约论把国家说成人们订立契约的产物，是资产阶级思想家对国家起源的唯心主义解释，缺乏历史依据。","C":"这正是恩格斯的经典论断：国家是阶级矛盾不可调和的产物和表现，与题干完全对应。","D":"暴力论把国家起源归结为征服和暴力，忽视了暴力背后的经济利益和阶级对立，且暴力本身也是阶级矛盾的产物。"},"memoryTip":"“不可调和”才需要国家：调和论、契约论、暴力论三种错误一并排除。"},"20255":{"solution":"区分决定力量与必要条件。地理环境和人口因素只能加速或延缓社会发展，阶级斗争只在阶级社会起直接推动作用；唯有生产力是贯穿始终的最终决定力量。","optionAnalysis":{"A":"地理环境是社会发展的必要条件，好坏优劣能加速或延缓发展，但相同环境下社会形态可以不同，说明它不决定社会性质。","B":"人口因素同样是必要条件，人口数量和质量影响发展速度，却不能决定社会制度的性质和更替。","C":"阶级斗争是阶级社会发展的直接动力，原始社会和共产主义社会不存在阶级斗争，无法充当一般意义上的决定力量。","D":"生产力是社会发展的最终决定力量，决定生产关系的性质和社会形态的更替，与题干要求一致。"},"memoryTip":"地理人口是“条件”，阶级斗争是“直接动力”，生产力才是“决定力量”，三层不能混。"},"20256":{"solution":"经济基础不是笼统的全部经济关系，而是占统治地位的生产关系。它有两个限定：一是与一定生产力发展阶段相适应，二是在该社会中居于统治地位，故须选带这两个限定的表述。","optionAnalysis":{"A":"“一切社会关系的总和”是马克思对人的本质的界定，且社会关系还包括思想关系，拿来定义经济基础属于概念挪用。","B":"“一切经济关系”范围过宽，会把旧生产关系的残余和从属经济成分也算进来，而经济基础只指占统治地位的生产关系。","C":"“所有生产关系”缺少“占统治地位”这一关键限定，同样把不占主导地位的生产关系包含在内。","D":"既点明与生产力发展相适应，又限定为占统治地位的生产关系总和，两个要件齐备，是完整定义。"},"memoryTip":"抓两个关键词：“相适应”“占统治地位”，缺一不可。"},"20257":{"solution":"马克思在《关于费尔巴哈的提纲》中提出，人的本质不是单个人所固有的抽象物，在其现实性上是一切社会关系的总和。题目问的正是这一经典论断。","optionAnalysis":{"A":"人的需要由所处社会关系决定并随社会关系变化，它是被决定的东西，不能反过来充当人的本质。","B":"自然属性即生物本能，是人与动物共有的属性，无法把人与动物区别开来，因而不是人的本质。","C":"把人的本质归于共同利益，是脱离社会关系去设想抽象人性的唯心主义人性论。","D":"社会关系总和既指明本质的现实来源，又体现人的本质随社会关系而变化，与马克思的原意一致。"},"memoryTip":"背原话：“一切社会关系的总和”，别丢“社会”二字，自然属性、共同利益都是干扰。"},"20258":{"solution":"唯物史观与唯心史观的根本分歧不在个别观点，而在历史观的基本问题即社会存在与社会意识何者第一性。承认社会存在决定社会意识即为唯物史观，反之则是唯心史观。","optionAnalysis":{"A":"唯心史观不但承认个人作用，还往往把历史归于少数英雄人物，因此这一条无法把两种历史观分开。","B":"承认意识的能动作用并不是分水岭，唯心史观夸大意识作用，唯物史观在存在决定意识前提下也承认能动作用。","C":"资产阶级历史学家同样承认阶级和阶级斗争的存在，承认阶级斗争并不等于坚持唯物史观。","D":"社会存在决定社会意识是历史观的基本问题，对这一问题的不同回答正是划分两种历史观的根本标准。"},"memoryTip":"分水岭只有一条：社会存在与社会意识谁决定谁，其余都是枝叶。"},"20259":{"solution":"题干说的是“基础及决定力量”，指向社会存在的核心内容。社会存在包括地理环境、人口因素和物质资料生产方式，其中生产方式是基础它决定社会的性质、结构和形态更替。","optionAnalysis":{"A":"自然环境是社会存在的自然前提，提供生产和生活的资料与场所，但相同自然条件下可以有不同社会制度，故不具决定作用。","B":"人口因素影响社会发展的速度和规模，却不能说明社会制度的性质，也不是社会形态更替的依据。","C":"阶级斗争仅限于阶级社会，是阶级社会发展的直接动力，无法充当一切社会形态的共同基础。","D":"物质资料生产方式是社会存在中最主要的方面，是社会历史发展的决定力量，符合“基础及决定力量”的限定。"},"memoryTip":"社会存在三要素，地理环境和人口是“前提”，生产方式才是“基础和决定者”。"},"20260":{"solution":"社会意识是与社会存在相对应的范畴，指社会生活的精神方面，是全部社会精神现象的总称。它既包括低层次的社会心理，也包括高层次的社会意识形式，不能以其中某一部分代替整体。","optionAnalysis":{"A":"把社会意识界定为一切社会精神现象的总称，外延完整，涵盖社会心理与社会意识形式两个层次。","B":"社会意识形态只是社会意识形式中反映经济基础的那一部分，用它代替整体，等于缩小了社会意识的外延。","C":"自然科学、社会科学和思维科学是按研究对象对科学的分类，属科学体系划分，不是社会意识这一哲学范畴的定义。","D":"社会心理只是社会意识的低层次、自发的部分，社会意识还包括系统化理论化的社会意识形式。"},"memoryTip":"社会意识=全部精神现象，它大于社会心理，也大于社会意识形态，别以部分代整体。"},"20261":{"solution":"社会生活本质上是实践的。自然界只提供自然前提，人口是必要条件，生产关系是生产的社会形式，真正支撑社会生存和发展的是物质生产实践这一最基本的实践活动。","optionAnalysis":{"A":"自然界是人类生存的自然前提，但社会的基础在社会自身的实践活动，单纯的自然界不能说明社会的形成与发展。","B":"生产关系是物质生产的社会形式，脱离生产力便无法独立支撑社会生存，不能单独充当基础。","C":"人口是社会存在的必要条件，没有人口固然没有社会，但人口本身也要靠物质生产来维持。","D":"物质生产实践解决吃喝住穿等基本需要，是社会存在和发展的基础，也是其他一切活动的前提。"},"memoryTip":"题干出现“生存和发展的基础”，直接锁定物质生产实践，不要被“自然界”迷惑。"},"20262":{"solution":"自然与社会既相互区别又相互统一，其结合点在劳动。劳动是人以自身的活动引起、调整和控制人与自然之间物质变换的过程，人和社会在劳动中从自然分化出来又与之保持统一。","optionAnalysis":{"A":"生产劳动是人与自然之间的物质变换过程，既创造了人和社会，又把人同自然联系起来，因而构成二者分化与统一的基础。","B":"自然界只是统一体中的一方，把自然本身当作统一的基础，等于取消社会相对自然的独立性。","C":"人虽是连接自然与社会的承担者，但人的这种连接作用是在劳动中实现的，人不能抽象地充当基础。","D":"社会同样只是统一体的一方，以社会为基础无法说明它如何从自然中产生并与自然保持物质变换。"},"memoryTip":"劳动是“分”与“合”的同一个关节点：人在劳动中脱离自然，又在劳动中与自然交往。"},"20263":{"solution":"题目问的是“物质根源”，要追到一切社会关系由何而生。物质生产劳动是人类最基本的实践活动，人们在劳动中结成生产关系，进而派生出政治、思想等各类社会关系。","optionAnalysis":{"A":"生产关系是生产劳动中结成的关系，是劳动的产物和形式，把它当根源等于用结果解释原因。","B":"财产关系是生产关系在法律上的表现，属于派生的、被决定的关系，比生产关系更远离根源。","C":"阶级关系是生产关系在特定历史阶段的产物，范围狭窄且以生产关系为前提。","D":"生产劳动是一切社会关系得以生成的源泉，其他关系都在劳动基础上发展起来，最符合“物质根源”的要求。"},"memoryTip":"“根源”要往下追一层：不是生产关系，而是生成生产关系的生产劳动。"},"20264":{"solution":"唯心史观有两种形态，差别在于把历史动力归于何种精神因素。主观唯心史观把历史归于人的思想动机、个别英雄的意志，认为意见支配世界。","optionAnalysis":{"A":"地理环境决定论把社会状况归因于自然条件，属于自然主义的历史观，是旧唯物主义在历史领域的表现，不是主观唯心论。","B":"人口状况决定论同样从自然因素解释社会，与主观唯心论以精神为第一性的立场不同。","C":"“天数”即天命、天意，是凌驾于人之上的客观精神，属于客观唯心史观，而非主观唯心史观。","D":"把社会发展最终归于人的思想动机，正是主观唯心史观的典型命题，与题干要求一致。"},"memoryTip":"主观唯心看“动机与意志”，客观唯心看“天数与绝对观念”，两题要对照记。"},"20265":{"solution":"客观唯心史观设定某种超人类的客观精神作为历史的本原。黑格尔把历史看作绝对观念自我展开、自我实现的过程，是这类观点的典型代表。","optionAnalysis":{"A":"地理环境决定论属于自然主义历史观，用自然条件解释社会，不是以客观精神为本原的唯心史观。","B":"人口状况决定论仍是从自然因素出发解释社会历史，同样不属于客观唯心论。","C":"绝对观念是先于世界而存在的客观精神，把历史归于它的自我实现，正是客观唯心史观的标准表述。","D":"人的思想动机属于主观精神，把它当作历史动力是主观唯心史观的命题。"},"memoryTip":"和上一题成对记：绝对观念、天命、世界理性归客观唯心；个人动机、英雄意志归主观唯心。"},"20266":{"solution":"这段话讲的是历史合力的形成机制：无数个人意志相互冲突，最终形成不以任何个人意志为转移的总结果。恩格斯借此说明历史进程受客观规律支配，而非由某个人的意志安排。","optionAnalysis":{"A":"“多种力量最后决定”表述含混，且会滑向否认最终决定力量；恩格斯的原意是合力背后仍有客观规律在起作用。","B":"社会规律必须通过有意识、有目的的人的活动实现，与自然规律的作用方式有本质区别，说二者“相同”抹杀了这一差别。","C":"社会规律既有自发性也有自觉性，人的实践活动自觉参与其中，说它纯粹自发实现不符合原意。","D":"合力论恰恰证明历史不是意志的堆叠，而像自然过程一样受客观规律支配，与恩格斯论述的落脚点一致。"},"memoryTip":"记住落脚句：“像自然过程一样进行”——合力不等于无规律，而是证明有规律。"},"20267":{"solution":"题干限定“囊括全部社会生活”的总体性范畴。社会形态只包括经济基础与上层建筑，社会有机体则把生产力、生产关系、上层建筑以及人口、自然环境等要素全部涵盖在内，范围最广。","optionAnalysis":{"A":"社会形态是经济基础与上层建筑的统一体，不包括人口因素和自然环境，外延小于全部社会生活。","B":"社会经济结构仅指占统治地位的生产关系总和，只是社会生活的经济方面，覆盖面过窄。","C":"政治结构与观念结构属于上层建筑领域，只覆盖社会生活的政治和精神方面，遗漏了经济生活。","D":"社会有机体是把社会各要素、各领域作为相互依存的整体来把握的总体性范畴，最能对应“囊括全部社会生活”。"},"memoryTip":"比大小：社会有机体最大，社会形态次之，经济结构最小，题问“全部”就选有机体。"},"20268":{"solution":"生产力表示人类改造自然、获取物质生活资料的实际能力，体现的是人与自然之间的物质变换关系；生产关系才是人们在生产中结成的人与人的关系，两个范畴分工明确。","optionAnalysis":{"A":"生产力回答“人能用什么方式改造自然”，反映的正是人与自然之间的关系，与题干相符。","B":"人与社会的关系属于社会关系层面，其中生产关系才是生产力得以实现的社会形式，不是生产力本身反映的内容。","C":"人与劳动产品的关系涉及产品分配和消费，属于生产关系及交换消费领域的问题。","D":"劳动者与剥削者的关系是阶级社会中生产关系的表现，属于人与人之间的关系，不是人与自然的关系。"},"memoryTip":"一句口诀：“生产力管天人，生产关系管人人。”"},"20269":{"solution":"劳动资料是一个包含工具、能源、信息、控制等多个子系统的体系，其中生产工具直接作用于劳动对象，最能体现人类改造自然的实际能力，因而是具有决定意义的因素。","optionAnalysis":{"A":"生产工具是劳动资料中最重要的部分，既是生产力发展水平的客观尺度，也是区分社会经济时代的物质标志，符合题意。","B":"信息传递系统是劳动资料体系的组成部分，它服务于生产过程，其水平高低本身仍要由生产工具的状况来说明。","C":"自动化控制系统属于现代生产工具的延伸和组成部分，不能与生产工具系统并列充当决定因素。","D":"能源动力系统是劳动资料的重要构成，但动力必须通过工具作用于对象，起决定作用的中介仍是工具。"},"memoryTip":"工具是生产力的“骨骼系统”，也是划分经济时代的标尺，其余子系统围绕工具运转。"},"20270":{"solution":"生产方式指人类获取物质生活资料的方式，是生产力与生产关系的统一：生产力是其物质内容，生产关系是其社会形式，二者结合才构成生产方式。","optionAnalysis":{"A":"劳动者与生产资料的结合是生产力内部要素的结合，说明的是生产过程得以进行的条件，不是生产方式的定义。","B":"生产力作为内容、生产关系作为形式统一起来构成生产方式，这正是教材的标准表述。","C":"经济基础与上层建筑的统一构成的是社会形态，与生产方式不是同一概念。","D":"物质生产决定精神生产，二者是决定与被决定的关系，不存在“物质生产与精神生产的统一”这种生产方式规定。"},"memoryTip":"两组“统一”别混：生产力+生产关系=生产方式；经济基础+上层建筑=社会形态。"},"20271":{"solution":"列宁的阶级定义从经济地位入手，把阶级划分的根据确定为对生产资料的占有关系，即人们在生产关系体系中所处的地位不同，而不是收入多少或思想觉悟高低。","optionAnalysis":{"A":"对生产资料的占有关系决定人们在生产中的地位和产品分配方式，是划分阶级的根本依据，与题意一致。","B":"分配多少由占有关系决定，是占有关系的结果；以分配为标准会把高收入的被剥削者误判为剥削阶级。","C":"社会分工只是阶级产生的历史条件之一，分工本身并不直接标明阶级归属，同一分工位置上可有不同阶级。","D":"政治立场和思想觉悟是经济地位的派生表现，不同阶级的成员在思想上可能交叉，不能作为划分标准。"},"memoryTip":"阶级只看“占有”：占有生产资料的是剥削阶级，不占有并出卖劳动力的是雇佣劳动者。"},"20272":{"solution":"经济基础即占统治地位的生产关系总和，而生产关系是人们在生产中结成的不以人的意志为转移的物质关系，因此经济基础属于社会的物质关系、物质的社会关系。","optionAnalysis":{"A":"生产关系由生产力状况决定，人们不能自由选择，具有客观物质性，故经济基础属于物质关系，判断正确。","B":"思想关系是上层建筑中的意识形态和政治法律思想，属于被经济基础决定的上层领域，方向颠倒。","C":"阶级关系是生产关系在阶级社会的具体表现，范围窄于生产关系，且不是与物质关系并列的另一种关系。","D":"政治关系属于上层建筑范畴，是物质关系在政治上的反映，不能用来界定经济基础的性质。"},"memoryTip":"二分法记牢：经济基础是物质关系，上层建筑是思想关系，界线在“是否以人的意志为转移”。"},"20273":{"solution":"社会意识对社会存在的反作用不是自动实现的，必须通过人的实践活动。一种思想只有为群众所掌握，才能转化为改造社会的物质力量，因此作用大小取决于它掌握群众的广度和深度。","optionAnalysis":{"A":"社会意识只有被群众接受并付诸行动才能影响社会，掌握群众的广度和深度直接决定其反作用的大小，表述正确。","B":"是否为统治阶级服务并不决定作用大小，进步阶级的社会意识即使暂时不占统治地位，也能产生巨大影响。","C":"反映被统治阶级利益的程度同样不能作为尺度，关键在于是否掌握群众、是否符合社会发展规律。","D":"与经济发展水平是否平衡讲的是社会意识相对独立性的表现，说明的是发展不同步，而不是作用大小的衡量标准。"},"memoryTip":"记马克思那句话：“理论一经掌握群众，也会变成物质力量。”"},"20274":{"solution":"手工磨与蒸汽磨代表不同性质的生产工具，封建主为首的社会与工业资本家为首的社会代表不同性质的生产关系。马克思这句话正是说明生产力（以工具为骨骼）的性质决定生产关系的性质。","optionAnalysis":{"A":"这一项只说到生产工具是衡量生产力水平的尺度，停留在生产力内部，没有揭示题干要表达的“工具变革决定社会性质”的关系。","B":"题干并未涉及科学与工具变革的关系，而是直接用两种磨对应两种社会，重心不在科技的作用。","C":"社会形态更替的顺序性讲的是五种形态依次演进，题干强调的是工具与社会性质的对应，不是顺序问题。","D":"生产工具是生产力的骨骼系统，其性质决定生产力的性质，进而决定生产关系的性质，完整揭示了题干关系。"},"memoryTip":"“磨”是工具，“为首的社会”是生产关系：工具变→生产力变→生产关系变。"},"20275":{"solution":"社会基本矛盾是贯穿人类社会始终、决定社会性质和发展方向的矛盾，即生产力与生产关系的矛盾、经济基础与上层建筑的矛盾，二者构成社会发展的根本动力。","optionAnalysis":{"A":"敌我矛盾和人民内部矛盾是社会主义社会两类不同性质的社会矛盾，属于基本矛盾在特定阶段的表现，不是贯穿始终的基本矛盾。","B":"人与自然之间的矛盾是唯物辩证法讲的人与自然关系问题，不是社会基本矛盾的规范表述。","C":"阶级矛盾只是生产力与生产关系矛盾在阶级社会的集中表现，原始社会和共产主义社会并不存在阶级矛盾。","D":"这两对矛盾覆盖一切社会形态，是社会发展的根本动力，也是社会基本矛盾的完整表述。"},"memoryTip":"基本矛盾成对记：“生产力—生产关系”“经济基础—上层建筑”，贯穿始终、两对社会。"},"20276":{"solution":"历史唯物主义一元论指社会历史归根到底由物质生产力决定，反对把历史归于精神或多元因素。它讲的是“最终决定”的唯一性，并不否认社会发展动力的多样性。","optionAnalysis":{"A":"社会发展动力是分层次的系统，根本动力、直接动力、间接动力并存，说生产力是“惟一动力”把一元论误解为唯一动力。","B":"混淆了“一元”与“一个动力”，一元论回答的是何者最终决定，而不是动力数量的多少。","C":"政治、文化等因素也构成社会发展动力，只是归根到底受经济制约，把动力来源限于经济领域是简单化。","D":"物质生产力是社会发展的最终决定力量，正是历史唯物主义一元论的核心含义，表述准确。"},"memoryTip":"一句辨析：一元论讲“最终决定”，不讲“唯一动力”，动力可以很多，决定者只有一个。"},"20277":{"solution":"“最终决定”强调决定作用要经过中介环节层层传递。生产力先决定生产关系，再通过经济基础决定上层建筑，中间需要人的实践活动、革命与改革等环节，不是直线式的自动作用。","optionAnalysis":{"A":"生产力通过生产关系这一中介再去影响各种社会关系，并非直接决定一切，跳过中介就变成了机械决定论。","B":"生产关系的变革需要借助人的实践活动以及革命、改革等具体环节，不会自动发生，“自动引起”否认了人的能动作用。","C":"同一水平的生产力在不同国家和时期可以建立不同的生产关系，还受历史传统、国际环境等影响，并非只能有一种。","D":"生产力决定生产关系，并通过生产关系最终决定上层建筑的变革，完整表达了“最终决定”的传导路径。"},"memoryTip":"两层中介要记住：生产力→生产关系→上层建筑，是“最终”不是“直接”。"},"20278":{"solution":"生产关系一定要适合生产力状况的规律，要求政党既不能墨守已不适合生产力的旧生产关系，也不能脱离生产力水平盲目求新，而应建立并完善适合生产力发展的生产关系。","optionAnalysis":{"A":"“不断变革”脱离生产力实际状况，容易重犯盲目求纯、求大的“左”的错误，忽视了生产关系的相对稳定。","B":"把上层建筑也纳入“不断建立”的范围，超出了题干限定的生产关系问题，且同样带有盲目冒进色彩。","C":"只讲稳定不讲变革，当生产关系已不适应生产力时就会阻碍发展，属于另一端的片面性。","D":"以“适合生产力发展”为标准来建立和完善生产关系，恰是这一规律在政策上的直接要求，表述全面。"},"memoryTip":"政策落点在“适合”二字：既反对滞后不改，也反对拔苗助长。"},"20279":{"solution":"上层建筑能否促进社会发展，取决于它所服务的经济基础是否先进。服务于先进经济基础的上层建筑推动生产力发展，服务于腐朽经济基础的上层建筑则阻碍社会发展。","optionAnalysis":{"A":"与自己的经济基础相符合只是上层建筑存在的前提，若该经济基础已腐朽，符合得越紧反而阻碍越大，不能推出促进作用。","B":"上层建筑对生产力的作用必须经由经济基础这一中介，不是直接影响，说法跳过了中间环节。","C":"促进作用的实质是上层建筑为先进的经济基础服务，从而解放和发展生产力，与题干因果吻合。","D":"国家政权是上层建筑的核心，这是上层建筑内部结构的判断，本身成立却与题干所问的“促进作用”没有因果联系。"},"memoryTip":"判断标准不在“是否适合”，而在“所适合的经济基础是否先进”。"},"20280":{"solution":"科学产生于生产实践的需要，生产发展不断向科学提出新课题，并提供观测手段和实验设备，因此社会生产是科学发展最终起决定作用的力量。","optionAnalysis":{"A":"生产实践是科学认识的源泉和动力，生产的需要比十所大学更能推动科学前进，符合“决定作用”的限定。","B":"社会制度影响科学发展的方向和速度，可以为科学提供有利或不利的环境，但属于影响条件而非决定力量。","C":"文化教育水平制约科学人才的培养和知识传承，是重要条件，却不能最终决定科学的发展。","D":"科学本身就是一种社会意识形式，用社会意识去决定科学，等于同义反复，且颠倒了社会存在与社会意识的关系。"},"memoryTip":"记恩格斯的意思：生产一旦有技术需要，就比十所大学更能把科学推向前进。"},"20281":{"solution":"社会革命是社会形态的根本质变，其深刻根源不在主观热情，而在社会基本矛盾的尖锐化，即生产关系已严重阻碍生产力发展、上层建筑已严重阻碍经济基础变革。","optionAnalysis":{"A":"经济政治总危机是基本矛盾尖锐化的外在表现，属于现象层面，用表现解释根源是倒果为因。","B":"人民群众的革命热情和革命精神是革命得以发动的主观条件，只能影响革命的进程和时机，不是根源。","C":"社会基本矛盾尖锐化使现有生产关系成为生产力发展的桎梏，才使革命成为必然，正是革命的深刻根源。","D":"革命阶级觉悟程度和组织程度的提高同样是主观条件，缺少客观矛盾基础，觉悟再高也不会产生革命形势。"},"memoryTip":"客观矛盾是根源，热情与觉悟是条件：根在生产力与生产关系的冲突。"},"20282":{"solution":"社会革命是阶级斗争的最高形式，它推翻旧的上层建筑、建立新的上层建筑，从而实现社会形态的根本更替，因而是阶级社会形态更替的决定性环节。","optionAnalysis":{"A":"社会革命解决的是政权和社会制度问题，直接引起社会形态的质变，正是更替的决定性环节。","B":"阶级斗争是阶级社会发展的直接动力，但日常的阶级斗争多在不改变社会形态的范围内进行，只有上升为革命才实现更替。","C":"改革是同一社会形态内部的自我调整和完善，不改变社会形态的根本性质，不能充当更替的决定性环节。","D":"生产力发展是社会形态更替的最终决定力量，但它要通过革命这一环节才能实现，题干问的是“环节”。"},"memoryTip":"马克思称革命是“历史的火车头”，也是新社会形态的“助产婆”。"},"20283":{"solution":"杰出人物不是泛指有影响的人，而是指能够反映时代要求、顺应历史发展趋势，并在历史上产生重大进步作用和显著贡献的人物，进步性是其质的规定。","optionAnalysis":{"A":"重要历史事件的主要当事人和指挥者只表明参与程度，反动人物同样可以充当重大事件的指挥者，不含进步性要求。","B":"“重大影响”是中性的，影响可以是推动也可以是阻碍，阻碍历史前进的人物不能称为杰出人物。","C":"重大革命运动的领导者范围过窄，杰出人物的贡献并不限于革命运动，还包括科技、文化等领域。","D":"既强调反映时代要求，又强调进步作用和显著贡献，完整揭示了杰出人物的内涵，与教材表述一致。"},"memoryTip":"杰出人物=顺应时代+进步作用，光“有影响”不算，反动人物影响也很大。"},"20284":{"solution":"生产关系是人们在物质生产过程中结成的不以人的意志为转移的经济关系，包括生产资料所有制、人们在生产中的地位和交换关系、产品分配关系，其实质是人们的物质利益关系。","optionAnalysis":{"A":"人与自然的关系是生产力所反映的内容，生产关系恰恰是生产力得以实现的社会形式，二者不能互换。","B":"生产关系三方面归根到底都是物质利益关系，所有制决定利益格局，分配直接体现利益，表述准确。","C":"管理与被管理关系只是人们在生产中所处地位的一种具体形式，属于生产关系的一个侧面，不能等同于生产关系整体。","D":"分工协作关系是生产过程中组织形式的体现，同样只是生产关系的具体表现之一，外延过窄。"},"memoryTip":"生产关系“三要素、一实质”：所有制、地位交换、分配，实质是物质利益关系。"},"20285":{"solution":"大众心理属于社会意识，经济走势属于社会存在领域。心理预期影响消费和投资，说明社会意识能够反作用于社会存在，但这种作用只能是影响而不能是决定。","optionAnalysis":{"A":"社会意识决定社会存在是唯心史观的根本命题，把“影响”拔高为“决定”，颠倒了二者的关系。","B":"社会心理能影响经济运行，但社会发展方向由社会基本矛盾决定，说它可以“左右方向”夸大了反作用。","C":"错误的社会意识同样会阻碍社会发展，只是方向为负，说只有正确意识才起作用不符合事实。","D":"心理影响走势正是社会意识反作用于社会存在的具体体现，表述既唯物又辩证，与题意吻合。"},"memoryTip":"看到“影响”选反作用，看到“决定”“左右方向”立即排除。"},"20286":{"solution":"生产总是在一定的社会条件下进行，其中最基本、最重要的是生产关系。政治法律制度、文化传统、道德规范都属上层建筑因素，它们只能通过生产关系间接影响生产。","optionAnalysis":{"A":"政治法律制度属上层建筑，对生产的作用要经由生产关系才能实现，不是生产的社会条件中最基本者。","B":"生产关系是生产得以进行的社会形式，直接规定生产资料与劳动者结合的方式，因而是最基本最重要的社会条件。","C":"历史文化传统影响生产方式和经营管理风格，但属于观念层面的间接因素，不起基本作用。","D":"伦理道德规范调节生产中的人际关系，同样属上层建筑因素，不能与生产关系并列称最基本。"},"memoryTip":"四个选项中只有生产关系是“物质的社会关系”，其余三个都是上层建筑。"},"20287":{"solution":"马克思恩格斯指出，人们为了能够创造历史必须能够生活，而为了生活首先就需要吃喝住穿，因此生产满足这些需要的物质生活资料，是一切历史的第一个活动。","optionAnalysis":{"A":"吃喝穿住是人的自然需要本身，满足这些需要的活动才是生产，停留在需要层面还不能构成历史活动。","B":"物质生活资料的生产是满足生存需要的实践活动，正是人类第一个历史活动，也是其他一切活动的前提。","C":"把自觉意识活动当作历史起点，是唯心史观的典型思路，意识是在物质生产基础上才发展起来的。","D":"社会关系是在物质生产过程中结成的，生产在前、关系在后，不能倒置为第一个历史活动。"},"memoryTip":"“第一个历史活动”固定搭配物质生活资料的生产，别与“吃喝穿住”这种需要混淆。"},"20288":{"solution":"宪法是国家的根本法，属于政治上层建筑。将“国家尊重和保障人权”写入宪法，是政治法律制度的重大完善，标志着社会主义政治文明的进步。","optionAnalysis":{"A":"宪法修正是上层建筑领域的变革，生产关系指所有制和分配关系，二者不在同一层面。","B":"人权原则入宪健全了国家保障人权的法律制度，属于政治法律制度建设成果，归入政治文明范畴恰如其分。","C":"物质文明指物质生产的发展和物质生活水平的提高，宪法条文修改本身不直接体现物质文明成果。","D":"精神文明指思想道德建设和教育科学文化建设，人权入宪是法律制度安排，不属于精神文明范畴。"},"memoryTip":"宪法修改归“政治文明”，三个干扰项分别是生产关系、物质文明、精神文明。"},"20289":{"solution":"这段话强调吃饭问题是头等大事，用唯物史观解释就是：人们首先必须吃、喝、住、穿，然后才能从事政治、科学、艺术、宗教等活动，物质生活资料的生产是一切活动的前提。","optionAnalysis":{"A":"先解决吃穿住行才能从事政治、科技、艺术、宗教等活动，正是物质生产制约其他社会活动的通俗表达，与题意契合。","B":"人的生理需求是自然本能，历史的基础是物质生产方式，把本能当作历史基础是自然主义的历史观。","C":"人的本质在其现实性上是一切社会关系的总和，自然属性不能决定人的本质，这一项与唯物史观相反。","D":"社会发展的根本动力是社会基本矛盾，物质欲望只是观念形态的动因，不能充当根本动力。"},"memoryTip":"“民以食为天”考的是“生产是前提”，不是“欲望是动力”，两者必须分开。"},"20290":{"solution":"三种奴隶处在同样的奴隶制社会存在中，思想意识却相差极大，说明社会意识并不总与社会存在完全同步、完全对应，这正是社会意识相对独立性中与社会存在发展不平衡的表现。","optionAnalysis":{"A":"社会意识归根到底都是社会存在的反映，差别只在于反映的深浅正误，说有的意识不是存在的反映，违背唯物史观。","B":"相同的社会存在可以产生不同的社会意识，说明二者存在不一致性，正是这三种意识差异的根本原因。","C":"题干比较的是同一种社会意识形式内部的差别，并未涉及哲学、道德、艺术等不同形式之间的相互作用。","D":"历史继承性解释的是不同时代之间思想成果的传承，而三种奴隶处于同一时代背景下，用它说明不了差异。"},"memoryTip":"同处境、不同觉悟，就是这个“不一致性”；相对独立性的关键词是“不同步”。"},"20291":{"solution":"题干把文化的“力”规定为“化”自身，指向文化对人的作用。文化通过价值观念、知识体系和行为规范的熏陶，培育人、塑造人，这就是以文化人的功能。","optionAnalysis":{"A":"文化之“力”用以“化”自身，说的是文化对人的教化和塑造，与培育塑造人的功能完全对应。","B":"人的本质在其现实性上是一切社会关系的总和，文化影响人但不“构造”人的本质，这一说法夸大了文化的作用。","C":"社会发展的主导力量是物质生产，文化具有重要作用但不起主导和决定作用。","D":"历史进步的源泉是物质生产实践，文化是其在观念上的反映和条件，不能称为源泉。"},"memoryTip":"抓“化自身”三字，直接对应“以文化人”，其余选项都在拔高文化地位。"},"20292":{"solution":"马克思的原意是：判断变革时代不能以该时代的意识为根据，而要从物质生活的矛盾、从社会生产力与生产关系的现存冲突中去解释。因为生产力与生产关系的冲突是其他一切冲突的总根源。","optionAnalysis":{"A":"生产力与生产关系的现存冲突是物质生活矛盾的最深层内容，上层建筑领域的冲突归根到底由它派生，符合“根本上”的限定。","B":"经济基础与上层建筑的冲突是生产力与生产关系矛盾在上层领域的延伸和表现，层次上低于前者。","C":"人类社会与自然界的矛盾属于另一层关系，不是解释社会变革时代的直接依据。","D":"社会存在与社会意识的冲突是物质矛盾在观念上的反映，属于结果而非根源。"},"memoryTip":"层层往下挖：上层建筑冲突←经济基础冲突←生产力与生产关系的冲突，最底层才是答案。"},"20293":{"solution":"“以人民为中心”强调人民主体地位、为人民服务、把人民对美好生活的向往作为目标，其理论依据正是唯物史观关于人民群众是历史创造者的原理。","optionAnalysis":{"A":"人的本质是一切社会关系总和讲的是如何理解人，并未直接论证人民的历史主体地位，与题干的落点错位。","B":"人民群众是历史的创造者，是坚持人民主体地位、坚持以人民为中心最直接的理论基础，与题干完全对应。","C":"受历史条件制约讲的是群众活动的条件性，侧重限制而非主体地位，不能成为以人民为中心的依据。","D":"教材中并无这一规范原理表述，且其含义含混，不能准确支撑人民主体地位这一结论。"},"memoryTip":"“以人民为中心”对“人民是历史创造者”，一对一绑定，不要被“人的本质”干扰。"},"20294":{"solution":"旧唯物主义在自然领域坚持物质第一性，是唯物主义的；但一进入社会历史领域就把历史归于人的意识、英雄意志，滑向唯心主义。这种上、下半截不一致，故称“半截子”唯物主义。","optionAnalysis":{"A":"唯物论与辩证法相脱离是旧唯物主义的形而上学性，属于另一条局限，不解释“半截子”这一特定批评。","B":"形而上学唯物主义是对旧唯物主义性质的概括，与“半截子”所特指的历史观缺陷不是同一问题。","C":"自然观上唯物、历史观上唯心，正是“下半截唯物、上半截唯心”的形象说法，与题干因果吻合。","D":"不承认意识能动性是机械性的表现，属于旧唯物主义在意识观上的缺陷，仍不涉及历史观。"},"memoryTip":"“半截子”只指历史观没唯物：下半截（自然观）唯物，上半截（历史观）唯心。"},"20295":{"solution":"这句话强调历史不是脱离人的抽象过程，而是人追求自身目的的活动过程，人是历史的主体，历史是人自己创造的；但人创造历史又受客观规律和既定条件制约。","optionAnalysis":{"A":"唯物史观研究社会历史的出发点是物质生产和社会存在，而不是抽象的人，这一表述属于人本主义思路。","B":"历史由追求目的的人的活动构成，说明人们自己创造自己的历史，与题干引文意思一致。","C":"历史发展方向由客观规律决定，人只能在既定条件下选择，说方向由人自己决定夸大了主体作用。","D":"人的自我保存和发展不是历史原动力，物质生产才是社会发展的根本动力和决定力量。"},"memoryTip":"人是“剧作者”也是“剧中人”：自己创造历史，却不能任意选择历史方向。"},"20296":{"solution":"这段论述的两个要点是：不把成败简单归功或归咎于个人，不用今天的条件苛求前人。二者共同指向一个方法论要求——把历史人物放在特定历史条件下作具体、全面的考察和评价。","optionAnalysis":{"A":"人民群众是历史的创造者，个人作用从属于群众作用，说二者“同等重要”混淆了主次。","B":"任何人包括杰出人物都不能改变历史发展的基本方向，只能加速或延缓历史进程、影响其具体面貌。","C":"论述并未比较顺境与逆境中作用的大小，这一说法于理无据，也不是引文的主旨。","D":"从特定历史条件出发、全面辩证地评价历史人物，正是反对简单归因和苛求前人的方法论结论。"},"memoryTip":"评价历史人物两把尺子：放进当时的历史条件，看其全面功过，不苛求、不神化。"},"20297":{"solution":"社会形态是经济基础与上层建筑的统一体，其中经济基础即占统治地位的生产关系具有决定意义。五种社会形态的划分依据正是经济基础特别是生产关系的性质，即生产资料所有制的不同。","optionAnalysis":{"A":"生产工具的质量和数量是生产力水平的标志，可用来划分经济时代，但不能直接作为划分社会形态的依据。","B":"统治集团的阶级属性和政治属性由经济地位派生，是结果层面的特征，不能充当划分依据。","C":"经济基础特别是生产关系性质决定社会形态的性质，五种形态的区别正在于所有制形式不同，表述准确。","D":"社会交往和分工的范围与水平是社会发展的重要条件，但不能决定社会形态的根本性质。"},"memoryTip":"五种形态按“所有制”排队：原始公有→奴隶主私有→封建地主私有→资本家私有→公有制。"},"20298":{"solution":"“人不负青山，青山定不负人”讲的是人与自然相互成就：人善待自然，自然以良好生态回馈人。唯物史观认为，自然界作为劳动对象进入生产力，合理开发利用自然能够促进社会发展。","optionAnalysis":{"A":"人与自然具有统一性，但自然不能“自发”满足人的需要，必须通过人的劳动去改造和获取，“自发”二字不成立。","B":"劳动对象是生产力的基本要素，自然界作为劳动对象被合理开发利用，就能转化为现实的生产力，推动社会发展，与题意吻合。","C":"人具有能动性，不只是消极适应自然，这一说法否认了人的主体性和改造自然的能力。","D":"自然没有能动性，能动性是人特有的属性，说自然“能动补偿”把人与自然混为一谈。"},"memoryTip":"“青山”是劳动对象，属生产力要素；“能动”这个词只能给人，不能给自然。"},"20299":{"solution":"人们能以史为鉴，前提是历史不是偶然事件的杂乱堆积，而是有内在规律可循。正因为历史发展存在不以人的意志为转移的客观规律，相似条件下会重复出现相似趋势，经验才具有借鉴价值。","optionAnalysis":{"A":"历史规律与自然规律在客观性上有相似之处，但作用方式和表现形式根本不同，且“相似”本身不足以说明为何能汲取教训。","B":"历史发展存在不以人的意志为转移的客观规律，规律的可重复性使后人能够借鉴前人经验，正是题干的原因。","C":"历史发展是螺旋式上升、波浪式前进，不是循环往复，这一说法属于历史循环论。","D":"人类对历史规律的认识是不断深化的过程，说“已经完全掌握”既夸大又封闭了认识，且此项表述本身有误。"},"memoryTip":"可借鉴的是“规律”不是“事件”：历史会重演的是逻辑，不是情节。"},"20300":{"solution":"法律法规属于上层建筑中的政治法律制度和设施，是社会的思想关系层面。社会意识具有相对独立性，其发展变化与社会存在、与生产力的发展并不总是同步，可能超前也可能滞后，这就是不平衡性。","optionAnalysis":{"A":"法律既可能因滞后而阻碍新技术，也可能通过知识产权、成果转化等制度促进技术发展，“总是阻碍”以偏概全。","B":"法律不仅可以落后于技术，还可以通过前瞻性立法引导和规范技术发展，“只能落后”把可能性说成唯一性。","C":"法律的制定和修改与技术发展往往不同步，或滞后于新技术的出现，或超前作出规范，体现的正是社会意识相对独立性中的不平衡性。","D":"技术发展的内在动力来自技术自身的矛盾和生产实践的需要，法律是外部制度条件，不能成为内在动力。"},"memoryTip":"记“可滞后、可超前”五个字，凡出现“总是”“只能”的法律与技术关系判断，一律排除。"},"20301":{"solution":"题眼是“从根本上说”。唯物史观认为，生产力与生产关系的矛盾是生产方式内部最基础的矛盾，旧的生产关系容纳不下生产力发展时，变革时代就到来了，社会意识的变化也只有回到这一矛盾才能得到解释。","optionAnalysis":{"A":"生产力与生产关系的现存冲突位于生产方式内部，是社会变革最深的根源，与“从根本上说”这一限定完全吻合。","B":"经济基础与上层建筑的冲突由生产力与生产关系的矛盾派生，属于次一层级的矛盾，回答不了“根本”的追问。","C":"人类社会与自然界的矛盾是生产力发展的外部条件，不能解释社会形态更替和时代意识变更的内部根源。","D":"社会存在与社会意识的冲突本身就是有待解释的对象，用它去解释意识，等于用结果说明原因。"},"memoryTip":"两层矛盾分主次：生产力与生产关系在最底层，上层建筑那一层是派生出来的。"},"20302":{"solution":"题干问的是“理论基础”，落点应在人民的历史地位上。以人民为中心强调人民是历史的主体和力量源泉，其唯物史观依据正是人民群众是历史创造者的原理，其余选项虽同属唯物史观，但回答的是别的理论问题。","optionAnalysis":{"A":"总体的人在总体历史过程中的主体地位，是马克思早期关于人的解放的抽象表述，不是教材所指的直接理论依据。","B":"人的本质是一切社会关系总和，说明人不能脱离社会关系存在，指向人的社会性，支撑不了人民主体地位。","C":"人民群众活动受社会历史条件制约，强调的是一种限制关系，与“以人民为中心”的能动意涵方向相反。","D":"人民群众是历史的创造者，指明人民创造物质财富、精神财富并推动社会变革，正是以人民为中心的理论根基。"},"memoryTip":"见“以人民为中心”就锁定“人民是历史创造者”，别被人的本质、历史条件制约带走。"},"20303":{"solution":"社会意识相对独立性有若干表现：与社会存在发展的不完全同步、内部各形式相互影响、各有历史继承性，以及对存在能动的反作用。其中反作用是压轴的一条，因为它直接体现意识对存在的现实力量。","optionAnalysis":{"A":"不完全同步性说明意识可能超前或滞后于存在，只是发展节奏上的差异，属于相对独立性的次要表现。","B":"各种意识形式之间相互作用影响，属于意识内部的关系，尚未触及意识对存在的反作用这一根本。","C":"历史继承性说明意识有自身的发展线索，同样只是相对独立性的一个侧面。","D":"能动的反作用表现为先进意识促进社会发展、落后意识阻碍社会发展，是相对独立性最突出、最根本的表现。"},"memoryTip":"四项表现按“不同步、互影响、有继承、能反作用”记，压轴的“反作用”最突出。"},"20304":{"solution":"恩格斯曾概括马克思一生的两大发现：一是唯物史观，揭示社会发展的客观规律；二是剩余价值理论，揭开资本主义剥削的秘密。两者分别在历史观和政治经济学上实现了根本变革。","optionAnalysis":{"A":"唯物史观与剩余价值理论正是马克思的两大独创性贡献，与经典概括完全一致。","B":"劳动价值论由古典政治经济学提出，马克思是继承并发展，谈不上“开创”；辩证唯物主义也不在两大发现之列。","C":"辩证唯物主义是马克思主义哲学的基础内容，但两大发现中并无此项，组合仍然错位。","D":"把劳动价值论当作独创贡献不成立，它先于马克思而存在，虽配了历史唯物主义，整体仍错。"},"memoryTip":"两大发现记“史观＋剩余价值”：一个改造历史观，一个解剖资本主义。"},"20305":{"solution":"资本主义的产生和发展有科技、阶级斗争、工具革新等多种推动力量，但贯穿始终的基本动力是社会基本矛盾，即生产力与生产关系、经济基础与上层建筑的矛盾运动，其他力量都在这一矛盾基础上发挥作用。","optionAnalysis":{"A":"科技发展是重要的推动力量，但属于生产力要素的变化，不能取代社会基本矛盾这一总体动力。","B":"社会基本矛盾在资本主义条件下表现为生产社会化与私人占有的冲突，贯穿资本主义产生和发展全过程。","C":"被压迫阶级的斗争是阶级社会发展的直接动力，层次低于基本矛盾，不是“基本动力”。","D":"生产工具革新是生产力发展的标志和结果，是基本矛盾运动的具体体现，本身不构成基本动力。"},"memoryTip":"问“基本动力”一律给社会基本矛盾；问“直接动力”才轮到阶级斗争。"},"20306":{"solution":"商品经济是直接以交换为目的的经济形式，生产者生产产品不是为了自己消费，而是要通过交换让渡使用价值、取得价值。它与自给自足的自然经济正好相对。","optionAnalysis":{"A":"自给自足是自然经济的特征，与商品经济恰好相反，不是商品经济的定义。","B":"为他人生产只是现象，未点出“通过交换”这一关键，原始公社内部也有为他人生产却非商品生产。","C":"以交换为目的，准确揭示商品生产的目的在于交换价值，是商品经济的规定性表述。","D":"商品经济只存在于社会分工和不同所有者出现后的若干社会形态，并非一切社会都有。"},"memoryTip":"抓“交换”二字：为交换而生产是商品经济，自给自足是自然经济。"},"20307":{"solution":"商品经济产生和存在需要两个条件：一是社会分工，生产者各自生产不同产品，交换才有必要；二是生产资料和劳动产品属于不同所有者，交换才成为必须。二者缺一不可。","optionAnalysis":{"A":"自然经济与商品经济是对立的经济形式，它的存在不构成商品经济的条件。","B":"社会化大生产和资本主义私有制是商品经济高度发展阶段的背景，解释不了商品经济在奴隶社会、封建社会的存在。","C":"社会主义公有制下商品经济依然存在，可见公有制并非条件；社会化大生产也只是商品经济发展的结果。","D":"社会分工使交换成为必要，不同所有者使交换成为必然，正是商品经济存在的两个基本条件。"},"memoryTip":"两个条件记“分工＋不同所有者”：一个管必要性，一个管必然性。"},"20308":{"solution":"不同商品使用价值各异，在质上无法比较；它们能按一定比例交换，是因为都耗费了无差别的一般人类劳动，都具有价值，价值量由社会必要劳动时间决定，从而可以按量比较。","optionAnalysis":{"A":"使用价值性质不同恰恰使商品不能相互通约，是交换中必须被抽象掉的因素。","B":"具体劳动创造使用价值，各种具体劳动在质上不同，不能充当比较的尺度。","C":"都凝结了一般人类劳动即价值，价值在质上相同、在量上可比，构成交换比例的现实基础。","D":"共同效用仍停留在使用价值层面，不同商品的效用无法通约，决定不了交换比例。"},"memoryTip":"能按比例交换，一定是有“同质”的东西在背后——抽象劳动的凝结。"},"20309":{"solution":"这句话讲的是商品的内在矛盾：对所有者来说商品只是价值，要取得价值必须让渡使用价值；对购买者来说商品只是使用价值，要得到使用价值必须支付价值。使用价值与价值在同一主体身上不能兼得。","optionAnalysis":{"A":"商品是使用价值和价值的统一体，二者缺一就不成其为商品，“不可能既有”判断错误。","B":"所有者让渡使用价值才得到价值，购买者支付价值才得到使用价值，任何一方都不能同时占有二者。","C":"价值才是商品的社会属性和本质属性，使用价值只是商品的自然属性。","D":"使用价值与价值相互排斥、相互对立，一方实现以另一方让渡为条件，正是引文揭示的矛盾。"},"memoryTip":"“卖者不用、买者不付值”：同一个人不可能既留住使用价值又拿到价值。"},"20310":{"solution":"决定商品价值量的社会必要劳动时间以简单劳动为尺度，复杂劳动要按倍加或多倍的简单劳动折算。因此价值的计量单位是不需要专门训练的一般劳动。","optionAnalysis":{"A":"抽象劳动是形成价值的实体，说明价值的质的规定，但计量社会必要劳动时间要以简单劳动为单位。","B":"私人劳动是商品生产者的个别劳动，其社会性质还要通过交换才能实现，不能充当计量尺度。","C":"剩余劳动是超过必要劳动的那部分劳动，与价值量的计量尺度无关。","D":"简单劳动是一般劳动者不需专门训练即可从事的劳动，社会必要劳动时间正以它为尺度衡量。"},"memoryTip":"价值量用“简单劳动”当尺子，复杂劳动折算成倍加的简单劳动。"},"20311":{"solution":"小麦的滋味属于使用价值层面的自然属性，只表明它能满足人的食用需要，与由谁生产、在何种生产关系下生产没有关系。因此使用价值不反映生产关系的性质。","optionAnalysis":{"A":"使用价值由物品的自然属性决定，是贯穿各个时代的永恒范畴，不是历史范畴。","B":"使用价值只体现人与自然的关系，不体现人与人的生产关系，所以从滋味里看不出生产关系的性质。","C":"同一物品的使用价值由其物理、化学等自然属性决定，不随生产关系的变化而变化。","D":"有使用价值的物品未必是劳动产品，空气、阳光、野生果实都有使用价值却未经劳动加工。"},"memoryTip":"使用价值只管“有用没用”，看自然属性；生产关系只能从价值的生产过程中看出来。"},"20312":{"solution":"生产商品的劳动具有二重性：从具体形式看是具体劳动，创造使用价值；从耗费人类劳动力的角度看是抽象劳动，形成价值。二者不是先后两次劳动，而是同一劳动过程的两个方面。","optionAnalysis":{"A":"具体劳动和抽象劳动不是先后进行的两次劳动，而是同一次劳动的双重规定。","B":"同一商品只经过一个生产过程，不存在两个并行的劳动过程，表述错误。","C":"在同一生产过程中，具体劳动与抽象劳动同时存在，是同一劳动的两个方面，表述准确。","D":"把二重性说成不同过程中的两个方面，割裂了二者的同时性和同一性。"},"memoryTip":"二重性是“一次劳动、两副面孔”，不是两次劳动、两个过程。"},"20313":{"solution":"这句谚语讲的是物质财富即使用价值的源泉。使用价值由劳动和生产资料共同构成，劳动不是唯一源泉；而价值则只由劳动创造，土地等自然物并不创造价值，两种“源泉”不能混为一谈。","optionAnalysis":{"A":"价值源泉只有劳动，土地等自然物不创造价值，“劳动和土地是价值的源泉”混淆了财富源泉与价值源泉。","B":"土地同其他生产资料一样只转移自身旧价值，并不形成新价值。","C":"劳动是价值的唯一源泉，不是外部条件；把土地说成价值源泉属于要素价值论的错误。","D":"使用价值即物质财富由劳动和生产资料共同创造，劳动并非唯一源泉，正是引文要表达的财富源泉观。"},"memoryTip":"两句话分开记：财富源泉是劳动加生产资料，价值源泉只有劳动。"},"20314":{"solution":"全社会劳动生产率提高后，同一劳动时间内生产的使用价值数量增多，而凝结的价值总量不变，于是分摊到每件商品上的价值量减少。商品数量与单位价值量呈反向变动。","optionAnalysis":{"A":"劳动生产率提高会使商品数量增加而不是减少，前提判断已经错了。","B":"数量增加是对的，但单位商品价值量与劳动生产率成反比，不会保持不变。","C":"数量增加、单位价值量减少，符合劳动生产率与使用价值量成正比、与单位价值量成反比的规律。","D":"劳动生产率提高不会使商品数量减少，也不会使单位价值量增大，两个判断方向都相反。"},"memoryTip":"一升一降要配对：生产率升，数量升、单位价值降，价值总量不动。"},"20315":{"solution":"流通手段的特点是货币充当商品交换的媒介，一手交钱、一手交货，买卖同时完成。只有当期钱货两清的即时购买，才是货币在执行流通手段职能。","optionAnalysis":{"A":"顾客当即付款、当即取得苹果，货币充当了交换的媒介，是典型的流通手段。","B":"“10元可购买5斤”只是用货币衡量商品价值、表示价格，属于价值尺度职能。","C":"先取货、一周后付款，货币用于清偿已经发生的债务，属于支付手段。","D":"预定并约定单价，货币尚未现实地媒介交换，属于支付手段范畴而非流通手段。"},"memoryTip":"流通手段＝钱货同时两清；赊账、预付、还款、缴税都归支付手段。"},"20316":{"solution":"价格标签只是用货币为商品标出价格，也就是用货币衡量商品价值的大小。这里的货币是观念上的货币，不需要现实出场，执行的是价值尺度职能。","optionAnalysis":{"A":"流通手段要求货币现实地充当交换媒介，标签上的货币并未进入买卖过程。","B":"支付手段用于清偿债务、支付工资等单方面转移，标价不涉及任何债权债务关系。","C":"用货币衡量并表现商品价值，正是价值尺度职能，标签上的货币只是观念上的货币。","D":"作为社会财富的代表是贮藏手段的特征，需要现实的足值货币退出流通。"},"memoryTip":"只标价不成交是价值尺度，标价又当场成交才是流通手段。"},"20317":{"solution":"价值规律不是抽象地起作用，而是通过价格机制、供求机制和竞争机制这一整套市场机制来贯彻：价格随供求变动，竞争推动价格围绕价值波动并引导资源流向。","optionAnalysis":{"A":"生产者之间的竞争只是竞争机制的一个部分，单靠它无法涵盖价格与供求的联动。","B":"消费者之间的竞争同样只是市场机制的一个侧面，说明不了价值规律实现的完整途径。","C":"买卖双方的竞争仍停留在竞争机制之内，遗漏了价格机制和供求机制两个关键环节。","D":"价格、供求、竞争三大机制相互配合，构成价值规律发生作用的完整途径。"},"memoryTip":"三大机制串记“价、供、竞”，缺一个都说不全价值规律的实现方式。"},"20318":{"solution":"价值规律对生产、流通和消费的调节，是通过价格受供求影响围绕价值上下波动实现的。价格波动改变各市场主体的利益，从而引导其调整行为；波动是形式，围绕价值才是实质。","optionAnalysis":{"A":"社会必要劳动时间与个别劳动时间的矛盾是价值规律发挥作用的内在根据，不是调节作用的实现形式。","B":"使用价值与价值的矛盾说明商品的内在矛盾，不构成调节生产、流通、消费的具体形式。","C":"价格随供求围绕价值波动并影响市场主体利益，正是价值规律调节作用的实现形式。","D":"价格波动所围绕的轴心是价值而不是生产成本，这一选项把轴心弄错了。"},"memoryTip":"调节靠“价格绕价值转”，轴心是价值，不是成本，也不是供求本身。"},"20319":{"solution":"货币本身不会增殖，它能转化为资本，关键在于货币所有者买到了劳动力这一特殊商品。劳动力在使用中能创造出比自身价值更大的价值，货币增殖由此成为可能。","optionAnalysis":{"A":"私人劳动转化为社会劳动是商品经济基本矛盾的解决方式，与货币转化为资本的前提无关。","B":"生产资料私有制是资本主义所有制的特征，但只有私有制而没有劳动力买卖，货币仍不能成为资本。","C":"纸币代替金属货币只是货币形式的演变，不改变货币作为流通媒介的性质。","D":"劳动力成为商品，货币所有者才能买到能创造剩余价值的劳动力，这是货币转化为资本的前提。"},"memoryTip":"货币变资本，关键是买到“会下蛋”的劳动力，劳动力成为商品是总开关。"},"20320":{"solution":"劳动力商品的特殊性集中在其使用价值上：劳动力被使用即劳动的过程中，能创造出比自身价值更大的价值，成为价值和剩余价值的源泉，这是它区别于其他商品的最重要特征。","optionAnalysis":{"A":"使用价值是价值和剩余价值的源泉，正是劳动力商品最根本的特殊性，与题干“最重要特征”吻合。","B":"普通商品使用价值消失时价值也随之消失或转移，这并非劳动力商品独有的特点。","C":"价值决定包含历史和道德因素确实是劳动力商品价值的特点，但重要性不及使用价值的特殊性。","D":"这是劳动力成为商品的地位和作用，回答的是货币转化为资本的前提，不是劳动力商品自身的特征。"},"memoryTip":"劳动力商品的“独门绝技”是使用能生出更多价值，其余特点都是配角。"},"20321":{"solution":"资本主义生产不止于制造使用价值，更在于生产剩余价值。一方面它是创造使用价值的劳动过程，另一方面它又是价值增殖过程，二者是同一生产过程的两个方面。","optionAnalysis":{"A":"生产过程和流通过程的统一讲的是资本循环，不是资本主义生产过程本身的二重规定。","B":"简单再生产与扩大再生产是按规模划分的再生产类型，与生产过程的性质规定无关。","C":"劳动过程与价值形成过程的统一是简单商品生产过程的特征，缺少增殖这一资本主义特质。","D":"劳动过程与价值增殖过程的统一，准确揭示资本主义生产既要造使用价值又要生产剩余价值的本质。"},"memoryTip":"资本主义＝劳动过程＋价值增殖过程；价值形成过程只属于简单商品生产。"},"20322":{"solution":"价值形成过程只补偿生产资料转移的旧价值和劳动力价值。当劳动时间超过这一补偿点后，新创造的价值超出预付资本价值，价值形成过程就转化为价值增殖过程。","optionAnalysis":{"A":"劳动过程是生产使用价值的过程，只是价值增殖过程的物质基础，不能与之等同。","B":"价值形成过程只到补偿预付资本价值为止，尚未产出剩余价值，用它定义增殖过程范围过窄。","C":"超过一定点的价值形成过程就是价值增殖过程，“一定点”指补偿劳动力价值所需的时间点。","D":"生产资料转移价值只是价值形成的一个环节，涵盖不了增殖过程。"},"memoryTip":"抓住“一定点”：补偿劳动力价值那一点之后的劳动时间，才凝结成剩余价值。"},"20323":{"solution":"剩余价值由可变资本带来，剩余价值率等于剩余价值与可变资本之比，反映的是资本家对工人的剥削程度，也就是可变资本的价值增殖程度。","optionAnalysis":{"A":"预付资本的价值增殖程度由利润率表示，利润率恰恰掩盖了真实的剥削程度。","B":"可变资本用于购买劳动力并能带来剩余价值，剩余价值率反映的正是它的增殖程度。","C":"固定资本属于不变资本的组成部分，只转移旧价值，不产生任何增殖。","D":"不变资本只是转移价值，不创造剩余价值，谈不上增殖程度。"},"memoryTip":"剩余价值率配可变资本，利润率配预付资本，两把尺子别拿错。"},"20324":{"solution":"绝对剩余价值生产是在必要劳动时间不变的条件下，通过延长工作日或提高劳动强度来增加剩余劳动时间。必要劳动时间保持不变，是这种方法能够成立的前提。","optionAnalysis":{"A":"剩余劳动时间若不变，剩余价值量就不会增加，与延长工作日的目的正好相悖。","B":"必要劳动时间保持不变，工作日延长所增加的时间全部成为剩余劳动时间，正是绝对剩余价值生产的前提。","C":"工作日长度不变是相对剩余价值生产的前提条件，与绝对剩余价值生产的做法相反。","D":"无偿劳动时间即剩余劳动时间，若它保持不变，剩余价值就无从增加。"},"memoryTip":"绝对延长看工作日、必要劳动不变；相对缩短看工作日不变、必要劳动缩短。"},"20325":{"solution":"相对剩余价值以全社会劳动生产率提高为前提：各部门生产率普遍提高使生活资料价值下降，劳动力价值随之降低，必要劳动时间缩短，剩余劳动时间相应延长。个别企业提高生产率得到的是超额剩余价值。","optionAnalysis":{"A":"个别企业提高劳动生产率，获得的是超额剩余价值，改变不了社会范围的必要劳动时间。","B":"单个部门提高劳动生产率只降低本部门产品价值，不足以普遍降低劳动力价值。","C":"整个社会劳动生产率提高，劳动力价值下降、必要劳动时间缩短，才是相对剩余价值的来源。","D":"个别企业生产率高于部门平均，获得超额剩余价值，这是相对剩余价值生产的自发机制而非结果本身。"},"memoryTip":"个别企业得超额，全社会普及才落成相对剩余价值。"},"20326":{"solution":"资本主义再生产的特征是扩大再生产。资本家为追逐更多剩余价值必须不断积累，而竞争的外部压力又迫使其扩大规模，内在动力与外部压力共同决定了扩大再生产的必然性。","optionAnalysis":{"A":"资本有机构成提高是资本积累的结果和伴随现象，不是扩大再生产的决定因素。","B":"追逐剩余价值的内在动力加上竞争的外部压力，构成资本主义扩大再生产的决定机制。","C":"资本周转速度加快影响年剩余价值量，但不决定再生产采取扩大还是简单的形式。","D":"剩余价值率提高意味着剥削程度加深，为积累提供更多源泉，却不是扩大再生产的根本动力。"},"memoryTip":"两台发动机：内在的贪欲＋外在的竞争，一起推动扩大再生产。"},"20327":{"solution":"资本积累是把剩余价值转化为资本。其实质在于资本家凭借无偿占有的剩余价值扩大生产规模，进而占有更多的剩余价值，也就是用榨取来的剩余价值去榨取更多剩余价值。","optionAnalysis":{"A":"用榨取的剩余价值来榨取更多剩余价值，揭示了资本积累的剥削实质，表述准确。","B":"增加社会资本总量只是资本积累的结果和现象，没有揭示其社会实质。","C":"扩大生产规模、增强竞争能力是积累的手段和外在表现，不是实质。","D":"推动社会进步是资本积累的客观后果，与揭示其实质不是同一层次的问题。"},"memoryTip":"积累的实质是“拿抢来的再去抢”，落脚点始终是剩余价值的再占有。"},"20328":{"solution":"资本积累把剩余价值转化为资本，使生产在扩大的规模上重复进行。因此资本积累是资本主义扩大再生产的源泉，而扩大再生产是资本积累的表现和结果，二者方向不能颠倒。","optionAnalysis":{"A":"关系被颠倒了。扩大再生产以资本积累为源泉，而不是积累以扩大再生产为源泉。","B":"剩余价值资本化形成追加资本，才使生产规模得以扩大，故积累是扩大再生产的源泉。","C":"剩余价值转化为资本是资本积累的定义内容，并没有回答积累与扩大再生产的关系。","D":"二者存在内在因果关系，积累正是扩大再生产的源泉，“无内在关系”的说法完全错误。"},"memoryTip":"箭头只朝一个方向：积累是源泉，扩大再生产是结果。"},"20329":{"solution":"资本有机构成是生产资料与劳动力之比，用不变资本与可变资本的比例表示。有机构成提高意味着总资本中不变资本占比上升、可变资本占比相对下降，反映技术进步与劳动生产率提高。","optionAnalysis":{"A":"有机构成提高的直接表现就是不变资本比重增加、可变资本比重相对减少，表述正确。","B":"二者按相同比例扩大，比例本身不变，属于有机构成不变的典型情形。","C":"有机构成提高时可变资本的比重是相对下降而不是增大，方向相反。","D":"按相同比例下降同样保持比例不变，而且资本总量通常不会同时下降。"},"memoryTip":"有机构成提高＝机器设备那头加重，人工那头变轻。"},"20330":{"solution":"增大个别资本有两条途径。资本积聚依靠剩余价值资本化，靠单个资本自身积累滚雪球式扩大；资本集中则通过吞并、联合、组建股份公司把现有资本合并。题干问积聚，答案只能是剩余价值的资本化。","optionAnalysis":{"A":"大资本吞并小资本属于资本集中，只改变现有资本的组合，不增加社会资本总额。","B":"许多中小资本联合同样是资本集中，与个别资本依靠自身积累扩大无关。","C":"组织股份公司把分散资本合并使用，是资本集中的典型方式。","D":"剩余价值的资本化就是资本积累，由积累实现的个别资本增大即资本积聚，表述正确。"},"memoryTip":"自己攒叫积聚，合起来叫集中；积聚的原料是剩余价值。"},"20331":{"solution":"股份制把社会上分散的资本合并为大资本，原有资本所有权并未消失，只是支配权集中，社会资本总额不增加。这正是资本集中区别于资本积聚的根本标志。","optionAnalysis":{"A":"资本积累是剩余价值资本化，靠自身积累逐步扩大，与股份制合并存量资本不同。","B":"资本积聚以资本积累为基础，靠单个资本自身增大，不涉及把他人资本合并过来。","C":"股份制实现现有资本的合并与支配权集中，社会资本总量不变，属于资本集中。","D":"垄断指生产集中发展到一定阶段的状态，不是资本增大的方式分类，与题干的划分不对应。"},"memoryTip":"判断标准看社会资本总额：增加是积聚，不增加只是合并就是集中。"},"20332":{"solution":"研究资本运动的角度各不相同。资本循环着眼于产业资本依次经过三个阶段、采取三种职能形式又回到出发点的连续过程；资本周转研究速度快慢；社会资本再生产研究实现条件。","optionAnalysis":{"A":"资本循环考察资本从货币资本出发再回到货币资本的连续运动，着眼点正是运动的连续性。","B":"速度方面是资本周转的研究对象，与循环的考察角度不同。","C":"实现条件方面属于社会资本再生产的核心内容，不是资本循环的角度。","D":"矛盾性不是资本循环的特定研究角度，循环重在阶段更替与职能形式并存的连续性。"},"memoryTip":"循环看“连不连”，周转看“快不快”，社会资本看“卖得掉、买得回”。"},"20333":{"solution":"产业资本循环的第一阶段是购买阶段，货币资本的职能是购买生产资料和劳动力，为剩余价值生产准备好物的和人的条件。它本身不生产剩余价值，只是为生产创造条件。","optionAnalysis":{"A":"生产剩余价值是生产资本的职能，发生在第二阶段生产过程。","B":"实现剩余价值是商品资本的职能，发生在第三阶段售卖过程。","C":"货币只购买生产要素，剩余价值在生产中产生，货币本身不会直接带来剩余价值。","D":"购买劳动力和生产资料、为剩余价值生产准备条件，正是货币资本的职能。"},"memoryTip":"三段三职能：买（备条件）—产（造剩余）—卖（实现剩余）。"},"20334":{"solution":"商品资本处在循环的第三阶段，职能是把包含剩余价值的商品卖出去，实现商品的价值和剩余价值，使资本以货币形式回流，为下一轮循环做准备。","optionAnalysis":{"A":"生产剩余价值是生产资本的职能，商品资本已不再进入直接生产过程。","B":"通过销售使凝结在商品中的价值和剩余价值得到实现，正是商品资本的职能。","C":"为剩余价值生产准备条件是货币资本的职能，阶段和内容都不符。","D":"“为实现剩余价值准备条件”表述混乱，商品资本承担的是实现本身，而非准备。"},"memoryTip":"商品资本的活儿只有一件：把货卖出去，让剩余价值变现。"},"20335":{"solution":"社会总产品的实现即补偿，包含实物补偿和价值补偿两个方面：产品要在实物形式上得到替换，在价值上得到实现，二者同时完成，社会资本再生产才能顺利进行。","optionAnalysis":{"A":"实物和价值两个方面的补偿，是社会总产品实现的经典表述，与题意吻合。","B":"使用价值和价值是商品二因素的一般说法，没有落到再生产中的补偿关系上。","C":"可变资本与不变资本是资本构成的划分，不是社会总产品实现的方面。","D":"价值与剩余价值只是产品价值构成内部的部分关系，不能充当实现的两个方面。"},"memoryTip":"总产品实现要过两道关：东西换得回来是实物补偿，钱收得回来是价值补偿。"},"20336":{"solution":"马克思按社会总产品的最终用途，把社会生产分为两大部类：生产生产资料的部类和生产消费资料的部类。这一划分是分析社会资本再生产的理论前提。","optionAnalysis":{"A":"以社会总产品的最终用途，即用于生产消费还是个人消费为依据划分两大部类，表述准确。","B":"生产规模大小划分的是简单再生产与扩大再生产，不是两大部类。","C":"不变资本与可变资本的划分依据是资本在剩余价值生产中的作用，与部类划分无关。","D":"固定资本与流动资本的划分依据是价值周转方式，属于资本周转范围的划分。"},"memoryTip":"两部类看用途：造机器设备的归第Ⅰ部类，造消费品的归第Ⅱ部类。"},"20337":{"solution":"社会资本再生产的核心问题是社会总产品的实现问题，即产品能否卖出去、所需生产资料和消费资料能否买回来，实物补偿与价值补偿能否顺利完成。","optionAnalysis":{"A":"两大部类的划分是分析再生产的理论前提，本身并不构成核心问题。","B":"价值构成（不变资本、可变资本、剩余价值）只是分析补偿关系的工具，不是核心问题本身。","C":"生产资料优先增长是扩大再生产的客观要求，属于规律性结论而非核心问题。","D":"社会总产品能否在价值和实物上得到补偿即实现，直接决定再生产能否继续，是核心问题。"},"memoryTip":"核心就一个词——实现：卖得出、买得回，缺一环再生产就断。"},"20338":{"solution":"资本主义工资的实质是劳动力价值或价格的转化形式，但它在现象上表现为劳动的价格，好像全部劳动都得到了报酬，必要劳动与剩余劳动的界限被抹掉，剥削因此被掩盖。","optionAnalysis":{"A":"工资以“劳动的价格”的外观出现，使全部劳动看似都有偿，这是它掩盖剥削的直接原因。","B":"工资实质是劳动力价值，这是被掩盖的内容，本身说明不了掩盖的机制。","C":"工资相当于必要劳动创造的价值，这一实质恰恰被工资形式遮蔽。","D":"这是工资的实质规定，属于科学揭示的结论，与“为何能掩盖”不是同一问题。"},"memoryTip":"工资的障眼法在“看着像劳动的报酬”，实质却是劳动力的价钱。"},"20339":{"solution":"平均利润率是部门之间竞争的结果：资本为追逐高利润率在各部门间自由转移，使各部门利润率趋于平均，形成一般利润率。部门内部竞争则形成社会价值和超额剩余价值。","optionAnalysis":{"A":"不同部门资本为争夺有利投资场所而转移，使利润率趋于平均，是平均利润率形成的直接原因。","B":"部门内部竞争决定商品的社会必要劳动时间和超额剩余价值，不会使利润率平均化。","C":"生产者与购买者之间的竞争影响价格水平，与利润率平均化的机制不同。","D":"购买者之间的竞争只影响需求和价格，不构成平均利润率的形成机制。"},"memoryTip":"平均利润率靠“跨部门搬家”：部门间竞争拉平，部门内竞争拉出差距。"},"20340":{"solution":"资本主义经济危机的实质是生产相对过剩，即相对于劳动人民有支付能力的需求而言商品过剩，而不是社会财富的绝对过剩。大量产品卖不出去只是危机的现象表现。","optionAnalysis":{"A":"危机中劳动者的大量需求仍得不到满足，并非绝对过剩，“生产绝对过剩”判断错误。","B":"产品超过的是有支付能力的需求，而非人们的一般需要，这一表述丢掉了“相对”这个关键词。","C":"大量产品卖不出去是危机的现象表现，不是危机的实质。","D":"生产相对过剩，即相对于有支付能力需求的过剩，准确揭示资本主义经济危机的实质。"},"memoryTip":"咬住“相对”二字：不是东西太多了，是穷人买不起。"},"20341":{"solution":"资本主义基本矛盾是生产社会化与生产资料资本主义私人占有之间的矛盾。它贯穿资本主义始终，决定并派生其他各种矛盾，是资本主义一切冲突的总根源。","optionAnalysis":{"A":"无产阶级与资产阶级的矛盾是基本矛盾在阶级关系上的表现，不是基本矛盾本身。","B":"生产无限扩大趋势与有支付能力需求相对缩小的矛盾，是基本矛盾在再生产中的具体表现。","C":"个别企业生产有组织性与整个社会生产无政府状态的矛盾，同样是基本矛盾的表现形式。","D":"生产社会化要求社会共同占有生产资料，而生产资料却被资本家私人占有，这一矛盾才是基本矛盾。"},"memoryTip":"基本矛盾只有一个公式：社会化生产对私人占有，其余都是它的表现。"},"20342":{"solution":"“两个必然”的依据在于资本主义基本矛盾的不可调和：生产社会化与私人占有制的冲突在资本主义制度框架内无法根本解决，只能通过社会主义代替资本主义来解决。","optionAnalysis":{"A":"政治经济发展不平衡是“一国或数国首先胜利”的现实依据，不是“两个必然”的理论依据。","B":"生产社会化与资本主义私人占有的矛盾不可调和，决定了资本主义的历史暂时性，是主要依据。","C":"个别企业有组织性与社会生产无政府状态的矛盾只是基本矛盾的表现，层次较低。","D":"阶级矛盾尖锐化是基本矛盾的表现和结果，不能充当根本依据。"},"memoryTip":"问“必然”找基本矛盾，问“一国胜利”才找政治经济发展不平衡。"},"20343":{"solution":"社会主义代替资本主义，从社会发展规律看，是生产关系一定要适合生产力状况规律作用的结果：资本主义私有制已容纳不下社会化大生产的要求，必然被新的生产关系所取代。","optionAnalysis":{"A":"资本主义固有矛盾无法解决是具体原因，未上升到规律层面，表述不够根本。","B":"生产关系必须适应生产力发展要求，是社会主义代替资本主义的一般规律依据，表述准确。","C":"生产与需求的矛盾不是社会形态更替的根本规律，无法解释制度替代。","D":"阶级矛盾是基本矛盾的表现，不能充当制度更替的规律依据。"},"memoryTip":"制度更替的总答案永远是“生产关系要适合生产力”，其余都是表现。"},"20344":{"solution":"价值的物质承担者是使用价值，即商品能够满足人们某种需要的有用性或效用。移动电话的各种功能只是有用性的具体体现，真正承担其价值的是使用价值本身。","optionAnalysis":{"A":"各种功能只是使用价值的具体表现形式，范围偏窄，不能等同于作为价值承担者的使用价值。","B":"对消费者的效用或有用性就是使用价值，它构成价值的物质承担者，与题意吻合。","C":"货币是价值的表现形式，不是价值的物质承担者，方向完全错位。","D":"软件只是产品的组成部分，其价值同样要靠使用价值来承担，回答不了本题。"},"memoryTip":"价值只能“挂”在使用价值上：没有用处的东西卖不出价钱。"},"20345":{"solution":"商品具有二因素：使用价值是自然属性，反映人与自然的关系；价值是社会属性，反映商品生产者之间交换劳动的社会关系，是商品的本质属性。","optionAnalysis":{"A":"使用价值由物品的自然属性决定，是商品的自然属性，不是社会属性。","B":"交换价值是价值的表现形式，只是现象层面的规定，不是社会属性的本体。","C":"价值体现商品生产者之间交换劳动的社会关系，是商品的社会属性，表述正确。","D":"使用价值与价值并列，其中只有价值才是社会属性，不能一并称为社会属性。"},"memoryTip":"自然属性看使用价值，社会属性看价值，交换价值只是价值的“外衣”。"},"20346":{"solution":"交换价值表现为两种使用价值相交换的量的比例。这种比例之所以能确定，是因为不同商品都凝结了无差别的人类劳动即价值，价值是交换价值的基础，交换价值是价值的表现形式。","optionAnalysis":{"A":"商品是使用价值与价值的统一体，是交换的承担者，不能充当交换比例的基础。","B":"货币是价值的表现形式，是交换长期发展的产物，不是交换价值的内容。","C":"使用价值是交换价值的物质承担者，性质各异无法通约，不能作为基础。","D":"价值是交换价值的基础和内容，交换价值随价值变动而变动，表述正确。"},"memoryTip":"价值是里、交换价值是表，里决定表；货币只是表进一步外化的形式。"},"20347":{"solution":"劳动二重性决定了价值转移与价值创造的分工：具体劳动创造使用价值，同时把生产资料的旧价值转移到新产品中；抽象劳动则创造新价值。生产资料的价值只能被转移，绝不可能增殖。","optionAnalysis":{"A":"具体劳动只转移旧价值，不会使生产资料的价值增殖，“增殖”一词用错。","B":"具体劳动在创造使用价值的同时，把生产资料的旧价值转移到新产品中，表述正确。","C":"抽象劳动创造新价值，不负责转移生产资料价值，更不会使其增殖。","D":"抽象劳动形成的是新价值而非转移旧价值，概念搭配错误。"},"memoryTip":"具体劳动管“搬家”转移旧价值，抽象劳动管“生子”创造新价值。"},"20348":{"solution":"社会必要劳动时间指在现有社会正常生产条件下、社会平均的劳动熟练程度和强度下生产某种使用价值所需的时间。其中“正常生产条件”指某一生产部门内大多数产品已经达到的技术装备水平。","optionAnalysis":{"A":"社会必要劳动时间以部门为比较范围，跨部门的全社会平均技术装备水平与之无关。","B":"先进技术装备水平对应的是个别劳动时间较低的先进企业，不是社会正常生产条件。","C":"部门内部大多数产品已经达到的技术装备水平，正是“正常的生产条件”的含义。","D":"以全社会大多数部门为范围扩大了界限，社会必要劳动时间只在同一部门内部比较。"},"memoryTip":"“正常条件”取部门内占多数、大多数企业已达到的水平，既不取先进也不取全社会。"},"20349":{"solution":"劳动生产率是具体劳动的生产效率，它的变化只影响单位时间生产的使用价值数量，不改变同一时间凝结的价值总量。因此同一社会必要劳动时间创造的价值不变，变化的是单位商品的价值量。","optionAnalysis":{"A":"劳动生产率提高使使用价值数量增加，但同一劳动时间内凝结的价值总量并不增加。","B":"同一社会必要劳动时间对应的劳动量固定，创造的价值总量不会因生产率提高而减少。","C":"价值由抽象劳动量决定，同一社会必要劳动时间创造的价值量恒定不变，表述正确。","D":"“提高”意味着价值量增加，与价值总量不变相矛盾，实际变化的是使用价值数量。"},"memoryTip":"生产率只改“东西多少”，不改“价值多少”；单位价值量才与它成反比。"},"20350":{"solution":"剩余价值在生产领域由雇佣工人的剩余劳动创造，但它的产生离不开流通：必须在流通中买到劳动力，并在流通中卖出商品实现价值。所以剩余价值不在流通中产生，却不能离开流通。","optionAnalysis":{"A":"剩余价值在生产中创造、在流通中实现，“不能离开流通”强调的正是流通的条件性，表述准确。","B":"流通只实现价值而不创造价值，把产生地点说成流通领域，主次颠倒。","C":"离开流通，既买不到劳动力也卖不出商品，剩余价值无从产生和实现，“无关”说法错误。","D":"流通中通行等价交换，本身不产生剩余价值，“又在流通中产生”判断错误。"},"memoryTip":"一句口诀：生产里生、流通里活——生在生产，离不开流通。"},"20351":{"solution":"题眼是“都是依靠”，要求找出绝对剩余价值与相对剩余价值的共同点。前者延长工作日，后者在工作日不变时缩短必要劳动时间，做法不同，但最终都使剩余劳动时间延长、剩余价值增多。","optionAnalysis":{"A":"延长工作日只是绝对剩余价值的获取方式，相对剩余价值恰恰以工作日不变为前提，A无法覆盖两种方式。","B":"压低工资属于对劳动力价值的侵占，不是教材划分两种剩余价值生产方法的依据，也说明不了相对剩余价值如何形成。","C":"两种方法路径不同，结果却一致：剩余劳动时间延长、必要劳动时间相对缩短，这正是二者的共同点。","D":"提高劳动生产率只是相对剩余价值的实现途径，绝对剩余价值靠延长劳动时间，并不依赖生产率提高。"},"memoryTip":"延长工时得绝对，缩短必要劳动得相对，二者殊途同归到“剩余劳动时间变长”。"},"20352":{"solution":"资本构成分三个层次，题干问“由生产技术水平决定”，指向实物形态的比例。生产资料与劳动力的比例随技术装备水平变动，是技术构成；用价值表现才是不变资本与可变资本之比。","optionAnalysis":{"A":"固定资本与流动资本是按价值周转方式划分的，回答的是资本周转速度快慢问题，与技术构成无关。","B":"固定资本只是生产资料的一部分，与劳动力对比既不是技术构成的规范表述，也不是价值构成，概念被拼凑。","C":"不变资本与可变资本的比例是资本价值构成，它由技术构成决定并反映其变化，本身不是技术构成。","D":"生产资料与劳动力的比例直接由生产技术装备水平决定，是资本技术构成的准确定义。"},"memoryTip":"技术构成看实物（生产资料比劳动力），价值构成看货币（c比v），有机构成是二者的统一。"},"20353":{"solution":"平均利润产生于部门之间的竞争，是不同部门利润率平均化的结果。它以部门预付资本为基数、按平均利润率计算，因此主体必须落在“生产部门”而不是单个企业。","optionAnalysis":{"A":"以部门预付资本为基数、按平均利润率计算，把主体和计算口径都摆正了，与平均利润的定义吻合。","B":"把“生产部门”换成“企业”就错了，同一部门内各企业生产条件不同，实际利润率并不相等。","C":"职能资本与非职能资本之间是利润分割，即企业利润与利息的划分，与平均利润率的形成是两回事。","D":"利润来自生产过程中工人创造的剩余价值，说从流通领域获得，违背劳动价值论。"},"memoryTip":"平均利润的题眼是“部门”：按部门预付资本分配，不按单个企业算。"},"20354":{"solution":"划分经济形态看产品是否用于交换：自给自足的是自然经济，为交换而生产的是商品经济。二者是人类社会迄今仅有的两种基本形态，市场经济只是商品经济成熟后的产物。","optionAnalysis":{"A":"市场经济是商品经济高度发展、市场机制起基础性作用时的经济体制，被商品经济所包含，不能与之并列。","B":"计划经济是资源配置方式，属于体制层面，与自然经济不在同一个划分标准上。","C":"按产品是否用于交换划分，自然经济与商品经济构成两种基本形态，表述准确。","D":"商品经济讲交换形式，计划经济讲资源配置方式，两者标准不同，不能并列。"},"memoryTip":"看产品去向：自己用是自然经济，拿去换是商品经济；市场经济只是商品经济的成熟阶段。"},"20355":{"solution":"改进技术提高的是本企业的个别劳动生产率，使个别价值低于社会价值，按社会价值出售便可多得一份超额剩余价值，这正是资本家改进技术的直接动因。普遍模仿之后才形成相对剩余价值。","optionAnalysis":{"A":"劳动力价值下降是全社会劳动生产率普遍提高后的结果，属于相对剩余价值生产的后果，不是改进技术的动机。","B":"率先改进技术能压低个别价值、按社会价值出售而多获一份剩余价值，直接动因正在于此。","C":"绝对剩余价值靠延长工作日和加强劳动强度取得，与改进技术没有直接关联。","D":"相对剩余价值是各部门普遍提高劳动生产率的产物，是追逐超额剩余价值带来的社会结果。"},"memoryTip":"直接动因是超额剩余价值，相对剩余价值是大家跟风之后形成的“集体结果”。"},"20356":{"solution":"引文强调追加资本的每一个价值原子都来自他人的无酬劳动，即来自剩余价值。这说明资本积累的唯一源泉是工人创造的剩余价值，而资本积累又构成扩大再生产的基础。","optionAnalysis":{"A":"资本积累确是扩大再生产的源泉，但引文追问的是追加资本从何而来，A答的是积累与再生产的关系，方向错位。","B":"无酬劳动就是剩余价值，追加资本全部由它转化而来，说明剩余价值是资本积累的唯一源泉。","C":"资本积累为扩大再生产提供追加资本，但积累并不等于扩大再生产，C把手段与过程混为一谈。","D":"追加资本正是扩大再生产的物质前提，D否认二者联系，与引文意思相反。"},"memoryTip":"链条记牢：剩余价值变资本积累，积累再支撑扩大再生产，引文问源头只能答剩余价值。"},"20357":{"solution":"商品按社会必要劳动时间决定的价值出售，个别劳动时间越低，个别价值就越低于社会价值，差额就是超额收益。所以生产者都力图使个别劳动时间小于社会必要劳动时间。","optionAnalysis":{"A":"个别劳动时间达社会必要劳动时间的多倍，个别价值远高于社会价值，按社会价值出售必然亏本。","B":"二者相等只能按价值出售、获得正常收益，得不到额外好处，体现不了“更多收益”。","C":"个别劳动时间大于社会必要劳动时间，意味着劳动耗费高于社会平均，处于竞争劣势。","D":"个别劳动时间低于社会必要劳动时间，个别价值低于社会价值，按社会价值出售即可多得收益。"},"memoryTip":"“个别低于社会”才赚钱，差额就是超额收益；个别高于社会则必亏。"},"20358":{"solution":"价值尺度是用自身价值去衡量其他商品的价值。货币首先是商品，凝结着一般人类劳动、本身有价值，才能充当衡量他人价值的尺度，这是它能够执行该职能的根本原因。","optionAnalysis":{"A":"能衡量其他商品价值的大小，就是价值尺度职能本身的表现，属于同义反复，没有回答“为什么能”。","B":"货币作为社会劳动的产物自身具有价值，才能以自身价值为尺度去衡量其他商品，这是根本原因。","C":"具有计量单位是价格标准的技术规定，是价值尺度落到具体操作上的条件，不是其可能性的根据。","D":"执行价值尺度时可用观念上的货币，这是该职能的特点，由货币本身有价值派生而来，属结果不是原因。"},"memoryTip":"有价才能量价：货币因自身凝结劳动才有资格当尺度，观念货币只是执行方式。"},"20359":{"solution":"资本积聚靠剩余价值资本化，受社会财富增长速度限制；资本集中则是既有资本的合并，凭借竞争和信用尤其是股份公司和银行信用在短时间完成，故集中方式是竞争和信用。","optionAnalysis":{"A":"资本积聚与资本积累是同一过程的两面，积累指剩余价值资本化，积聚指由此带来的资本增大，都不是集中方式。","B":"剩余价值资本化属于资本积聚，竞争只是推动集中的外部压力，此项把积聚与集中搅在一起。","C":"竞争迫使资本联合，信用通过股份公司和银行把闲散资本汇集起来，二者是资本集中的两个有力杠杆。","D":"简单再生产与扩大再生产是再生产类型的划分，与资本集中的实现方式无关。"},"memoryTip":"积聚靠“攒”（剩余价值资本化），集中靠“合”（竞争加信用、股份公司）。"},"20360":{"solution":"部门之间竞争的手段是资本自由转移：利润率低的部门资本流出、高的部门资本流入，结果各部门利润率趋于平均。其实质是全体资本家按资本比例重新瓜分工人创造的剩余价值。","optionAnalysis":{"A":"“超额使用价值”不是马克思主义政治经济学的规范概念，使用价值本身也不存在超额问题。","B":"资本在部门间转移使利润率平均化，等量资本取得等量利润，实质就是各部门资本家重新瓜分剩余价值。","C":"促进技术进步和有机构成提高是部门内部追逐超额利润的后果，且属于作用而非实质。","D":"获得超额利润是部门内部先进企业竞争的目标；部门之间竞争的结果是平均利润。"},"memoryTip":"部门内部争超额，部门之间争平均，后者的实质是重新瓜分剩余价值。"},"20361":{"solution":"劳动力商品的使用价值在于能创造价值，且创造的价值大于自身价值。生产中新创造的价值分为补偿劳动力价值的必要劳动部分和剩余价值两部分，故为二者之和。","optionAnalysis":{"A":"商品价值还包括生产中转移的生产资料旧价值，范围大于新创造的价值，不能等同。","B":"劳动力自身价值只是必要劳动时间创造的部分，遗漏了剩余劳动创造的剩余价值。","C":"剩余价值只是剩余劳动时间创造的部分，遗漏了补偿劳动力价值的必要部分。","D":"新价值等于劳动力价值加剩余价值，即必要劳动与剩余劳动之和，涵盖全部新创造的价值。"},"memoryTip":"新价值是v加m，c属于转移的旧价值不算；题干问“新”，先把转移部分排除。"},"20362":{"solution":"价值形成过程只到产品价值等于预付资本为止；一旦劳动时间超过补偿劳动力价值那一点，多出的部分就形成剩余价值，价值形成过程随之转为价值增殖过程。这个“一定点”即补偿劳动力价值的时间。","optionAnalysis":{"A":"生产使用价值的时间贯穿整个劳动过程，划不出价值形成与价值增殖的分界。","B":"劳动一开始就在创造新价值，创造新价值的时间同样贯穿全程，无法充当分界点。","C":"补偿劳动力价值的时间是必要劳动与剩余劳动的分界，超过这一点就是无偿为资本家生产的剩余劳动时间。","D":"生产资料价值靠具体劳动转移，其转移过程与必要劳动、剩余劳动的时间划分并不对应。"},"memoryTip":"一定点就是替自己干完、开始替资本家干的那条线，即补偿工资所需的时间。"},"20363":{"solution":"工作日不变而劳动生产率提高，生活资料变便宜使劳动力价值下降，必要劳动时间缩短，剩余劳动时间相应延长，剩余价值率随之提高。实际工资提高与劳动力价值下降可以同时发生。","optionAnalysis":{"A":"工资的实物量提高不等于受剥削程度减轻，剩余价值率提高恰恰说明剥削加重。","B":"生产资料效率提高使同样劳动推动更多生产资料，剩余价值量仍可增加，B判断有误。","C":"劳动力价值下降、必要劳动缩短，正是剩余价值率提高的机制，C否认了这一点。","D":"必要劳动时间缩短而工作日不变，剩余劳动时间占比上升，剩余价值率必然提高。"},"memoryTip":"工资涨了剥削也重：实物工资上升与劳动力价值下降可并存，m′看必要劳动是否缩短。"},"20364":{"solution":"同一劳动在同样时间内创造的价值总量由劳动时间决定，与生产力无关；但生产力提高使使用价值量增加，分摊到每件商品上的价值就减少。可见生产力变化影响的是单位商品价值量。","optionAnalysis":{"A":"引文明确说生产力提高时使用价值量多些，A与原文直接冲突。","B":"生产力本身就是生产效率的标志，它的变化必然改变效率，B否认了基本常识。","C":"价值总量不变而使用价值量随生产力变动，单位商品价值量等于总量除以数量，必然随之变化。","D":"同一劳动在同样时间提供的价值总量不变，改变的只是使用价值量，D误读了引文。"},"memoryTip":"劳动生产率与单位商品价值量成反比，与同一时间创造的价值总量无关。"},"20365":{"solution":"垄断价格由成本价格加垄断利润构成，售价可以高于生产价格，但垄断组织要避免净亏损，至少要收回成本并取得平均利润，因此它能接受的最低界限是生产价格。","optionAnalysis":{"A":"成本价格只能补偿c和v，不含平均利润，低于生产价格，仅够保本，还谈不上避免净亏损。","B":"生产价格等于成本价格加平均利润，是垄断组织出售商品的最低界限，低于此便无利可图。","C":"垄断低价是垄断组织购买原材料、零部件时压价形成的买价，与出售商品的最低界限不是同一问题。","D":"垄断高价是垄断组织出售商品时的价格形式，属于价格上限方向的概念，不能充当最低界限。"},"memoryTip":"垄断价格上限看需求、下限看生产价格；成本价格只是保本线，还不够。"},"20366":{"solution":"引文的关键是卖者成为债权人、买者成为债务人，即商品让渡与货币支付在时间上分离。货币在这种赊购赊销关系中充当清偿债务的手段，取得了支付手段职能。","optionAnalysis":{"A":"价值尺度是货币衡量商品价值并表现为价格，不涉及买卖双方的债权债务关系。","B":"流通手段要求一手交钱一手交货，货币与商品同时易位，与延期支付正相反。","C":"贮藏手段是货币退出流通被保存起来，与清偿债务无关。","D":"商品先让渡、货币后支付，卖者成为债权人，货币用于清偿债务，正是支付手段职能。"},"memoryTip":"题干一见“债权人和债务人”就选支付手段：钱货分离、延期支付。"},"20367":{"solution":"资本主义在发展社会生产力的同时，不自觉地为更高级的生产形式创造物质条件，说明它并非永恒，而是历史的、过渡性的生产形式，最终将被社会主义所取代。","optionAnalysis":{"A":"资本主义基本矛盾限制生产力发展，说它能无限制解放生产力，与教材判断和事实都不符。","B":"题干说它为“更高级的生产形式”准备条件，恰恰意味着资本主义将被超越，B与题意相反。","C":"资本主义曾创造出远超以往时代的物质财富，“越扩张越不利于创造财富”与历史事实相悖。","D":"为更高级形式创造物质条件，意味着资本主义只是历史过程的一个阶段，具有过渡性质。"},"memoryTip":"“为更高级形式准备条件”就是自己否定自己，落点永远是历史的过渡性。"},"20368":{"solution":"私有制商品经济中不存在统一的社会计算，复杂劳动折合为简单劳动的比例，是在无数次商品交换中由市场机制自发形成的，不以任何人的预先计算或规定为依据。","optionAnalysis":{"A":"生产者各自独立经营，既无能力也无需事先计算社会折算比例，A把自发过程说成自觉行为。","B":"私有制下没有统一的社会管理中心，市场管理部门也不可能事先规定折算标准。","C":"交换双方是按价值规律成交，不是就劳动折算比例讨价还价，C混淆了交换与约定。","D":"复杂劳动还原为简单劳动在交换中通过反复比较自发完成，是市场机制作用的结果。"},"memoryTip":"“自发”二字定音：计算、规定、协商都带人为色彩，只有市场机制自发实现。"},"20369":{"solution":"私有制商品经济中，生产者的劳动直接表现为私人劳动，又因社会分工而具有社会性质。产品能否卖出去、私人劳动能否被承认为社会劳动，决定生产者命运，这一矛盾就是基本矛盾。","optionAnalysis":{"A":"使用价值与价值的矛盾由私人劳动和社会劳动的矛盾引起，是后者的表现，不是基本矛盾本身。","B":"私人劳动能否转化为社会劳动决定商品能否卖出，进而决定生产者命运，正是私有制商品经济的基本矛盾。","C":"具体劳动与抽象劳动的矛盾源于劳动二重性，是基本矛盾在劳动性质层面的体现。","D":"脑力劳动与体力劳动的对立来自旧式分工，与商品经济的基本矛盾不在同一层面。"},"memoryTip":"总矛盾记“私对社会”：私人劳动对社会劳动，其余矛盾都是它的表现。"},"20370":{"solution":"马克思创立劳动二重性学说，才科学说明抽象劳动形成价值、具体劳动创造使用价值，进而解开剩余价值来源之谜，为整个理论体系提供方法论基础，因此被称为理解政治经济学的枢纽。","optionAnalysis":{"A":"剩余价值理论是马克思主义政治经济学的基石和核心，地位极重要，但教材不称其为“枢纽”。","B":"价值规律是商品经济的基本规律，回答价格如何围绕价值波动，不构成理论体系的枢纽。","C":"劳动二重性是理解商品二因素、剩余价值生产、资本有机构成等一系列问题的钥匙，正是枢纽所在。","D":"商品二因素理论以劳动二重性为前提，是由后者推出的结论，不能反过来说它才是枢纽。"},"memoryTip":"两顶帽子分开戴：基石是剩余价值理论，枢纽是劳动二重性理论。"},"20371":{"solution":"“机器换人”使单位劳动推动的生产资料大幅增加，生产资料与劳动力的比例上升，即资本技术构成提高，并带动资本有机构成提高。机器人只转移价值，不改变剩余价值的来源。","optionAnalysis":{"A":"机器人替代工人使生产资料与劳动力的比例上升，资本技术构成随之提高，判断正确。","B":"剩余价值的唯一来源仍是雇佣工人的剩余劳动，机器只转移旧价值、不创造价值，来源没有改变。","C":"使用机器人提高了劳动生产率，单位商品所含价值反而下降，C说商品价值提高正好相反。","D":"率先使用的企业得到的是超额剩余价值，属个别企业的超额利润，不是社会平均利润。"},"memoryTip":"机器换人等于c比v上升即技术构成提高，但机器人不创造价值，源泉不变。"},"20372":{"solution":"垄断资本主义即帝国主义，其经济实质和历史地位都系于垄断：垄断组织控制生产和市场，凭借垄断地位获取高额利润，其他特征均由垄断派生而来。","optionAnalysis":{"A":"自由竞争被垄断取代，垄断成为最深厚的经济基础，构成现代资本主义的经济实质。","B":"剥削是资本主义的一般本质，自由竞争阶段同样存在，标识不出垄断阶段的特殊性。","C":"国家调节经济是国家垄断资本主义的重要手段和表现，属派生形式，不是经济实质。","D":"对外掠夺是垄断资本向外扩张的表现，由垄断的经济关系决定，不能倒果为因。"},"memoryTip":"问现代资本主义的“实质、基础”就锁垄断，国家调节和对外掠夺都是派生。"},"20373":{"solution":"自由竞争发展到垄断，根本标志不是某个新现象冒头，而是垄断组织在经济生活中取得统治地位、自由竞争让位于垄断。资本输出、金融资本等特征都在这个基础上展开。","optionAnalysis":{"A":"垄断代替自由竞争占据统治地位，是自由竞争阶段进入垄断阶段的根本标志。","B":"资本输出地位上升是垄断阶段的特征之一，由垄断统治派生，不是划分阶段的根本标志。","C":"垄断阶段是银行资本与工业资本融合为金融资本，而非银行资本取代工业资本，表述本身有误。","D":"国家垄断代替私人垄断发生在第二次世界大战后，比自由竞争向垄断的转变晚得多。"},"memoryTip":"分水岭只有一条：垄断占统治地位；国家垄断要到二战后才登场。"},"20374":{"solution":"垄断价格由成本价格、平均利润和超过平均利润的垄断利润三部分构成，它高于生产价格，高出的部分正是垄断利润。垄断组织就是靠这种价格取得高额利润。","optionAnalysis":{"A":"成本价格补偿耗费，平均利润是部门间竞争形成的一般水平，垄断利润是超出平均利润的高额部分，三者相加即垄断价格。","B":"成本价格加平均利润只是生产价格，属自由竞争阶段的价格基础，缺少垄断利润。","C":"把自由竞争阶段的生产价格当作垄断价格的基础，混淆了两个阶段的价格范畴，教材不采此说。","D":"成本价格加产业利润遗漏了平均利润和垄断利润，构成不完整。"},"memoryTip":"垄断价格等于成本价格加平均利润再加垄断利润，与生产价格的差额就是垄断利润。"},"20375":{"solution":"国家垄断资本主义形式多样，国有企业、公私合营都属局部形式，覆盖面最广、作用最经常的是国家对整个经济的调节，故国家调节经济是最主要、最重要的形式。","optionAnalysis":{"A":"“国家市场垄断经济”不是教材概括国家垄断资本主义形式的规范用语，概念含混。","B":"国家运用财政、货币、产业政策进行宏观调节和微观规制，涉及面最广、作用最经常，是最主要形式。","C":"公私合营经济只是国家与私人资本结合的一种具体形式，规模和影响有限，不居主导地位。","D":"“国家自然垄断经济”属于国有经济的一部分，只是具体形式之一，不能与整体调节相比。"},"memoryTip":"最主要记“国家调节”，含宏观调节加微观规制；国有化、公私合营都只是具体形式。"},"20376":{"solution":"生产社会化程度提高与生产资料私人占有之间的矛盾日益尖锐，单靠私人垄断资本无力解决，只能借助国家力量干预经济，所以国家垄断资本主义从根本上说是基本矛盾运动的产物。","optionAnalysis":{"A":"国内市场竞争是促使资本集中的因素，属一般原因，解释不了国家政权与垄断资本的直接结合。","B":"国际竞争压力是外部诱因，同样由基本矛盾派生，不是“从根本上说”的答案。","C":"垄断统治提供了经济基础，但迫使国家介入的根源在于基本矛盾激化，C停在中间环节。","D":"基本矛盾运动迫使垄断资本借助国家力量维持再生产，这是国家垄断资本主义产生的根本原因。"},"memoryTip":"凡问“根本原因”就回到基本矛盾，竞争、危机、劳资冲突都是它的表现形式。"},"20377":{"solution":"垄断资本在国内确立统治后必然向外扩张，各国垄断组织通过协定划分销售市场、原料产地和投资场所，形成国际垄断同盟，实现在经济上瓜分世界。","optionAnalysis":{"A":"国家垄断资本主义是国内资产阶级国家与垄断资本的结合，不涉及国际间的经济瓜分。","B":"各国垄断组织订立协定、划分势力范围，正是国际垄断同盟，与题干指向一致。","C":"金融资本和金融寡头是国内垄断统治的主体，其形成早于并从属于国际瓜分。","D":"殖民地和宗主国反映的是从领土上瓜分世界，属政治占领，不是经济上瓜分的直接结果。"},"memoryTip":"经济上瓜分世界出国际垄断同盟，领土上瓜分世界出殖民体系，两条线别串。"},"20378":{"solution":"战后科技革命使生产社会化程度空前提高，巨额投资和巨大风险私人垄断资本无力承担，只能要求国家直接介入，国家垄断资本主义因此迅速发展，根源仍是基本矛盾深化。","optionAnalysis":{"A":"生产社会化与私人占有的矛盾在战后进一步加深，迫使国家全面干预，是迅速发展的根本原因。","B":"危机频繁是基本矛盾尖锐化的表现形式，它推动国家干预，本身却不是根本原因。","C":"经济全球化要求政策协调属外部条件且出现较晚，解释不了战后初期国家垄断的普遍发展。","D":"劳资矛盾尖锐是基本矛盾在阶级关系上的表现，同样由基本矛盾派生。"},"memoryTip":"危机、全球化、劳资冲突都是枝叶，根子在基本矛盾，问根本原因就抓根。"},"20379":{"solution":"跨国公司是国际垄断组织最典型的具体形式，以实力雄厚的垄断组织为母公司，通过对外直接投资在多个国家设立子公司和分支机构，形成跨国经营的多国公司。","optionAnalysis":{"A":"只强调“一国垄断组织”，把母公司局限于单一国家，忽略了它以国际化垄断组织为主体、在多国布局的组织特征。","B":"由多国垄断组织共同建立的经济联盟属国际垄断同盟的另一类型，不是跨国公司的组织形式。","C":"以垄断组织为母公司、通过对外直接投资在多国设立子公司，故称多国公司，与题干吻合。","D":"由多个国家政府共同建立的经济联盟是国家间经济一体化组织，主体是国家而非垄断组织。"},"memoryTip":"跨国公司的核心是“垄断组织当母公司、多国设子公司”，政府间联合才叫经济联盟。","reviewFlag":"本题标准答案为C，而教材通行表述为跨国公司“由一国垄断组织为主建立”，A项与之高度接近，建议复核答案。"},"20380":{"solution":"金融资本不是单纯的银行资本或工业资本，而是垄断阶段银行垄断资本与工业垄断资本通过相互持股、人事结合融合生长形成的新型资本，金融寡头就是它的人格化。","optionAnalysis":{"A":"把支配权归银行、使用权归工业资本家，割裂了二者的融合关系，也颠倒了实际支配格局。","B":"银行垄断资本只是融合的一方，单独存在时仍是银行资本，尚未与工业垄断资本融为一体。","C":"国家控制的资本属国家垄断资本主义范畴，形成机制与金融资本完全不同。","D":"银行垄断资本与工业垄断资本融合生长形成金融资本，是垄断阶段资本形态的核心特征。"},"memoryTip":"金融资本的关键词是“融合”，银行垄断资本加工业垄断资本，不是谁替代谁。"},"20381":{"solution":"二战后国际垄断组织形式发生更替：战前以国际卡特尔这类私人协定型同盟为主，战后则以跨国公司为主，通过对外直接投资在国际范围内组织生产。","optionAnalysis":{"A":"国际卡特尔是战前国际垄断同盟的典型形式，战后地位明显下降，不再是主要形式。","B":"经济共同体是国家间经济一体化组织，主体是各国政府，不属于国际垄断组织的主要形式。","C":"混合联合公司是国内垄断组织跨部门多样化经营的形式，不特指国际范围的生产经营。","D":"战后跨国公司凭借对外直接投资大规模扩张，成为国际垄断组织的主要形式。"},"memoryTip":"时间轴记清：战前国际卡特尔，战后跨国公司；国家出面联合的叫经济共同体。"},"20382":{"solution":"资本社会化指资本占有和支配形式不断社会化。股份公司是初步形式，国家垄断资本主义使资本在全社会范围内由资产阶级国家统一支配，因而达到最高形式。","optionAnalysis":{"A":"垄断资本主义包含以私人垄断为主的阶段，社会化程度有限，尚未达到由国家统一支配的高度。","B":"国家垄断资本主义使资本关系在全社会规模上社会化，是资本社会化发展的最高形式。","C":"生产社会化是资本社会化的物质基础和生产力前提，本身不是资本占有形式。","D":"经营管理社会化是生产社会化的一个方面，层次低于资本占有的社会化。"},"memoryTip":"资本社会化阶梯：股份公司起步，私人垄断发展，国家垄断到顶。"},"20383":{"solution":"国家干预经济并不改变资本主义性质，出发点是缓和矛盾、维持再生产，落脚点既不是个别资本家也不是劳动者，而是资产阶级特别是垄断资产阶级的整体利益和长远利益。","optionAnalysis":{"A":"促进经济稳定增长是干预的直接目标之一，属手段层面的效果，不是实质。","B":"国家干预只能缓和而不能消除经济危机，说“消除”违背基本矛盾原理，本身也不成立。","C":"加强对劳动者的剥削是干预的阶级后果之一，但缺了“整体、长远”这一关键限定，以偏概全。","D":"国家以社会总资本家的身份调节经济，维护资产阶级的整体利益和长远利益，正是实质所在。"},"memoryTip":"国家干预的实质记“两全”：整体利益加长远利益，不是个别资本家的眼前得失。"},"20384":{"solution":"进入国家垄断资本主义阶段，私人垄断仍是基础，变化在于国家政权与垄断资本结合，政府承担起调控宏观经济的重要职能，用财政、货币政策等干预经济运行。","optionAnalysis":{"A":"政府作为总资本家承担宏观调控职能，是这个阶段的显著标志，判断正确。","B":"私人垄断资本仍是经济生活的基础，说国家垄断资本“掌控”经济生活，夸大了国有成分的地位。","C":"国有化只涉及部分行业且随政府更替有进有退，从未对“所有重要的经济部门”实行国有化。","D":"国家垄断建立在私人垄断基础之上，二者不是简单比轻重，D掩盖了私人垄断的基础地位。"},"memoryTip":"国家垄断阶段的公式：私人垄断当底座，政府当总资本家调控宏观。"},"20385":{"solution":"经济全球化中利益分配失衡，根源在于旧的国际经济秩序及其不公平规则。只有建立公正合理的国际新秩序，改变规则制定中的不平等，才可能实现共赢共存。","optionAnalysis":{"A":"南南合作是发展中国家之间的互助，能增强谈判能力，却改变不了全球规则，故非关键。","B":"反对恐怖主义属安全领域议题，与经济全球化的利益分配机制不在同一层面。","C":"旧秩序下的不等价交换和规则倾斜是失衡根源，建立公正合理的国际新秩序才是实现共赢的关键。","D":"南北对话是沟通协调的渠道，能缓解矛盾，但不改变旧秩序就难有实质公平。"},"memoryTip":"共赢的关键在“规则”：旧秩序换新秩序，南南合作和南北对话都只是路径。"},"20386":{"solution":"经济全球化的载体是企业。跨国公司通过对外直接投资在全球配置资源、组织生产与销售，把各国经济联结在一起，因而成为全球化的主要承担者和推动者。","optionAnalysis":{"A":"世界贸易组织协调贸易规则，为全球化提供制度框架，本身不直接组织生产经营活动。","B":"国际货币基金组织负责国际金融协调与援助，属制度性安排，不是全球化的主要推动力量。","C":"跨国公司以对外直接投资把生产、销售、研发布局全球，是经济全球化的主要承担者和推动者。","D":"主权国家是全球化的参与者和规则制定者，但全球化的微观载体和直接推动力在企业。"},"memoryTip":"全球化靠企业的“腿”走路：制度框架靠国际组织，实际承载靠跨国公司。"},"20387":{"solution":"题目问“不包括”，须排除对发达国家不利的项。全球化使发达国家得以在全球配置资源、降低成本、获取高额利润并控制国际金融市场，而贸易逆差扩大并非其得到的好处。","optionAnalysis":{"A":"凭借技术、品牌和规则优势从世界各地获取高额利润，确是发达国家得到的利益。","B":"把生产基地转移到劳动力和资源价格更低的国家，生产成本确实下降。","C":"贸易逆差扩大意味着进口大于出口，冲击本国产业和就业，不属于全球化带给发达国家的好处。","D":"凭借金融优势和货币地位，发达国家加强了对国际金融市场的控制，是实际获益。"},"memoryTip":"逆差是“失”不是“得”，好处清单里混进逆差，用利弊方向就能秒排。"},"20388":{"solution":"垄断阶段工业生产高度集中，银行也由普通支付中介变为垄断者，二者融合形成金融资本，金融寡头据此掌握经济命脉，所以占统治地位的资本是金融资本。","optionAnalysis":{"A":"工业资本是自由竞争阶段占统治地位的资本形态，垄断阶段已被金融资本取代。","B":"农业资本在国民经济中比重下降，且同样从属于金融资本的支配。","C":"银行资本只是金融资本的一个来源，单独存在时还支配不了整个经济。","D":"银行垄断资本与工业垄断资本融合成金融资本，金融寡头依靠它实现全面统治。"},"memoryTip":"自由竞争看工业资本，垄断阶段看金融资本，分界线就在“融合”二字。"},"20389":{"solution":"列宁概括的垄断资本主义五个基本特征中，垄断组织在经济生活中占统治地位是最根本的一条，资本输出、国际垄断同盟、瓜分世界等其余特征都由垄断派生。","optionAnalysis":{"A":"列宁讲的是国际垄断同盟的形成，不是“国家垄断同盟”，且它由垄断统治派生，并非最根本。","B":"资本输出意义重大是垄断阶段的重要特征，但它是垄断统治在经济扩张上的表现。","C":"垄断在经济生活中占统治地位，决定其余一切特征，是五个特征中最根本的一条。","D":"瓜分世界领土、形成殖民体系是垄断统治在国际政治领域的延伸，属派生特征。"},"memoryTip":"五特征里排第一的是垄断，其余四条都是垄断“长出来的枝叶”。"},"20390":{"solution":"国家垄断资本主义不是凭空产生，它建立在私人垄断资本的基础之上，是私人垄断资本与国家政权结合的产物，国有垄断资本也由私人垄断资本转化而来。","optionAnalysis":{"A":"国有垄断资本是国家垄断资本主义的重要成分，但它由私人垄断资本转化形成，不能充当基础。","B":"资产阶级国家是结合的一方，属于上层建筑，不能作为经济形式赖以生长的基础。","C":"私人垄断的发展使生产社会化与私人占有的矛盾激化，才引出国家干预，私人垄断是基础。","D":"资本输出是垄断阶段的对外扩张形式，与国家垄断资本主义的发展基础无关。"},"memoryTip":"先有私人垄断，后有国家与它的结合，底座永远是私人垄断。"},"20391":{"solution":"国家垄断资本主义是私人垄断资本与国家政权的结合，它不改变资本主义性质，也不触动私人垄断的基础，而是从资产阶级整体出发维护垄断资本的总利益。","optionAnalysis":{"A":"国家干预只在资本主义框架内调整关系，所有制和雇佣劳动的性质未变，A判断错误。","B":"国家以社会总资本家的身份协调各垄断集团利益，符合垄断资本家的整体利益，判断正确。","C":"国家调节着眼于资产阶级的整体和长远，可能损害个别资本家的眼前利益，C缩小了主体范围。","D":"私人垄断仍是基础，国家垄断恰恰以它为前提，D说“消灭”与现实相反。"},"memoryTip":"三句话定位：性质不变、基础不动、利益变“整体”。"},"20392":{"solution":"参与制是金融寡头通过控制股票实现层层控股的办法：掌握母公司一定比例的股票即可支配母公司，再由母公司控制子公司，逐级放大，用少量资本支配大量社会资本。","optionAnalysis":{"A":"金融寡头一般不直接插手单个工业企业的日常经营，而是通过控股和人事结合间接控制。","B":"直接参与银行经营只是控制链条中的一个环节，概括不了参与制层层控股的实质。","C":"参与制的要害是掌握足够比例的股票而非全部股票，购买全部股票既不可能也无必要。","D":"以少量股票控制母公司、再层层控制子公司，正是参与制实现经济统治的方式。"},"memoryTip":"参与制是“控股金字塔”：买一定数量股票层层放大，绝不需要买全部股票。"},"20393":{"solution":"国家垄断资本主义的实质是资产阶级国家同垄断资本相结合：国家以总资本家身份直接参与社会资本再生产过程，为垄断资本的整体利益服务。","optionAnalysis":{"A":"国家干预能缓解生产的无政府状态，但不可能消除，A夸大了国家调节的作用。","B":"二者是结合而非分离，“相互分离”恰好说反了国家垄断资本主义的内涵。","C":"资产阶级国家与垄断资本融合在一起，政权与资本结合为一体，定义准确。","D":"国家垄断资本主义仍是资本主义，不包含社会主义因素，D混淆了社会性质。"},"memoryTip":"国家垄断资本主义的公式是国家加垄断资本“融合”，既非分离也非社会主义。"},"20394":{"solution":"战后国家垄断资本主义依托科技革命和国家干预的常态化，发展迅速并在经济生活中持续占据重要地位；其间虽有国有化与非国有化的调整，总体趋势仍是持续发展。","optionAnalysis":{"A":"战后国家垄断资本主义扩张很快，说“发展缓慢不稳定”与事实不符。","B":"战后国家垄断资本主义迅速发展，并在经济生活中持续稳定地发挥作用，符合教材判断。","C":"国有化与非国有化的交替只是具体形式的调整，不改变总体持续发展态势，C判断偏颇。","D":"政策重点会随经济形势变化，但国家垄断的总体地位没有逆转，D把形式调整误作方向变化。"},"memoryTip":"战后关键词是“迅速加持续”：国有化可进可退，总体方向不逆转。"},"20395":{"solution":"国家对社会经济的宏观管理与调节，是从社会总资本再生产的要求出发，协调各垄断集团之间的利益冲突，因而体现的是垄断资产阶级的整体利益。","optionAnalysis":{"A":"调节以维持资本再生产为目的，不可能代表全体劳动人民的经济利益。","B":"个别金融寡头的特殊利益可能与整体利益冲突，国家调节恰恰要抑制这种局部要求。","C":"国家以总资本家身份协调各方，宏观调节体现垄断资产阶级的整体利益，判断正确。","D":"国有企业只是调节的工具之一，宏观调节服务的对象是整个垄断资产阶级，而非国企自身。"},"memoryTip":"宏观调节服务对象锁“整体”二字，个别寡头和国企都不是答案。"},"20396":{"solution":"国家垄断资本主义只能在资本主义框架内调整关系，它可以暂时缓和某些矛盾，却触动不了基本矛盾，反而使矛盾在更大规模上积累、加深并趋于复杂。","optionAnalysis":{"A":"时而迅速发展时而停滞，是国家垄断资本主义的发展特点，不是对其局限性的概括。","B":"战后资本主义经济曾有明显增长，说长期停滞不符合事实，也不是局限性的表述。","C":"滞胀是20世纪70年代出现的阶段性现象，概括不了国家垄断资本主义的长期状态。","D":"只能暂时缓和矛盾、却使矛盾进一步加深和复杂化，正是其根本局限所在。"},"memoryTip":"局限性一句话：只“暂缓”不“解决”，矛盾反而在更大规模上积累。"},"20397":{"solution":"经济全球化要以商品和生产要素跨国流动的现实规模为依托。国际贸易的高度发展使各国市场连成一体，为生产、投资、金融的全球化提供了现实基础。","optionAnalysis":{"A":"新科技革命提供的是物质技术条件和根本动力，属于全球化的技术基础。","B":"生产国际化是全球化在生产领域的展开，属全球化的重要内容，但题干问“现实基础”，落点在贸易。","C":"国际贸易高度发展使商品和生产要素跨国流动成为常态，构成经济全球化发展趋势的现实基础。","D":"国际金融迅速发展是全球化在金融领域的表现，它依托贸易与生产国际化而展开。"},"memoryTip":"分工记牢：科技是动力，贸易是现实基础，生产国际化是内容，金融是表现。"},"20398":{"solution":"题目问“不包括”，需排除不属于消极影响的项。全球化在带来资本、技术和市场机会的同时，也使发展中国家经济利益受损、价值转移、金融风险上升，但并没有让发展机会大大减少。","optionAnalysis":{"A":"在不等价交换和规则劣势下，发展中国家的经济利益确实会遭受一定损失。","B":"发达国家凭借技术和规则优势获取更多利益，发展中国家在国际贸易中剩余价值大量流失。","C":"资本项目开放和国际游资冲击使发展中国家金融风险明显加大，是普遍现象。","D":"全球化同时给发展中国家带来资金、技术和市场机会，说机会“大大减少”与事实相反。"},"memoryTip":"抓“机会”二字：全球化对发展中国家是机遇与风险并存，机会并没有减少。"},"20399":{"solution":"资本主义基本矛盾即生产社会化与生产资料私人占有的矛盾，在其发展中不断尖锐，最终要求由社会占有生产资料，所以历史趋势是社会主义公有制取代资本主义私有制。","optionAnalysis":{"A":"计划经济与市场经济都是资源配置方式，不构成社会形态更替的方向。","B":"市场经济取代计划经济描述的是体制转轨，与资本主义的历史命运无关。","C":"商品经济与计划经济不在同一层次，未来社会也不以取消商品经济为标志。","D":"生产社会化要求生产资料归社会所有，社会主义公有制取代资本主义私有制是必然趋势。"},"memoryTip":"历史趋势只认“所有制”更替：公有制取代私有制，其余选项都在体制层面打转。"},"20400":{"solution":"国家垄断资本主义使生产、资本和经营管理全面社会化，国有经济和社会调节机构为全社会统一组织生产提供了现成形式，因而被认为为向社会主义过渡准备了物质条件。","optionAnalysis":{"A":"国家垄断资本把生产、资本和经营管理推向全面社会化，提供了社会主义所需的物质前提。","B":"商品化程度提高属经济形式变化，与向社会主义过渡的物质条件不是同一命题。","C":"市场化是资源配置方式，说明不了生产社会化为新社会准备了什么。","D":"市场的计划化是调节手段的调整，不触及生产社会化这一物质基础。"},"memoryTip":"过渡的物质条件锁“全面社会化”：生产、资本、管理三方面，不是商品化市场化。"},"20401":{"solution":"题干问的是“正确认识”历史过渡性，态度上既不能全盘否定也不能全盘肯定。资本主义制度终将被取代，但其在长期发展中形成的反映社会化生产规律的文明成果可以借鉴，C项正是这种辩证态度。","optionAnalysis":{"A":"把资本主义的一切改良都说成毫无意义，是形而上学的全盘否定，既不符合事实，也无法解释资本主义为何还能容纳生产力发展。","B":"全面肯定等于否认资本主义的历史暂时性，与“过渡性”这一前提直接冲突，也违背基本矛盾运动的分析。","C":"承认资本主义必然被取代，同时把其中反映人类文明进步、反映社会化生产规律的改良成果拿来为我所用，符合辩证否定观。","D":"借鉴的对象是具体制度成果和管理经验，不能把“发展资本主义经济制度”作为目标，那会混淆两种社会制度的根本性质。"},"memoryTip":"过渡性＝辩证否定：否定制度，借鉴文明成果；既不全盘抛弃，也不照搬制度。"},"20402":{"solution":"当代大公司股权高度分散，股东难以直接经营，所有权与经营权分离，日常经营决策权落到职业经理层手中。题目问“实际控制者”，指的正是掌握经营权的群体，故选高级经理。","optionAnalysis":{"A":"高级经理层掌握经营决策权，股东大会只保留重大事项表决等最终所有权职能，故实际控制者是经理层。","B":"股东大会是公司的最高权力机构，但股权分散使其沦为形式上的所有者代表，并不介入日常经营。","C":"监事会是监督机构，负责监督董事和经理的行为，不掌握经营决策权，不能成为实际控制者。","D":"理事会不是公司治理结构中的法定机关，多用于非营利组织，与股份公司的股东会、董事会、监事会不对应。"},"memoryTip":"股权分散导致所有权与经营权分离，出现“经理革命”：掌实权的是高级经理，不是股东会。"},"20403":{"solution":"资本所有制的演进顺序是私人资本所有制、私人股份资本所有制、法人资本所有制。当代大公司由各类法人机构持股，法人资本所有制成为居主导地位的形式，故选B。","optionAnalysis":{"A":"私人资本所有制是自由竞争阶段单个资本家的所有制，规模小、所有权与经营权合一，早已不是当代主导形式。","B":"法人资本所有制以各类法人机构持股为特征，与生产社会化程度提高相适应，在当代资本主义经济中居主导地位。","C":"私人股份资本所有制是19世纪末出现的过渡形式，由私人股东联合持股，其主导地位已被法人资本所有制取代。","D":"教材划分资本所有制形式不使用“垄断资本私人所有制”这一提法，属于自造概念，无法与演进序列对应。"},"memoryTip":"三段式：私人资本→私人股份资本→法人资本，当代主导是序列最后一站。"},"20404":{"solution":"题干限定“制度条件”，须在制度与政策层面找原因。20世纪70年代以来西方国家推行金融自由化，放松管制并鼓励金融衍生品创新，为金融资本膨胀提供了制度空间，故选A。","optionAnalysis":{"A":"金融自由化解除利率和业务交叉等管制，金融创新不断推出衍生工具，二者共同构成金融资本膨胀的制度条件。","B":"技术创新和互联网金融属于技术手段层面的条件，不是制度条件，且互联网金融兴起晚于70年代这一时间起点。","C":"全面私有化是所有制层面的调整，且“全面”过于绝对；放松监管只是金融自由化的一个侧面，不能替代完整表述。","D":"去工业化是金融资本膨胀的结果和表现，而不是原因，把结果当作制度条件属于因果倒置。"},"memoryTip":"记“两金融”：金融自由化＋金融创新＝制度条件；技术是手段，去工业化是结果。"},"20405":{"solution":"马克思主义由哲学、政治经济学、科学社会主义三部分组成。哲学提供世界观方法论，政治经济学作出论证，科学社会主义则是全部学说的核心和理论结论，故选C。","optionAnalysis":{"A":"马克思主义哲学是理论基础和世界观方法论，起指导作用，但本身不是整个学说的归宿和结论。","B":"政治经济学是主要内容，通过剩余价值学说揭示资本主义剥削实质，为结论作论证，而非结论本身。","C":"科学社会主义是马克思主义的核心，是哲学和政治经济学论证得出的最终结论，也是全部学说的落脚点。","D":"无产阶级革命学说是科学社会主义的组成部分之一，范围小于科学社会主义，不能充当整体核心。"},"memoryTip":"哲学是基础，政经是论证，科社是核心与结论——按“基础—论证—结论”三段记。"},"20406":{"solution":"新经济政策放弃战时共产主义直接过渡的做法，改行粮食税、允许商品交换和国家资本主义，核心是从俄国小农占多数的实际出发。邓小平说它“比较好”，正是肯定这种从本国国情出发的探索，故选B。","optionAnalysis":{"A":"新经济政策是在实践中逐步调整的政策体系，并未形成系统的社会主义建设纲领，这一评价拔高了它的理论形态。","B":"以粮食税代替余粮收集制、允许自由贸易，都是依据俄国小农经济占优势的国情作出的调整，体现了实事求是。","C":"新经济政策只是探索的开端，列宁本人也认为还需长期实践，说它已提供“比较成熟的模式”不符合实际。","D":"马克思恩格斯设想的未来社会不存在商品货币关系，而新经济政策恰恰利用商品货币关系，二者方向相反。"},"memoryTip":"新经济政策的关键词是“国情”：小农占多数，所以退一步、用市场，不照搬本本。"},"20407":{"solution":"列宁这句话讲的是革命与经济发展程度的关系：起义可以改变政权，却不能凭空造出社会主义所需的物质基础，说明社会主义革命必须以一定的生产力发展为前提，故选D。","optionAnalysis":{"A":"列宁恰恰主张经济相对落后的俄国可以首先革命，若理解为只能在发达国家取胜，正好与他的一国胜利论相反。","B":"社会主义思想不会在工人运动中自发产生，需要政党从外部灌输，革命更不会在资本主义内部自发完成。","C":"把“需要物质前提”误解为“只能靠经济力量”，取消了革命政党和群众的能动作用，是经济自发论。","D":"经济上尚未成熟就不能凭起义造出社会主义，说明革命需要生产力发展提供的物质前提，只是不要求前提完全成熟。"},"memoryTip":"抓住“不能凭空”：物质前提不可跳过，但可先夺权再补课——前提不等于完全成熟。"},"20408":{"solution":"社会主义民主是新型国家制度，其本质与核心在于人民在国家政治生活中居于主体地位。党的领导是根本保证，依法治国是基本方略，人民代表大会制度是载体，唯有人民当家作主才属本质层面，故选C。","optionAnalysis":{"A":"党的领导是社会主义民主政治的根本保证，回答的是“靠谁领导”，不是民主自身的本质和核心。","B":"依法治国是党领导人民治理国家的基本方略，属于运行方式和制度保障，不回答民主的本质归属。","C":"人民当家作主体现国家一切权力属于人民，是社会主义民主政治的本质特征和核心所在。","D":"人民代表大会制度是我国的根本政治制度，是实现人民当家作主的制度载体，属于形式层面。"},"memoryTip":"本质看“谁作主”：人民当家作主是本质，党的领导是保证，人大制度是载体，依法治国是方略。"},"20409":{"solution":"列宁这句话的落点在“国家”二字：民主是被承认的、以少数服从多数为原则的国家形式，即一种国家制度。前半句还特意提醒不能把民主简单等同于少数服从多数，故选C。","optionAnalysis":{"A":"民主既体现国体又通过政体实现，把二者对立起来并只归为国体，是对列宁原话的窄化。","B":"手段与目的之争不是这句话要回答的问题，列宁谈的是民主的国家属性，未涉及工具性。","C":"原话把民主界定为“承认少数服从多数的国家”，即民主是一种国家制度、国家形式，落点在制度属性上。","D":"列宁开篇即说“民主和少数服从多数不是一个东西”，把实质归结为少数服从多数恰好违背原意。"},"memoryTip":"原话的破题点在后半句“国家”：民主＝一种国家制度，而非单纯的表决规则。"},"20410":{"solution":"宗旨回答的是“为谁服务”。无产阶级政党除了工人阶级和最广大人民的利益，没有自己的特殊利益，因此把为人民群众谋利益作为根本宗旨，故选A。","optionAnalysis":{"A":"党没有自己的特殊利益，一切奋斗都落脚于人民利益，这正符合“根本宗旨”的内涵。","B":"实现共产主义是党的最高理想和最终目标，属于奋斗目标层面，不能等同于服务对象的宗旨。","C":"消灭私有制是革命所要完成的历史任务，是手段和途径，不是党存在和活动的根本出发点。","D":"为无产阶级解放而斗争是党的历史使命，范围窄于“人民群众”，把广大同盟者排除在外。"},"memoryTip":"宗旨问“为谁”：为人民谋利益；目标问“到哪”：共产主义；使命问“干什么”：解放无产阶级。"},"20411":{"solution":"组织原则解决的是党内如何形成决议、如何保持统一。无产阶级政党实行民主基础上的集中和集中指导下的民主相结合，即民主集中制，故选D。","optionAnalysis":{"A":"少数服从多数是民主集中制内部的一条具体规则，层次低于组织原则，不能作为整体原则。","B":"全心全意为人民服务是党的根本宗旨，讲的是价值取向，不是组织运作原则。","C":"人民民主专政是我国的国体即国家制度，属于国家政权层面，不是政党的组织原则。","D":"民主集中制把党内民主与集中统一结合起来，是马克思主义政党通行的组织原则和领导制度。"},"memoryTip":"党内讲“民主集中制”，国家讲“人民民主专政”，宗旨讲“为人民服务”，三层别混。"},"20412":{"solution":"社会阶段的划分有多种尺度，但生产力是社会发展的最终决定力量，社会主义从初级阶段向更高阶段推进，归根到底取决于生产力发展水平，故选A。","optionAnalysis":{"A":"生产力是最活跃最革命的因素，最终决定生产关系和上层建筑的变化，因而也是划分社会主义阶段的最终标准。","B":"生产关系由生产力决定，用生产关系统帅划分标准，颠倒了生产力与生产关系之间的决定关系。","C":"公有制程度是生产关系的具体形式，脱离生产力水平追求公有制升级，恰是历史上急于求成的教训。","D":"阶级斗争只在阶级社会是主要矛盾，社会主义制度建立后已不是划分发展阶段的根本尺度。"},"memoryTip":"凡见“最终”“归根到底”，答案指向生产力；阶段划分不看过公程度，看生产力。"},"20413":{"solution":"1847年，马克思和恩格斯把正义者同盟改组为共产主义者同盟，并为其起草《共产党宣言》，这是历史上第一个以科学社会主义为指导的无产阶级政党，故选C。","optionAnalysis":{"A":"俄国共产党（布尔什维克）产生于19世纪末20世纪初的俄国，在时间上晚于共产主义者同盟半个多世纪。","B":"中国共产党成立于1921年，是马克思主义与中国工人运动相结合的产物，并非世界第一个无产阶级政党。","C":"共产主义者同盟1847年建立，以科学社会主义为指导思想，第一个无产阶级政党的历史地位由此确立。","D":"法国共产党成立于1920年，是第二国际破产后欧洲各国建党潮中的一员，时间远晚于1847年。"},"memoryTip":"1847同盟、1848宣言：先有党（共产主义者同盟），后有纲领（《共产党宣言》）。"},"20414":{"solution":"社会主义制度建立后，社会主要矛盾转向人民日益增长的需要同落后的生产之间的矛盾，根本任务随之定为解放和发展生产力，故选D。","optionAnalysis":{"A":"阶级斗争在社会主义制度建立后已不是主要矛盾，把阶级斗争当作根本任务会重犯扩大化的错误。","B":"改革生产资料所有制是经济体制改革的内容，属于手段和途径，服务于生产力发展。","C":"政治体制和经济体制改革是发展的动力机制，是实现根本任务的途径，不能取代任务本身。","D":"生产力是社会发展的最终决定力量，社会主义要显示优越性、迈向更高阶段，根本任务就是解放和发展生产力。"},"memoryTip":"根本任务看“生产力”，根本目的看“共同富裕”，根本保证看“党的领导”，三个“根本”分开记。"},"20415":{"solution":"根本目的回答“为谁发展、成果归谁”。社会主义否定剥削制度，追求全体人民共同富裕，因此消灭剥削、消除两极分化、最终达到共同富裕是根本目的，故选A。","optionAnalysis":{"A":"这一表述揭示社会主义区别于资本主义的本质要求，落脚于全体人民共享发展成果，契合“根本目的”。","B":"建立无产阶级专政是政治前提和政权保障，为目的的实现提供条件，本身不是目的。","C":"巩固共产党的领导是根本保证，属于政治领导层面，不能取代为人民谋利益的目的定位。","D":"镇压资产阶级反抗是无产阶级专政的职能之一，属于手段性、阶段性的任务。"},"memoryTip":"目的看“共富”：消灭剥削＋消除两极分化＋共同富裕；专政与党的领导都是保证，不是目的。"},"20416":{"solution":"列宁考察帝国主义阶段的新变化，发现各国经济政治发展不平衡加剧，后起国家可以突破统治链条的薄弱环节，由此得出社会主义可能在一国或数国首先胜利，依据正是这一规律，故选B。","optionAnalysis":{"A":"这是关于人类社会一般规律的判断，说明社会主义代替资本主义的必然性，过于一般，不能直接推出“一国首先胜利”。","B":"帝国主义时代发展不平衡加剧，战争削弱统治链条，使个别国家率先突破成为可能，这是结论的直接理论依据。","C":"无产阶级与资产阶级斗争的规律说明阶级斗争的必然性，不涉及各国革命时机为何不同。","D":"无产阶级的先进性和革命性说明“谁来革命”，不回答“革命在哪个国家先胜”的空间问题。"},"memoryTip":"一国胜利论的钥匙是“不平衡”三字：发展不平衡→链条薄弱环节→一国先突破。"},"20417":{"solution":"社会主义代替资本主义的根源在生产方式内部。生产社会化要求生产资料由社会占有，而资本主义私人占有制阻碍这一要求，基本矛盾不可调和，决定了代替的必然性，故选D。","optionAnalysis":{"A":"阶级斗争尖锐化是基本矛盾在阶级关系上的表现，是推动力量，不是最终依据。","B":"这一矛盾是个别企业有组织性与社会生产无政府状态之间的矛盾，只是基本矛盾的表现形式之一，层次较低。","C":"无产阶级队伍壮大提供阶级力量，属于主观条件，不能说明制度为何必然被取代。","D":"生产社会化与资本主义私人占有制之间的矛盾是资本主义基本矛盾，贯穿始终并决定其历史命运。"},"memoryTip":"必然性的根子在“基本矛盾”：社会化生产对私人占有；阶级斗争只是它的表现。"},"20418":{"solution":"一种社会制度能否站住脚，根本在于是否适合生产力发展要求。社会主义消除了生产社会化与私人占有的对抗性矛盾，能够容纳生产力发展，因而具有不可抗拒的生命力，故选D。","optionAnalysis":{"A":"优越性是对生命力表现的评价性概括，用结论解释结论，未说明生命力究竟从何而来。","B":"成功和辉煌是生命力已经发挥出来的结果，属于现象层面，不能充当原因。","C":"新生事物并不天然不可战胜，只有符合发展规律的新生事物才有前途，单说“新”失之空泛。","D":"社会主义与生产社会化的发展方向一致，能够解放和发展生产力，这是其生命力的根本来源。"},"memoryTip":"凡问“生命力”“为什么能存在”，一律回到“是否适应生产力发展要求”。"},"20419":{"solution":"1848年《共产党宣言》发表，第一次系统阐明唯物史观的基本思想，把社会主义置于现实基础之上，标志着社会主义从空想变为科学，故选A。","optionAnalysis":{"A":"《共产党宣言》系统阐明资本主义灭亡和社会主义胜利的规律，是社会主义由空想到科学飞跃的标志性著作。","B":"共产主义者同盟的建立为科学社会主义诞生提供了组织条件，是准备和前奏，本身不等于理论飞跃。","C":"空想社会主义理想的破灭只说明旧方案失效，并未产生科学理论，不能充当标志。","D":"无产阶级革命的胜利是科学社会主义指导下的实践成果，发生在理论诞生之后，因果顺序颠倒。"},"memoryTip":"空想到科学的界碑是1848年《共产党宣言》；1847年建盟只是组织准备，别混。"},"20420":{"solution":"此题考的是列宁那一结论的理论依据。帝国主义阶段各国经济和政治发展极不平衡，新旧力量对比剧烈变动，使革命突破口可能出现在个别国家，故选A。","optionAnalysis":{"A":"经济政治发展不平衡规律在帝国主义时代充分展开，是列宁提出“少数甚至单独一国首先胜利”的直接理论依据。","B":"资本主义国家的衰落是趋势性描述，笼统且非规律，无法说明为何是“一国”而非“各国同时”。","C":"科学社会主义理论的传播提供思想条件，属于主观条件，不是结论的理论依据。","D":"无产阶级力量壮大是阶级条件，回答革命力量问题，不解释革命发生的不平衡性。"},"memoryTip":"列宁这一结论的标准搭配只有一句：帝国主义时代经济政治发展不平衡规律。"},"20421":{"solution":"题干两句话分别说明党的思想基础（科学社会主义与工人运动结合）和阶级属性（工人阶级先锋队）。既以工人阶级为阶级基础又高于普通工人，结论就是党以工人阶级为基础，故选B。","optionAnalysis":{"A":"政党是阶级的先锋队而非阶级本身，把党组织与整个阶级等同，抹杀了先进分子与普通群众的区别。","B":"党从工人阶级中吸收先进分子、代表其根本利益，说明工人阶级是党的阶级基础，先锋队正建立在这一基础之上。","C":"题干强调的是党与工人阶级的源流关系；党的先进性还源于科学理论武装，不能只归于阶级性。","D":"因果关系颠倒：工人阶级的先进性和科学理论的指导共同决定党的先进性，而非党赋予阶级先进性。"},"memoryTip":"党＝工人阶级的先锋队，公式是“阶级基础＋先进分子”，绝不是“党＝阶级”。"},"20422":{"solution":"共产主义是马克思主义全部学说指向的目标，也是人类社会基本矛盾运动的必然归宿。题干“必然趋势”加“最崇高社会理想”两个限定，只能落于实现共产主义，故选A。","optionAnalysis":{"A":"实现共产主义既是历史规律展开的方向，又是马克思主义最崇高的社会理想，两重限定完全对应。","B":"共同富裕是社会主义的本质要求和根本目的，属于社会主义阶段的现实目标，层次低于共产主义理想。","C":"和谐是社会主义社会建设的一个目标维度，不是人类历史发展的最终趋势。","D":"物质极大丰富只是共产主义社会的特征之一，是条件而非理想本身，且不能单独概括趋势。"},"memoryTip":"最崇高理想＝共产主义；共同富裕属社会主义本质，物质极大丰富只是它的特征。"},"20423":{"solution":"预见未来社会靠的不是主观想象，而是科学的世界观和方法论。只有站在唯物史观立场，用辩证方法分析社会矛盾运动，才能正确预见，故选A。","optionAnalysis":{"A":"立场、观点和方法是认识的工具，方法对头才能从现实矛盾中引出未来趋势，这是预见的基本前提。","B":"研究资本主义社会是预见的具体途径之一，属于对象范围，而非方法论前提。","C":"揭示无产阶级的特点是研究得出的认识成果，不是预见所依赖的前提条件。","D":"阐述无产阶级历史使命同样是认识的结论，用它作前提，等于用结果推导结果。"},"memoryTip":"预见未来先看“拿什么看”：立场观点方法在前，研究对象和结论在后。"},"20424":{"solution":"马克思主义把共产主义分为低级和高级两个阶段，低级阶段即社会主义。社会主义充分发展、条件成熟后才过渡到共产主义，因此社会主义是实现共产主义的必由之路，故选D。","optionAnalysis":{"A":"奴隶社会是人类第一个阶级社会，属于共产主义之前的私有制形态，与共产主义阶段划分无关。","B":"封建社会同样是已被取代的私有制社会形态，不在共产主义社会形态内部的阶段序列之中。","C":"资本主义是社会主义将要取代的对象，是共产主义实现前必须跨越的旧社会，不是其低级阶段。","D":"社会主义是共产主义社会的第一阶段，它的充分发展为实现共产主义准备条件，故称必由之路。"},"memoryTip":"同一社会形态两个阶段：社会主义＝低级阶段，共产主义＝高级阶段，二者同属一个形态。"},"20425":{"solution":"共产主义的实现不取决于任何人的主观意愿，而是生产关系一定要适合生产力状况这一规律作用的必然结果，故选B。","optionAnalysis":{"A":"把历史走向归于领袖意志，是英雄史观，违背人民群众是历史创造者的基本原理。","B":"人类社会基本矛盾运动决定了资本主义被社会主义、共产主义取代的历史方向，这是客观规律。","C":"所有人的愿望属于主观范畴，愿望本身不能改变社会形态，历史上也从未有全体一致的愿望。","D":"人民群众是历史创造者，但其意志仍属主观因素，决定历史趋势的是他们从事的物质生产活动及其规律。"},"memoryTip":"凡问“为什么一定能实现”就答“规律”；凡答“意志”“愿望”一律是唯心史观陷阱。"},"20426":{"solution":"马克思不虚构未来社会的蓝图，而是通过剖析资本主义旧世界的内在矛盾，从中发现新社会因素的生长点，这就是马克思主义预见未来社会的方法，故选B。","optionAnalysis":{"A":"空想社会主义者从理性原则出发构想理想王国，脱离现实运动，恰是“通过批判旧世界发现新世界”所反对的做法。","B":"批判旧世界即揭示资本主义基本矛盾及其趋势，从中引出未来社会的特征，这正是马克思主义的方法。","C":"唯物主义范围过宽，旧唯物主义在历史领域仍是唯心主义，不能等同于马克思主义的方法。","D":"唯心主义从观念出发推论历史，与从旧世界矛盾中发现新世界的方法正相反对。"},"memoryTip":"批判旧世界发现新世界＝马克思的方法；从头脑构想蓝图＝空想社会主义，对照记。"},"20427":{"solution":"这句话出自《共产党宣言》，用“自由人的联合体”表达未来社会理想，强调每个人的自由发展是一切人自由发展的条件，故选A。","optionAnalysis":{"A":"《共产党宣言》以这段话收束对未来的展望，“自由人联合体”由此成为共产主义社会的经典表述。","B":"《共产主义原理》是恩格斯1847年以问答体写的纲领草案，内容侧重原理阐释，不含这段名言。","C":"《哥达纲领批判》主要论述共产主义两个阶段和按劳分配、按需分配，与这段表述无关。","D":"《资本论》是剖析资本主义生产方式的政治经济学著作，主题是剩余价值，不是这句论断的出处。"},"memoryTip":"记“宣言收尾即联合体”：自由人联合体这句名言出自《共产党宣言》。"},"20428":{"solution":"“两个决不会”是指无论哪一个社会形态，在它所能容纳的全部生产力发挥出来以前决不会灭亡，新的更高的生产关系在其物质条件成熟以前决不会出现，出自《〈政治经济学批判〉序言》，故选C。","optionAnalysis":{"A":"《共产党宣言》提出“两个必然”，讲资本主义灭亡和社会主义胜利的必然性，与“两个决不会”分属不同著作。","B":"《哥达纲领批判》着重批判拉萨尔主义，阐明共产主义两阶段和分配原则，未提出“两个决不会”。","C":"《〈政治经济学批判〉序言》系统表述唯物史观，正是在此提出生产力与生产关系的“两个决不会”。","D":"《反杜林论》是恩格斯的著作，全面阐述马克思主义三个组成部分，不是“两个决不会”的出处。"},"memoryTip":"两个必然在《宣言》，两个决不会在《政治经济学批判》序言——“必”与“决”分家记。"},"20429":{"solution":"无产阶级的运动是绝大多数人的、为绝大多数人谋利益的运动，其最终指向不是夺取政权或改善待遇，而是消灭阶级、实现共产主义，故选B。","optionAnalysis":{"A":"建立社会主义国家是革命取得的阶段性政权成果，是通往最终目标的一个环节。","B":"共产主义是无产阶级解放斗争的最终目标，也是全部运动方向的归宿。","C":"消灭剥削是社会主义革命的重要任务，属于过程中的目标，小于最终目标。","D":"消除贫困是社会主义建设的现实任务，层次更具体，不能作为最终目标。"},"memoryTip":"最终目标只认“共产主义”；建国家、消灭剥削、消除贫困都只是路上的一站。"},"20430":{"solution":"马克思把社会形态划分为三大阶段：人的依赖关系、以物的依赖性为基础的人的独立性、自由个性。第一种指资本主义以前，人们在血缘和人身依附中结成的直接关系，故选A。","optionAnalysis":{"A":"前资本主义阶段生产力低下，个人依附于氏族、宗法或领主，“人的依赖关系”正是这一历史阶段的特征。","B":"资本主义社会对应的是“以物的依赖性为基础的人的独立性”，人与人的关系通过商品交换间接实现。","C":"社会主义社会已在公有制基础上发展新型人际关系，但仍存在商品交换，不属于马克思所说的第一种形态。","D":"共产主义社会对应“自由个性”，人成为社会关系的主人，与“人的依赖关系”恰是两端。"},"memoryTip":"三形态顺序：人的依赖（前资本主义）→物的依赖（资本主义）→自由个性（共产主义）。"},"20431":{"solution":"在资本主义社会，生产资料私有制和普遍的商品交换使人与人之间的社会联系必须通过物来建立，人依赖商品和货币而不依赖他人，故称“物的依赖性关系”，选B。","optionAnalysis":{"A":"资本主义以前的社会以人身依附和血缘宗法为纽带，占主导的是“人的依赖关系”，与“物的依赖”相反。","B":"商品货币关系普遍化后，人的社会关系被物与物的关系所掩盖，人的独立性以依赖物为基础，正合此表述。","C":"社会主义社会虽仍存在商品交换，但公有制主体地位使人的关系不再以物的依赖为本质特征。","D":"共产主义社会实现“自由个性”，人们共同占有生产资料、自觉支配社会关系，物的依赖已经消除。"},"memoryTip":"看到“物”就想商品货币——物的依赖＝资本主义，它正是商品拜物教的社会根基。"},"20432":{"solution":"国家消亡指政治国家、即作为阶级压迫工具的国家机器消亡。国家的社会管理职能不会消失，而是转为社会自身的公共管理，故选D。","optionAnalysis":{"A":"把国家职能全部否定，会连带否定社会公共管理，而这类职能在共产主义社会将由社会机构承担并保留。","B":"国家机构中承担公共事务的部分不会简单消失，只是性质改变，说“全部机构”消亡过于绝对。","C":"社会管理职能恰恰不消亡，它脱离政治性质后由社会自行行使，把消亡对象搞反了。","D":"消亡的是国家作为阶级统治和压迫机器的政治属性，这是国家消亡的确切含义。"},"memoryTip":"消亡的是“政治国家”，不是管理职能：压迫机器消失，公共管理转为社会自治。"},"20433":{"solution":"共产主义理想是长远目标，必须落到当前实践。现阶段我国处于社会主义初级阶段，为共产主义奋斗就体现为建设中国特色社会主义，故选A。","optionAnalysis":{"A":"中国特色社会主义是通往共产主义的必经阶段，现阶段一切奋斗都汇聚于这一现实运动，符合最高纲领与最低纲领的统一。","B":"直接说“为共产主义而奋斗”停留在口号层面，题干要的是“当前集中体现在”的现实落点。","C":"小康是现代化建设某一阶段的奋斗目标，已实现，且不能涵盖现阶段的全部任务。","D":"构建和谐社会是特定时期的具体任务之一，范围小于建设中国特色社会主义。"},"memoryTip":"远大理想落地＝建设中国特色社会主义：最高纲领靠最低纲领一步步逼近。"},"20434":{"solution":"马克思以人的发展状态划分社会形态，第三阶段是“自由个性”，以人的全面发展和自由个性为特征，对应共产主义社会，故选D。","optionAnalysis":{"A":"资本主义以前是“人的依赖关系”阶段，个人依附于共同体，谈不上自由个性。","B":"资本主义社会处于“以物的依赖性为基础的人的独立性”阶段，人被物支配，尚未达到自由个性。","C":"社会主义社会为自由个性创造条件，但受生产力水平和旧分工残余限制，还不是自由个性的完全实现。","D":"共产主义社会物质条件充分，人摆脱分工束缚和物的支配，自由个性得到真正实现。"},"memoryTip":"“自由个性”是三大形态的终点，只配共产主义；社会主义是创造条件阶段。"},"20435":{"solution":"“两个必然”揭示资本主义灭亡和社会主义胜利的历史趋势，“两个决不会”说明这一趋势的实现需要生产力条件，前者指明方向，后者规定条件，二者内在统一，故选C。","optionAnalysis":{"A":"把二者视为矛盾，是把必然性趋势与实现条件对立起来，前者回答“向哪走”，后者回答“何时走”。","B":"说成两回事，割裂了同一唯物史观结论的两个方面，会导致或否定趋势、或无视条件。","C":"二者统一于唯物史观：必然性通过条件性展开，条件性保证必然性不被冒进扭曲，是内在联系。","D":"内容与形式的关系指同一事物的内在要素与表现方式，二者并非这种结构关系。"},"memoryTip":"两个必然定方向，两个决不会定条件，合起来才完整；说矛盾或两回事都是割裂。"},"20436":{"solution":"党的纲领分最高和最低两层。最高纲领规定最终奋斗方向，即实现共产主义；最低纲领是现阶段的基本纲领。题干问最高纲领，故选A。","optionAnalysis":{"A":"实现共产主义是党的最高理想和最终目标，构成最高纲领，统领各个阶段的最低纲领。","B":"构建和谐社会是一定时期的具体任务，属于阶段性目标，层次低于最高纲领。","C":"“天下为公”是传统思想中的社会理想表述，不是党的纲领用语，也未指明共产主义方向。","D":"“大同世界”出自传统典籍，表达古人对理想社会的向往，与党的最高纲领不是同一概念。"},"memoryTip":"最高纲领只答“共产主义”；和谐、小康、大同、“天下为公”都不是党的纲领表述。"},"20437":{"solution":"共产主义是社会主义充分发展和高度发达后的社会形态，二者同属一个社会形态的两个阶段。因此共产主义只能在社会主义社会充分发展、高度发达的基础上实现，故选A。","optionAnalysis":{"A":"社会主义是共产主义的低级阶段，只有它充分发展，生产力高度发达、旧社会痕迹消失，才能过渡到共产主义。","B":"和谐社会是社会主义社会建设的目标状态，不是独立的社会形态，无法充当共产主义的基础。","C":"小康社会是现代化建设的一个阶段性目标，层次和范围都远小于社会主义社会的充分发展。","D":"自由人的联合体是共产主义社会本身的表述，用共产主义说明共产主义，属同义反复。"},"memoryTip":"题眼是“基础上”：基础只能是社会主义，因为二者是同一形态的两个阶段。"},"20438":{"solution":"必然王国指人被客观规律和物支配的状态，自由王国指人认识并支配规律、成为社会关系主人的状态。二者标示人类社会发展的不同阶段，属历史性概念，故选C。","optionAnalysis":{"A":"时间性概念只标先后顺序，而这两个范畴标示的是社会状态的性质变化，不止于时间刻度。","B":"空间性概念指地域范围，与必然王国、自由王国所刻画的人与规律的关系无关。","C":"两个范畴刻画人类从受必然性支配走向自觉支配社会关系的过程，是标志历史阶段的范畴。","D":"物质性概念指客观实在性，而二者描述的是人的活动状态和社会关系性质，不是物质范畴。"},"memoryTip":"必然王国到自由王国是人类历史的跃迁，抓住“历史性”，别被“时间”“空间”带偏。"},"20439":{"solution":"三大差别指工农差别、城乡差别、脑力劳动与体力劳动的差别，它们归根到底建立在利益差别之上。只有消灭利益差别，三大差别才能真正消除，故选D。","optionAnalysis":{"A":"工农差别本身属于三大差别之一，用其中一项说明“关键”，是以现象解释现象。","B":"城乡差别同样是三大差别的组成部分，不是消灭三大差别的关键所在。","C":"脑体差别也属于三大差别的内容，把它当作关键，逻辑上是以被消除者解释消除。","D":"三大差别背后是利益格局的分野，利益差别消除后，职业和地域分工的对立性才失去基础。"},"memoryTip":"三大差别（工农、城乡、脑体）是现象，利益差别是根子——问“关键”就答利益差别。"},"20440":{"solution":"共产主义社会结束了阶级对立和旧式分工对人的限制，社会发展与个人发展不再彼此排斥，而是互为条件、真正统一，故选A。","optionAnalysis":{"A":"在共产主义社会，人的自由发展与社会进步方向一致，个体发展不再以牺牲他人为条件，二者实现真正统一。","B":"共产主义社会消灭的是旧式固定分工和三大差别，而非一切分工；按能力与需要进行的活动分工仍然存在。","C":"共产主义社会商品货币关系已经消亡，实行各尽所能、按需分配，不存在商品经济的高度发达形态。","D":"劳动在共产主义社会成为生活的第一需要，不再是单纯的谋生手段，这正是与社会主义阶段的区别。"},"memoryTip":"共产主义三改：固定分工改为自觉协作、商品经济改为产品经济、谋生劳动改为第一需要。"},"20441":{"solution":"无产阶级的解放条件与全人类的解放是同一件事。只要还存在剥削、压迫和阶级差别，无产阶级自身就谈不上彻底解放，因此必须使整个社会摆脱这一切，故选C。","optionAnalysis":{"A":"工人阶级与其他劳动者并不因革命而融合为一个阶级，该说法混淆了阶级联合与阶级消亡。","B":"工人阶级同其他阶级在根本利益上一致但并非没有差别，抹掉差别会取消统一战线的必要性。","C":"无产阶级只有消灭一切剥削压迫和阶级差别，才能同时消灭自身受压迫的条件，这正是命题的内涵。","D":"解放不是先后两步的机械操作，而是同一个历史过程：只有解放全人类，才最终解放自己。"},"memoryTip":"这句话的关键是“同一过程”：别人的枷锁不解，自己的枷锁也解不掉，不是分两步走。"},"20442":{"solution":"“各尽所能，按需分配”以生产力高度发达、物质财富极大丰富为前提，是共产主义社会高级阶段的分配原则，与社会主义的按劳分配相区别，故选D。","optionAnalysis":{"A":"原始社会生产力极低，实行的是平均分配，仅能维持生存，不具备按需分配的物质条件。","B":"阶级社会的分配以生产资料私有制为基础，奴隶主、地主、资本家占有他人劳动，与按需分配正相反。","C":"社会主义社会实行各尽所能、按劳分配，以劳动为尺度，尚不具备按需分配的物质前提。","D":"共产主义社会物质财富极大丰富、劳动成为生活第一需要，因而能够实行按需分配。"},"memoryTip":"口诀：社会主义“按劳”，共产主义“按需”；中间差的是物质极大丰富这个前提。"},"20443":{"solution":"马克思主义认为人的发展与社会发展是同一过程的两面：社会发展为个人发展提供条件，个人发展又推动社会进步，二者互为前提和基础，故选D。","optionAnalysis":{"A":"把人的发展归为个人理想、社会发展归为社会目标，割裂了二者的现实统一性，属二元化理解。","B":"个人价值与社会价值是价值论范畴，不能替代人的发展与社会发展的关系问题，属偷换概念。","C":"说成彼此独立，否认了社会条件对个人发展的制约和个人活动对社会进步的推动，与唯物史观相悖。","D":"社会由个人构成并为个人发展创造条件，个人发展又构成社会发展的内容和动力，二者互为前提和基础。"},"memoryTip":"人的发展与社会发展是“同一过程的两面”，关键词是互为前提，不是并行的两条线。"},"20444":{"solution":"科学理想之所以科学，在于它建立在社会发展客观规律之上，具有客观必然性；空想和幻想则脱离现实根据，只是主观想象。这一区别正是二者的根本分野，故选A。","optionAnalysis":{"A":"有无客观必然性是根本分野：科学理想由规律推出并终将实现，空想则没有现实根据。","B":"说法颠倒：马克思主义恰恰拒绝对未来社会作详细描绘，空想社会主义者才热衷于描绘细节蓝图。","C":"空想社会主义也建有理论体系并作过论证，只是论证前提是理性原则而非客观规律，故不构成区别。","D":"空想与幻想恰恰更脱离现实、缺乏现实根据，说其“局限于现实”与事实方向相反。"},"memoryTip":"分野只有一条：有无客观必然性；“理论论证”空想也有，只是前提错了。"},"20445":{"solution":"对未来社会的设想并非马克思主义独有，空想社会主义者、中国古代思想家、资产阶级启蒙学者都描绘过理想社会，故“许多思想家都预见了未来社会”这一提法成立，选D。","optionAnalysis":{"A":"把预见未来的功绩只归给空想社会主义者，无视马克思主义和其他思想家的探索，“只有”过于绝对。","B":"马克思主义经典作家确实科学预见未来，但科学预见不等于唯一预见，其他思想家也有设想。","C":"唯心主义思想家也描绘过理想社会，且预见的正确与否不取决于唯物或唯心这一标签，此项双错。","D":"历史上多种思想流派都提出过未来社会构想，只是科学性程度不同，这一表述准确而不绝对。"},"memoryTip":"凡见“只有……才”，先疑绝对化；预见未来是很多思想家的共同话题，差别在科学性。"},"20446":{"solution":"江泽民这段话讲的是最高纲领与最低纲领的统一。“远大理想”与“现实工作”相对，指向党的最终目标，即共产主义远大理想，故选A。","optionAnalysis":{"A":"与“现实工作”相对的“远大理想”指党的最高理想，即共产主义远大理想，构成前进方向的指引。","B":"中国特色社会主义是现阶段的共同理想，属于“现实工作”所服务的阶段性目标，不是“远大理想”。","C":"个人对美好生活的向往属于个体层面的追求，与党的远大理想不是同一范畴。","D":"职业向往是个人择业问题，层次更具体，与政治意义上的远大理想无关。"},"memoryTip":"题中“远大理想”对“现实工作”：远＝共产主义，近＝中国特色社会主义，两个层次别错位。"},"20447":{"solution":"自由王国指人摆脱盲目必然性支配、自觉支配自身社会关系的状态，只有共产主义社会具备这一条件，此前各社会形态均处于必然王国之中，故选D。","optionAnalysis":{"A":"奴隶社会生产力低下，奴隶人身依附于奴隶主，是典型的必然王国，谈不上自由。","B":"封建社会农民依附土地和地主，社会关系受自然经济支配，仍属必然王国。","C":"资本主义社会受剩余价值规律和商品拜物教支配，人被物统治，依然处于必然王国。","D":"共产主义社会人们共同占有生产资料、自觉组织生产，成为社会关系的主人，进入自由王国。"},"memoryTip":"自由王国只有一站：共产主义；奴隶、封建、资本主义全在必然王国之内。"},"20448":{"solution":"判断分配方式要先看社会形态。“各尽所能，按需分配”以物质财富极大丰富、劳动成为生活第一需要为前提，只在共产主义社会实行，故选D。","optionAnalysis":{"A":"原始社会实行的是维持生存的平均分配，生产力水平不足以支撑按需分配。","B":"阶级社会的分配以私有制和剥削为基础，劳动者所得与其劳动相背离，与按需分配毫不相干。","C":"社会主义社会实行按劳分配，承认劳动差别带来的收入差别，尚未达到按需分配的条件。","D":"共产主义社会具备物质极大丰富的条件，实行各尽所能、按需分配，与按劳分配相区别。"},"memoryTip":"分配随形态走：原始平均、阶级剥削、社会主义按劳、共产主义按需，四级对照记。"},"20449":{"solution":"必然王国与自由王国不是两条可选道路或两种方案，而是人类社会在不同历史阶段呈现的两种状态：前者受必然性支配，后者自觉支配社会关系，故选A。","optionAnalysis":{"A":"二者描述的是社会发展的客观状态差异，前者是人类尚未真正解放的阶段，后者是解放之后的阶段。","B":"选择是主体在多种可能中的取舍，而这两个范畴是历史进程的客观呈现，不由人挑选。","C":"道路指实现目标的具体途径，必然王国并非一条“路”，而是社会状态本身。","D":"理想属主观追求，必然王国是现实状态而非理想，二者不能都归为理想。"},"memoryTip":"题干问“是社会发展的什么”，答“状态”；选道路、选择、理想都换了范畴。"},"20450":{"solution":"自由王国的自由不是为所欲为，而是认识并利用客观规律、摆脱自然和社会关系的盲目奴役，成为自己社会关系的主人。马克思正是在此意义上使用这一范畴，故选D。","optionAnalysis":{"A":"原始社会并不存在绝对自由，人受自然力和社会共同体双重束缚，属于必然王国的最初阶段。","B":"自由以认识和尊重规律为前提，说不再受规律支配，恰恰否定了自由的条件，是唯意志论。","C":"自由竞争资本主义受价值规律和剩余价值规律盲目支配，人被物统治，仍是必然王国。","D":"自由王国指人自觉认识和驾驭规律、摆脱盲目必然性支配，成为自然界和社会关系的主人。"},"memoryTip":"自由的公式：认识必然＋驾驭规律＝自由王国；“不受规律支配”“绝对自由”全是陷阱。"}};
